/** A hand-built state, so a frame assertion is not hostage to whatever a real store happens to hold.
 *  The planted values are the hostile ones: a CJK path, an astral emoji, and an escape that would
 *  clear the screen if it reached the terminal unsanitised. */
function dashFixture(over = {}) {
  return {
    views: {
      changemap: { summary: { title: 'fixture', pending: 2, kept: 3 }, files: [{ rel: '漢字/テスト.ts', cnt: 2, added: 9, removed: 1, status: 'pending' }] },
      list: {
        edits: [
          { id: 1, ts: 1000, tool: 'Edit', file: 'src/a.ts', status: 'pending', added: 4, removed: 1 },
          { id: 2, ts: 2000, tool: 'Edit', file: 'src/\x1b[2J\x1b[1;1Hevil.ts', status: 'kept', added: 1, removed: 0 },
          { id: 3, ts: 3000, tool: 'Edit', file: 'src/🔬scope.ts', status: 'undone', added: 2, removed: 2 },
        ],
      },
      prompts: { prompts: [{ id: 'p1', index: 1, ts: 1000, title: 'do the thing', editIds: [1, 3] }] },
      multitask: {
        agents: [{ session: 's', phase: 'working', phaseConfidence: 'heuristic', diff: { added: 4, removed: 1 }, sparkline: '▁▂▅' }],
        // A workflow run with BOTH shapes the Workflows screen has to render: agents that sit in a
        // declared phase, and agents that do not (the common case on a live run, where the phases come
        // from the script meta while the agents still carry journal keys). One label is DERIVED, so
        // the heuristic marker has something to mark.
        workflows: [
          {
            id: 'wf_fix',
            name: 'roadmap-deep-eval',
            description: 'deep eval of the CLI roadmap',
            phases: ['Find', 'Verify'],
            phaseGroups: [{ title: 'Find', done: 2, total: 2 }, { title: 'Verify', done: 1, total: 2 }],
            agents: [
              { agentId: 'v2:aaaaaaaa', label: 'find:consistency', labelDerived: false, phase: 'Find', done: true, tokens: 12000, durationMs: 240000, edits: 1, added: 5, removed: 2, model: 'Opus 4.8', effort: '', sparkline: [1, 2] },
              { agentId: 'bbbbbbbb', label: 'find:evidence', labelDerived: true, phase: 'Find', done: true, tokens: 31000, durationMs: 540000, edits: 0, added: 0, removed: 0, model: '', effort: '', sparkline: [] },
              { agentId: 'cccccccc', label: 'verify:external', labelDerived: false, phase: 'Verify', done: true, tokens: 88000, durationMs: 1080000, edits: 2, added: 3, removed: 1, model: '', effort: 'high', sparkline: [] },
              { agentId: 'dddddddd', label: null, labelDerived: false, phase: null, agentType: 'workflow-subagent', done: false, tokens: 102000, durationMs: 1320000, edits: 0, added: 0, removed: 0, model: '', effort: '', sparkline: [] },
            ],
            running: true,
            lastActivityMs: 1000,
            agentCount: 6,
            tokens: 601000,
            durationMs: 2760000,
            edits: 3,
            added: 12,
            removed: 3,
            startedTs: 1,
            lastTs: 2,
            sparkline: [1, 3, 2],
          },
        ],
        summary: { active: 1, conflicts: 2 },
      },
      feed: { entries: [{ ts: 1000, label: 'ran tests' }], mode: 'live' },
      risk: { high: 1, count: 2, risky: [{ ts: 1, tool: 'Bash', target: 'rm -rf x', level: 'high', reasons: [] }], outsideWrites: [{ file: '/etc/hosts', count: 1 }] },
      egress: { remote: 1, channels: [{ kind: 'web', target: 'example.com', scope: 'remote', count: 1 }] },
    },
    screen: 'edits',
    cursor: 0,
    scroll: 0,
    session: 'fixture0',
    sessionTitle: 'fixture',
    filter: '',
    status: 'ready',
    error: null,
    confirm: null,
    now: 5_000_000,
    watcherMode: 'native',
    open: new Set(),
    ...over,
  };
}

/** Feed `chunks` through a fresh decoder and collect every event, including the flushed tail. */
function decode(chunks) {
  const d = tui.createDecoder();
  const out = [];
  for (const c of chunks) out.push(...d.push(c));
  out.push(...d.flush());
  return out;
}
const keysOf = (evs) => evs.filter((e) => e.t === 'key' && !e.ctrl && !e.alt).map((e) => e.key);

test('session: the terminal front door — repo-scoped inside a repo, machine-wide newest outside', () => {
  freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const repo = fs.realpathSync(tmpWork());
  makeGitDir(path.join(repo, '.git')); // a workspace
  const desk = fs.realpathSync(tmpWork()); // no .git — "$HOME/Desktop"
  const write = (cwd, id, ts) => {
    const proj = core.projectDir(cwd);
    fs.mkdirSync(proj, { recursive: true });
    const p = path.join(proj, id + '.jsonl');
    fs.writeFileSync(
      p,
      [
        JSON.stringify({ type: 'user', sessionId: id, cwd, timestamp: new Date(ts).toISOString(), message: { role: 'user', content: 'hi' } }),
        JSON.stringify({ type: 'assistant', sessionId: id, timestamp: new Date(ts + 1).toISOString(), message: { role: 'assistant', id: 'm' + id, model: 'claude-opus-4-5', content: [], usage: {} } }),
      ].join('\n') + '\n'
    );
    fs.utimesSync(p, new Date(ts), new Date(ts));
  };
  write(repo, 'repoOld0', 1_000_000);
  write(desk, 'deskStale0', 500_000); // what the old walk-up would have found from the desk
  const other = fs.realpathSync(tmpWork());
  write(other, 'liveNow0', 2_000_000); // the machine-wide newest, in a different workspace
  assert.equal(core.defaultTuiSession(repo), 'repoOld0', 'inside a repo, the workspace rules — even with newer activity elsewhere');
  assert.equal(core.defaultTuiSession(desk), 'liveNow0', 'outside any repo, the machine-wide newest wins over ancestor leftovers');
  // `oak tui --root <dir>` NAMES a workspace: its own session, repo or not, never the newest elsewhere.
  assert.equal(core.defaultTuiSession(desk, true), 'deskStale0', 'a named workspace outside any repo keeps its own session');
  assert.equal(core.defaultTuiSession(fs.realpathSync(tmpWork()), true), null, 'a named workspace with no session adopts none from elsewhere');
});

test('tui/claude: the live tail renders — status row, feed rows, and the hint only when quiet', () => {
  const base = dashFixture();
  const live = {
    ...base,
    // The PANED layout, not the legacy single-screen chrome — the Claude window only exists there.
    panes: {
      minimized: tui.defaultMinimized(120, 48),
      zoom: null,
      focus: 'traces',
      tab: {},
      cursor: {},
      scroll: {},
      sizes: {},
    },
    views: {
      ...base.views,
      sessions: {
        active: 'fixture0',
        sessions: [{ id: 'fixture0', model: 'Opus 4.5', effort: 'high', active: true, tokens: 1234, durationMs: 60000 }],
      },
      multitask: { agents: [{ session: 'fixture0', self: true, phase: 'working', phaseConfidence: 'high' }], summary: {} },
      feed: {
        entries: [
          { ts: 4_990_000, kind: 'action', label: 'Edit src/a.ts', ok: true },
          { ts: 4_995_000, kind: 'reasoning', label: 'said', reasoning: 'now the tests', reasoningKind: 'text' },
          { ts: 4_996_000, kind: 'action', label: 'Bash npm test', ok: false },
        ],
        mode: 'live',
      },
    },
  };
  // 48 rows: tall enough that the Claude window OPENS (it folds below ~40) — every shorter frame
  // test exercises only the folded chip, which is how the whole body branch went untested.
  const frame = tui.renderDashFrame(live, { cols: 120, rows: 48, color: false }).join('\n');
  assert.match(frame, /Opus 4\.5/, 'the status row carries the model');
  assert.match(frame, /Edit src\/a\.ts/, 'a tool call lands in the tail');
  assert.match(frame, /now the tests/, 'assistant reasoning lands in the tail');
  assert.match(frame, /Bash npm test/, 'a failed call still shows');
  assert.ok(!/F8 again/.test(frame), 'a live tail spends no row on the resume hint');
  const quiet = { ...live, views: { ...live.views, feed: { entries: [], mode: 'live' } } };
  const frame2 = tui.renderDashFrame(quiet, { cols: 120, rows: 48, color: false }).join('\n');
  assert.match(frame2, /F8 again/, 'a quiet tail offers the door back to Claude');
});

test('tui/changemap: aggregates by path prefix, so nothing is dropped and every row fits', () => {
  // A top-N ledger looks complete while hiding most of the churn — on a real session its top twenty
  // rows covered less than a fifth of it. A prefix tree instead guarantees that whatever is not on
  // screen is still represented by a visible ancestor carrying its totals.
  const files = [
    { rel: 'packages/core/src/observe.ts', added: 90, removed: 10, cnt: 4, pending: 2, kept: 2, undone: 0, risk: 1 },
    { rel: 'packages/core/src/memory.ts', added: 40, removed: 5, cnt: 2, pending: 0, kept: 2, undone: 0, risk: 0 },
    { rel: 'packages/cli/src/index.ts', added: 20, removed: 2, cnt: 1, pending: 1, kept: 0, undone: 0, risk: 0 },
    { rel: '../elsewhere/thing.md', added: 500, removed: 0, cnt: 9, pending: 0, kept: 9, undone: 0, risk: 0 },
  ];
  const tree = tui.buildMapTree(files);
  assert.equal(tree.files, 4, 'every file is counted');
  assert.equal(tree.churn, 667, 'and the root carries the whole session churn');

  // A path outside the workspace is one row, not a synthetic deep tree — on a real session those are
  // the agent's own harness directories and would otherwise bury the user's code entirely.
  const top = tui.mapRows(tree, new Set());
  const outside = top.find((r) => r.label === tui.OUTSIDE);
  assert.ok(outside, 'files outside the workspace collapse into one named row');
  assert.equal(outside.node.churn, 500, 'carrying their churn, so it is never silently dropped');

  // Collapsed by default: a folded folder still reports its subtree's totals.
  const pkgs = top.find((r) => r.label === 'packages');
  assert.equal(pkgs.node.churn, 167, 'a folded folder reports its whole subtree');
  assert.ok(pkgs.expandable, 'and says it can be opened');

  const opened = tui.mapRows(tree, new Set(['packages']));
  assert.ok(opened.length > top.length, 'opening it reveals children');

  // Width is the invariant that actually breaks: an off-by-one in the column arithmetic puts every
  // row one cell over its budget at every width, which no amount of reading catches — and the pane
  // then wraps every single row onto a continuation line carrying nothing.
  for (const tier of ['ascii', 'safe', 'block']) {
    const g = tui.glyphs(tier);
    for (let cols = 30; cols <= 200; cols++) {
      for (const r of tui.mapRows(tree, new Set(['packages', 'packages/core']))) {
        for (const line of tui.renderMapRow(r, cols, g, 'none')) {
          assert.ok(tui.displayWidth(line) <= cols, `${tier}@${cols}: "${line}" is ${tui.displayWidth(line)} wide`);
        }
      }
      assert.ok(tui.displayWidth(tui.mapHeader(tree, cols, g)) <= cols, `${tier}@${cols}: header fits`);
    }
  }
});

test('tui/changemap: every row states its lines and its review state, and offers the two actions', () => {
  const files = [
    { rel: 'packages/core/src/observe.ts', added: 90, removed: 10, cnt: 4, pending: 2, kept: 2, undone: 0, risk: 1 },
    { rel: 'packages/core/src/memory.ts', added: 40, removed: 5, cnt: 2, pending: 0, kept: 2, undone: 0, risk: 0 },
  ];
  const tree = tui.buildMapTree(files);
  // Added and removed are kept APART all the way up the tree: +900/−4 and +4/−900 are the same churn
  // and are not the same change, and a folder row is what a reviewer decides a whole package on.
  const pkgs = tui.mapRows(tree, new Set())[0];
  assert.equal(pkgs.node.added, 130, 'a folder sums its subtree additions');
  assert.equal(pkgs.node.removed, 15, 'and its deletions, separately');
  assert.equal(pkgs.node.churn, pkgs.node.added + pkgs.node.removed, 'churn stays their sum');
  assert.equal(pkgs.node.pending, 2, 'pending and kept roll up too');
  assert.equal(pkgs.node.kept, 4);

  const g = tui.glyphs('ascii');
  const wide = tui.renderMapRow(pkgs, 120, g, 'none')[0];
  assert.match(wide, /\+130/, 'the row states the lines added');
  assert.match(wide, /−15/, 'and the lines removed');
  assert.match(wide, new RegExp(`2\\${g.pending}`), 'and how many edits are still pending');
  assert.match(wide, new RegExp(`4\\${g.kept}`), 'and how many are accepted');

  // The actions are laid out ONCE and the row is drawn from that layout — a cell pressable somewhere
  // other than where it is drawn reverts a folder the reader never pointed at.
  const acts = tui.mapRowActions(pkgs, 120);
  assert.deepEqual(acts.map((a) => a.action), ['keep', 'undo'], 'both actions at a wide size');
  for (const a of acts) {
    assert.equal(wide.slice(a.x, a.x + a.w), a.label, `${a.action} is drawn exactly at its own cells`);
  }

  // The headings are built from the SAME layout the cells are, so a label can never sit over the
  // wrong number — which is the whole reason they exist.
  const head = tui.mapColumnHeader(120, g);
  for (const [label, cell] of [['added', '+130'], ['removed', '−15'], ['pend', `2${g.pending}`], ['kept', `4${g.kept}`]]) {
    const at = head.indexOf(label);
    assert.ok(at >= 0, `the heading names ${label}`);
    const under = wide.slice(at, at + label.length + 1);
    assert.ok(under.includes(cell.slice(0, 2)), `${label} sits over its own column (found ${JSON.stringify(under)})`);
  }
  // No meter. A proportional bar answered "which is biggest", which the churn-ranked ORDER already
  // answers, and it spent up to 27 columns doing it beside numbers that say the same thing.
  assert.ok(!/[#=─▇]{3}/.test(wide), `no bar in the row, got ${JSON.stringify(wide)}`);

  // Narrow: columns drop WHOLE, cheapest first, and the actions outlive the numbers.
  const seen = new Set();
  for (let cols = 30; cols <= 140; cols++) seen.add(JSON.stringify(tui.mapColumns(cols, 0)));
  assert.ok(seen.size >= 4, `the sweep must actually cross tiers, saw ${seen.size}`);
  assert.equal(tui.mapColumns(34, 0).review, 0, 'the review counts go before the actions do');
  assert.ok(tui.mapRowActions(pkgs, 46).length === 2, 'and the actions survive well past it');

  // A node with nothing pending cannot be kept or undone, and must not look like it can. It offers
  // no button at all now — a dimmed one is still a target the reader will press once.
  const done = tui.buildMapTree([{ rel: 'a/b.ts', added: 1, removed: 0, cnt: 1, pending: 0, kept: 1, undone: 0, risk: 0 }]);
  const row = tui.mapRows(done, new Set())[0];
  const line = tui.renderMapRow(row, 120, g, 'none')[0];
  const cols = tui.mapColumns(120, row.depth);
  assert.equal(tui.mapRowActions(row, 120).length, 0, 'a fully resolved node offers no action');
  assert.equal(
    line.slice(120 - cols.risk - cols.actions, 120 - cols.risk).trim(),
    '',
    '…and its action cells are blank, not a promise it will refuse'
  );
});

test('tui/glyphs: a meter never rounds a real class away, and colour is optional', () => {
  const g = tui.glyphs('ascii');
  // One pending edit in a large folder must still show: rounding it to zero cells would make the
  // meter claim the folder is fully reviewed, which is the opposite of true.
  const bar = tui.meter({ pending: 1, kept: 900, undone: 0 }, 20, g, 'none');
  assert.equal(tui.displayWidth(bar), 20, 'the bar fills its track exactly');
  assert.ok(bar.includes(g.fill.pending), 'and the single pending edit survives the rounding');
  // Shape carries the state, so accept and reject are distinguishable without any colour at all —
  // the answer to red/green colour blindness on this product's two most important states.
  assert.notEqual(g.kept, g.undone);
  assert.equal(tui.tint('x', 'risk', 'none'), 'x', 'NO_COLOR renders no escapes');
  assert.ok(tui.tint('x', 'risk', '256').includes('\x1b['), 'and colour is applied when available');
  assert.equal(tui.colorDepth({ NO_COLOR: '1', TERM: 'xterm-256color' }, true), 'none', 'NO_COLOR wins over TERM');
  // A sparkline from the numeric series the payload actually carries — the previous renderer passed
  // this array through a string coercion and drew nothing at all.
  assert.equal(tui.sparkline([0, 1, 2, 3], g).length, 4);
  assert.equal(tui.sparkline([], g), '');
});

test('tui/input: a non-keystroke sequence never reaches the keymap as a key', () => {
  // Each of these was measured arriving as ordinary letters in a scanner-based decoder. In an
  // application where a, u, A, U and R keep or revert real code, a terminal answering a capability
  // query it was never asked to answer must not be able to revert a session.
  const hostile = [
    ['\x1b[<0;12;34M', 'an SGR mouse click'],
    ['\x1b]11;rgb:1111/2222/3333\x07', 'a background-colour reply'],
    ['\x1b[?2026;2$y', 'a synchronised-output reply'],
    ['\x1b[?1;2c', 'a device-attributes reply'],
    ['\x1bP>|xterm\x1b\\', 'a DCS version report'],
  ];
  for (const [seq, what] of hostile) {
    const evs = decode([seq]);
    assert.deepEqual(keysOf(evs), [], `${what} produces no keys`);
  }
  // Positive control: the instrument can see keys, so the emptiness above is real.
  assert.deepEqual(keysOf(decode(['jkq'])), ['j', 'k', 'q'], 'ordinary characters still arrive');
});

test('tui/input: a sequence split across reads decodes identically to a whole one', () => {
  // The terminal splits wherever it likes. A decoder that re-scans each chunk sees `["\x1b[", "A"]`
  // as the letter A — which in this application is "keep everything".
  const whole = [
    '\x1b[A', '\x1bOB', '\x1b[1;5C', '\x1b[3~', '\x1b[<64;5;7M',
    '\x1b[200~pasted U text\x1b[201~', '\x1b]11;rgb:0/0/0\x07', '\x1b[I', 'x',
  ];
  for (const seq of whole) {
    const want = JSON.stringify(decode([seq]));
    for (let i = 1; i < seq.length; i++) {
      const split = [seq.slice(0, i), seq.slice(i)];
      assert.equal(JSON.stringify(decode(split)), want, `${JSON.stringify(seq)} split at ${i} must decode the same`);
    }
  }
});

test('tui/input: a paste is one event, and its end marker can arrive late', () => {
  // Two failures this pins. A paste decoded as keystrokes runs its content through the keymap —
  // pasting a path containing U then y would bulk-undo the session. And losing a split end marker
  // strands the decoder in paste mode, after which every keystroke is silently swallowed forever.
  const one = decode(['\x1b[200~rm -rf U\x1b[201~']);
  assert.deepEqual(keysOf(one), [], 'nothing inside a paste reaches the keymap');
  assert.deepEqual(one.filter((e) => e.t === 'paste').map((e) => e.text), ['rm -rf U']);

  const late = decode(['abc\x1b[200~xy\x1b[', '201~', 'jkq']);
  assert.deepEqual(late.filter((e) => e.t === 'paste').map((e) => e.text), ['xy'], 'the paste body is exact');
  assert.deepEqual(keysOf(late), ['a', 'b', 'c', 'j', 'k', 'q'], 'and the decoder is not stuck — later keys still arrive');
});

test('tui/input: mouse reports decode to zero-based cells, and a lone ESC needs the flush', () => {
  const [m] = decode(['\x1b[<0;12;34M']);
  assert.equal(m.t, 'mouse');
  assert.deepEqual([m.kind, m.col, m.row], ['down', 11, 33], 'the wire is 1-based; callers get cells');
  assert.equal(decode(['\x1b[<64;1;1M'])[0].kind, 'wheel-up');
  // ESC alone is the Escape key only once nothing follows it — otherwise every arrow key would first
  // fire an Escape.
  const d = tui.createDecoder();
  assert.deepEqual(d.push('\x1b'), [], 'held, not guessed');
  assert.equal(d.pending(), '\x1b');
  assert.deepEqual(d.flush().map((e) => e.key), ['escape']);
});

test('tui/writer: while the terminal is a child’s, no byte leaks — and resume opens the gate', () => {
  const bytes = [];
  const w = tui.createGatedWriter((s) => bytes.push(s));
  assert.ok(w.write('frame 1'), 'open gate: the write flows');
  w.suspend();
  // The async completions that fire during a handover — a views payload, the debounced diff fetch,
  // a window resize — all end in a paint. Each must be REFUSED, not queued: the child owns the
  // screen, and a deferred frame would replay stale bytes over whatever it left there on resume.
  assert.equal(w.write('views payload paint'), false, 'refused, not queued');
  assert.equal(w.write('diff debounce paint'), false);
  assert.equal(w.write('resize paint'), false);
  assert.ok(w.suspended(), 'the gate reports its own state');
  w.resume();
  assert.ok(!w.suspended());
  assert.ok(w.write('the one catch-up frame'));
  assert.deepEqual(bytes, ['frame 1', 'the one catch-up frame'], 'exactly what the gate let through, in order');
});

test('tui/writer: every terminal byte in the runtime goes through the gate', () => {
  // The suspend gate only means anything if there is no way around it. This reads the runtime's
  // SOURCE and holds the number of direct `process.stdout.write(` calls at exactly one — the gate's
  // own sink. A second call site is a path that can paint over a suspended terminal, which is the
  // two-overlay corruption the gate exists to prevent. (`restore()` writes via fs.writeSync on
  // purpose — the exit path must hand back a working terminal even mid-suspension — and stderr is
  // untouched: crash reports print after restore, to a terminal that is already back.)
  const src = fs.readFileSync(path.resolve(__dirname, '../../tui/src/app.ts'), 'utf8');
  const calls = src.match(/process\.stdout\.write\(/g) ?? [];
  assert.equal(calls.length, 1, 'exactly one direct write: the gated sink');
  const sinkLine = src.split('\n').find((l) => l.includes('process.stdout.write('));
  assert.ok(sinkLine.includes('createGatedWriter'), 'and that one call is the gate’s sink');
});

test('tui/backend: the diff fetch asks for RAW bytes — colour belongs to whoever prints', () => {
  // The band regression's actual site, and it has no unit seam (backend.diff spawns/reads a real
  // store), so it is pinned at the source. `coloredDiff(session, rec, true)` hands the re-renderer
  // a foreground-coloured patch, which richdiff then classifies as all-context: no bands, headers
  // leaking, gutter numbering everything. The parser now strips SGR defensively (see the
  // ALREADY-COLOURED test), but the fetch itself must not ask for colour in the first place.
  const src = fs.readFileSync(path.resolve(__dirname, '../../tui/src/backend.ts'), 'utf8');
  const calls = src.match(/coloredDiff\([^)]*\)/g) ?? [];
  assert.equal(calls.length, 1, 'one diff fetch');
  assert.match(calls[0], /,\s*false\s*\)$/, `the TUI fetches an UNCOLOURED patch: ${calls[0]}`);
});

test('groups: an id set must be expanded, or a collapsed row half-resolves', () => {
  // What a surface shows as ONE row is often several raw records — reviewEdits collapses a same-code
  // chain into one unit and labels it with the most recent member's id. The `--ids` path is
  // group-unaware by design (it acts on raw records), so a surface that sends the displayed id alone
  // resolves one member and strands the others at an intermediate state no view can name. This pins
  // the expansion every id-set caller owes, using the same helper the single-id verbs use.
  freshHome();
  const S = 'grpexp';
  const F = path.join(tmpWork(), 'chain.js');
  const a = seedEdit(S, F, 'a\n', 'a\nb\n');
  const b = seedEdit(S, F, 'a\nb\n', 'a\n'); // net zero — collapses with the first

  const units = core.reviewEdits(S);
  assert.equal(units.length, 1, 'the chain is ONE review unit');
  assert.equal(units[0].id, b, 'labelled with the most recent member');

  const expanded = core.groupMembers(S, units[0].id);
  assert.deepEqual([...expanded].sort((x, y) => x - y), [a, b], 'expansion recovers every member');

  core.setStatusMany(S, expanded, 'kept');
  assert.equal(core.readLog(S).filter((r) => r.status === 'pending').length, 0, 'so nothing is left behind');

  // Positive control: without expansion the defect reappears, which is what makes the assertion above
  // meaningful rather than a restatement of setStatusMany.
  freshHome();
  const S2 = 'grpexp2';
  const F2 = path.join(tmpWork(), 'chain2.js');
  seedEdit(S2, F2, 'a\n', 'a\nb\n');
  const rep = seedEdit(S2, F2, 'a\nb\n', 'a\n');
  core.setStatusMany(S2, [rep], 'kept');
  assert.equal(core.readLog(S2).filter((r) => r.status === 'pending').length, 1, 'the unexpanded id strands a member');
});

test('acp: a partial record refuses undo by its own rule — and the file is untouched', () => {
  freshHome();
  const S = 'acppartial';
  const F = path.join(tmpWork(), 'x.py');
  core.ensureStore(S);
  // The ACP partial shape: the agent sent only the NEW text. beforeBlob null here means the
  // before-state is UNKNOWN — without `partial`, this exact shape means "file created", whose undo
  // DELETES the file. That near-miss is what this test pins.
  const after = core.writeBlob(S, Buffer.from('new content\n'));
  const id = core.nextId(S);
  core.appendLog(S, {
    id, ts: 1000, tool: 'Edit', file: F, beforeBlob: null, afterBlob: after,
    status: 'pending', source: 'acp', acpSessionId: 'acp-sess-1', partial: true,
  });
  fs.writeFileSync(F, 'new content\n'); // disk as the agent left it
  const res = core.undoEdit(S, id);
  assert.equal(res.ok, false, 'undo refuses');
  assert.match(res.message, /before-(content|state)/, 'and states the ACP reason');
  assert.ok(fs.existsSync(F), 'the file survives — a false "create" undo would have deleted it');
  // THE FORCE PATH refuses too: `undo <id> --force` routes to restoreFile directly, which used to
  // treat beforeBlob null as "created" and unlink the file — the unrecoverable direction.
  const forced = core.restoreFile(S, id);
  assert.equal(forced.ok, false, '--force refuses the same way');
  assert.match(forced.message, /--force included/);
  assert.ok(fs.existsSync(F), 'and the file still survives');
  const reforced = core.reapplyFile(S, id);
  assert.equal(reforced.ok, false, 'redo --force refuses symmetrically');
  const rec = core.readLog(S)[0];
  assert.equal(rec.source, 'acp');
  assert.equal(rec.acpSessionId, 'acp-sess-1');
  core.setStatusMany(S, [id], 'kept');
  assert.equal(core.readLog(S)[0].status, 'kept', 'review-only still means reviewable: keep works');
});

test('acp: one partial member taints its whole unit — the group undo refuses too', () => {
  freshHome();
  const S = 'acptaint';
  const F = path.join(tmpWork(), 'y.py');
  core.ensureStore(S);
  // Member 1 is partial (after = v1, before unknown); member 2 is a normal record chained onto it
  // (v1 → v2, rewriting the same line — same code, same turn, adjacent). The unit's synthetic pair
  // would read (null, v2) — "created", undoable, WRONG. The taint keeps it review-only.
  const v1 = core.writeBlob(S, Buffer.from('v1\n'));
  const v2 = core.writeBlob(S, Buffer.from('v2\n'));
  const a = core.nextId(S);
  core.appendLog(S, { id: a, ts: 1000, tool: 'Edit', file: F, beforeBlob: null, afterBlob: v1, status: 'pending', source: 'acp', partial: true });
  const b = core.nextId(S);
  core.appendLog(S, { id: b, ts: 1001, tool: 'Edit', file: F, beforeBlob: v1, afterBlob: v2, status: 'pending', source: 'acp' });
  fs.writeFileSync(F, 'v2\n');
  const units = core.reviewEdits(S).filter((r) => r.status === 'pending');
  assert.equal(units.length, 1, 'the chain is one review unit');
  assert.equal(units[0].partial, true, 'and it wears the taint');
  const res = core.undoGroup(S, units[0].id);
  assert.equal(res.ok, false, 'the unit undo refuses');
  assert.ok(fs.existsSync(F), 'and the file is untouched');
});

test('undo: a unit refused for a partial member names that member and its reason, --force included', () => {
  // The unit's record is its newest member's, so the refusal named the newest edit and a generic reason:
  // "edit #2 has an uncertain before-state (missing capture evidence)" for a unit whose #1 was partial.
  freshHome();
  const S = 'partial-named';
  const F = path.join(tmpWork(), 'z.py');
  core.ensureStore(S);
  const a = core.nextId(S);
  core.appendLog(S, { id: a, ts: 1000, tool: 'Edit', file: F, beforeBlob: null, afterBlob: core.writeBlob(S, Buffer.from('x = 1\n')), status: 'pending', partial: true, uncertainty: 'Overlapping tool calls share this capture interval' });
  const b = core.nextId(S);
  core.appendLog(S, { id: b, ts: 1001, tool: 'Edit', file: F, beforeBlob: core.writeBlob(S, Buffer.from('x = 1\n')), afterBlob: core.writeBlob(S, Buffer.from('x = 2\n')), status: 'pending' });
  fs.writeFileSync(F, 'x = 2\n');
  assert.deepEqual(core.groupMembers(S, b), [a, b], 'the fixture forms one unit');
  const named = new RegExp(`^edit #${a} has an uncertain before-state \\(Overlapping tool calls share this capture interval\\)`);
  for (const r of [core.undoGroup(S, b), core.restoreFile(S, b)]) {
    assert.equal(r.ok, false);
    assert.match(r.message, named);
  }
  assert.match(core.restoreFile(S, b).message, /--force included/);
  assert.equal(fs.readFileSync(F, 'utf8'), 'x = 2\n', 'nothing was written');
});

test('acp: prompt_id from the hook payload lands as promptId, and its absence stays silent', () => {
  freshHome();
  const W = tmpWork();
  const F = path.join(W, 'a.js');
  const S = 'promptid';
  fs.writeFileSync(F, 'old\n');
  const payload = (extra) => ({ session_id: S, cwd: W, tool_name: 'Edit', tool_input: { file_path: F }, ...extra });
  // Driven through the REAL hook pipeline, exactly as Claude Code ≥2.1.196 delivers it.
  core.handleHookPayload(payload({ prompt_id: 'p-123', hook_event_name: 'PreToolUse' }));
  fs.writeFileSync(F, 'new\n');
  core.handleHookPayload(payload({ prompt_id: 'p-123', hook_event_name: 'PostToolUse' }));
  let log = core.readLog(S);
  assert.equal(log.length, 1);
  assert.equal(log[0].promptId, 'p-123', 'the harness prompt id lands on the record');
  assert.equal(log[0].source, 'hook');
  // An older harness sends no prompt_id: the record simply lacks the field — nothing breaks or lies.
  core.handleHookPayload(payload({ hook_event_name: 'PreToolUse' }));
  fs.writeFileSync(F, 'newer\n');
  core.handleHookPayload(payload({ hook_event_name: 'PostToolUse' }));
  log = core.readLog(S);
  assert.equal(log.length, 2);
  assert.equal('promptId' in log[1], false, 'absent means absent — no empty-string placeholder');
});

// --- codex-native capture: hooks + rollout mining + installer ------------------------------------
// Payload shapes below are the REAL ones a live codex 0.147.0 sent during the isolated-CODEX_HOME
// spike (2026-08-13): Claude's field dialect (session_id/cwd/hook_event_name/tool_name/tool_input)
// plus codex's additions (turn_id, model, permission_mode, transcript_path → the rollout).

test('codex: patch headers parse — update/add/delete/move — and the patch text is found wherever it hides', () => {
  const patch = [
    '*** Begin Patch',
    '*** Update File: src/scale.py',
    '@@',
    '-def scale(values):',
    '+def scale(values):  # changed',
    '*** Move to: src/rescale.py',
    '*** Add File: src/util.py',
    '+def clamp(v, lo, hi):',
    '*** Delete File: junk.txt',
    '*** End Patch',
  ].join('\n');
  const entries = core.parseCodexPatch(patch);
  assert.deepEqual(entries, [
    { op: 'update', file: 'src/scale.py', moveTo: 'src/rescale.py' },
    { op: 'add', file: 'src/util.py' },
    { op: 'delete', file: 'junk.txt' },
  ]);
  // Where the text hides: {patch} (measured on the wire), {command: [...]} and {command: str} (the
  // source's block-message path), {input}. Anything else is null — the caller leaves a loud marker.
  assert.equal(core.extractPatchText({ patch }), patch);
  assert.equal(core.extractPatchText({ command: ['apply_patch', patch] }), patch);
  assert.equal(core.extractPatchText({ command: patch }), patch);
  assert.equal(core.extractPatchText({ input: patch }), patch);
  assert.equal(core.extractPatchText({ command: 'echo hi' }), null);
  assert.equal(core.extractPatchText(null), null);
});

test('codex: hook payloads drive the REAL capture — a Bash pair and a multi-file apply_patch', () => {
  freshHome();
  const W = tmpWork();
  const S = 'cxhooks1';
  const base = {
    session_id: S,
    transcript_path: path.join(W, 'rollout-fake.jsonl'),
    cwd: W,
    model: 'gpt-oss:20b',
    permission_mode: 'bypassPermissions',
    turn_id: 'turn-1',
  };
  // The Bash pair, exactly as measured: Pre snapshots, the command mutates disk, Post diffs.
  core.handleCodexHookPayload({ ...base, hook_event_name: 'PreToolUse', tool_name: 'Bash', tool_input: { command: 'printf "spike" > note.txt' }, tool_use_id: 'call_1' });
  fs.writeFileSync(path.join(W, 'note.txt'), 'spike');
  core.handleCodexHookPayload({ ...base, hook_event_name: 'PostToolUse', tool_name: 'Bash', tool_input: { command: 'printf "spike" > note.txt' }, tool_response: '', tool_use_id: 'call_1' });
  let log = core.readLog(S);
  const bash = log.find((r) => r.file.endsWith('note.txt'));
  assert.ok(bash, 'the shell-driven create was captured');
  assert.equal(bash.tool, 'Bash');
  assert.equal(bash.source, 'hook');
  assert.equal(bash.promptId, 'turn-1', "codex's turn_id IS the prompt id");

  // apply_patch: one hook call, N files — each runs the same Pre/Post staging every edit runs.
  const main = path.join(W, 'main.py');
  fs.writeFileSync(main, 'print("hi")\n');
  const patch = ['*** Begin Patch', '*** Update File: main.py', '@@', '-print("hi")', '+print("hi")  # tagged', '*** Add File: util.py', '+def f(): pass', '*** End Patch'].join('\n');
  core.handleCodexHookPayload({ ...base, turn_id: 'turn-2', hook_event_name: 'PreToolUse', tool_name: 'apply_patch', tool_input: { patch }, tool_use_id: 'call_2' });
  fs.writeFileSync(main, 'print("hi")  # tagged\n'); // codex applies its patch…
  fs.writeFileSync(path.join(W, 'util.py'), 'def f(): pass\n');
  core.handleCodexHookPayload({ ...base, turn_id: 'turn-2', hook_event_name: 'PostToolUse', tool_name: 'apply_patch', tool_input: { patch }, tool_response: 'Success.', tool_use_id: 'call_2' });
  log = core.readLog(S);
  const upd = log.find((r) => r.file === core.canonPath(main));
  assert.ok(upd, 'the updated file recorded');
  assert.equal(core.blobText(S, upd.beforeBlob), 'print("hi")\n', 'with its REAL before content');
  assert.equal(core.blobText(S, upd.afterBlob), 'print("hi")  # tagged\n');
  const add = log.find((r) => r.file.endsWith('util.py'));
  assert.ok(add && add.beforeBlob === null, 'the added file recorded as a create');
  assert.equal(add.promptId, 'turn-2');

  // A payload whose patch text is unrecoverable leaves a MARKER, never a silent miss.
  core.handleCodexHookPayload({ ...base, hook_event_name: 'PostToolUse', tool_name: 'apply_patch', tool_input: { weird: true }, tool_use_id: 'call_3' });
  const skips = core.readSkips(S);
  assert.ok(skips.some((k) => k.file === '<apply-patch>'), 'unparseable apply_patch is surfaced, not swallowed');

  // agent.json: the session self-identifies, with the rollout path the hooks reported.
  const meta = core.readCodexAgentMeta(S);
  assert.equal(meta.agent, 'codex');
  assert.equal(meta.model, 'gpt-oss:20b');
  assert.equal(meta.transcriptPath, base.transcript_path);
});

test('codex: agent.json is replaced whole (tmp + rename) and private (0600), never rewritten in place (0.11.0)', () => {
  // Written in place, a reader could find it half written (no Codex session at all), and a new file took the default
  // mode in a store whose files are all 0600.
  freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const S = 'cx-agent-meta';
  const cwd = tmpWork();
  core.ensureStore(S);
  const file = path.join(core.storeDir(S), 'agent.json');
  fs.writeFileSync(file, JSON.stringify({ agent: 'codex', cwd, model: 'gpt-old', updated: 1 }));
  fs.chmodSync(file, 0o644); // as an earlier build left it
  const renamed = [];
  const rename = fs.renameSync;
  fs.renameSync = function (a, b, ...rest) { renamed.push(String(b)); return rename.call(this, a, b, ...rest); };
  try {
    core.handleCodexHookPayload({ session_id: S, cwd, hook_event_name: 'SessionStart', source: 'startup', model: 'gpt-new' });
  } finally {
    fs.renameSync = rename;
  }
  assert.equal(core.readCodexAgentMeta(S).model, 'gpt-new', 'control: the change is recorded');
  assert.ok(renamed.includes(file), 'the new file is renamed over the old one');
  if (process.platform !== 'win32') assert.equal(fs.statSync(file).mode & 0o777, 0o600, 'and is private');
  assert.deepEqual(fs.readdirSync(core.storeDir(S)).filter((n) => n.startsWith('agent.json.')), [], 'no temporary file is left');
});

test('codex: Stop drops a Pre whose Post never came, so the next edit of that file is clean', () => {
  freshHome();
  const W = tmpWork();
  const S = 'cxstop1';
  const base = { session_id: S, cwd: W, model: 'gpt-oss:20b', turn_id: 'turn-1' };
  const main = path.join(W, 'main.py');
  fs.writeFileSync(main, 'print("hi")\n');
  const patch = ['*** Begin Patch', '*** Update File: main.py', '@@', '-print("hi")', '+print("hi")  # tagged', '*** End Patch'].join('\n');
  // A patch that was denied: Pre ran, Post never will.
  core.handleCodexHookPayload({ ...base, hook_event_name: 'PreToolUse', tool_name: 'apply_patch', tool_input: { patch }, tool_use_id: 'call_denied' });
  core.handleCodexHookPayload({ ...base, hook_event_name: 'Stop' });
  const staging = path.join(core.storeDir(S), 'staging');
  assert.deepEqual(fs.readdirSync(staging), [], 'the turn is over, so the abandoned snapshot is dropped');
  // The next turn edits the same file for real.
  const next = { ...base, turn_id: 'turn-2', tool_name: 'apply_patch', tool_input: { patch }, tool_use_id: 'call_real' };
  core.handleCodexHookPayload({ ...next, hook_event_name: 'PreToolUse' });
  fs.writeFileSync(main, 'print("hi")  # tagged\n');
  core.handleCodexHookPayload({ ...next, hook_event_name: 'PostToolUse', tool_response: 'Success.' });
  const rec = core.readLog(S).find((r) => r.file === core.canonPath(main));
  assert.deepEqual([rec.attribution, rec.partial ?? false], ['correlated', false], 'not marked as overlapping the denied call, so undo stays available');
});

test('codex: lifecycle events land in the sidecar — and an ambient session stays hooks-only', () => {
  freshHome();
  const S = 'cxlife1';
  const base = { session_id: S, cwd: '/tmp/x', model: 'gpt-oss:20b', turn_id: 't-1' };
  core.handleCodexHookPayload({ ...base, hook_event_name: 'SessionStart', source: 'startup' });
  core.handleCodexHookPayload({ ...base, hook_event_name: 'UserPromptSubmit', prompt: 'Create note.txt' });
  core.handleCodexHookPayload({ ...base, hook_event_name: 'PermissionRequest', tool_name: 'Bash', tool_input: { command: 'rm -rf x' }, tool_use_id: 'call_9' });
  core.handleCodexHookPayload({ ...base, hook_event_name: 'PreCompact' });
  core.handleCodexHookPayload({ ...base, hook_event_name: 'SubagentStart', subagent: { id: 'sub-1' } });
  const events = core.readCaptureEvents(S);
  const kinds = events.map((e) => e.kind);
  assert.deepEqual(kinds, ['agent_session', 'turn_start', 'permission_request', 'compact', 'subagent']);
  const turn = events.find((e) => e.kind === 'turn_start').payload;
  assert.equal(turn.promptId, 't-1');
  assert.equal(turn.prompt, 'Create note.txt');
  const perm = events.find((e) => e.kind === 'permission_request').payload;
  assert.equal(perm.toolCall.toolCallId, 'call_9');
  // The tier: a sidecar written by HOOKS (no session_open — only the drive writes that) is not a
  // drive. Without this, every ambient codex session would wear a drive badge it never earned.

});

test('codex: rollout mining — tokens with the cache split, model+effort, prompts, originator', () => {
  freshHome();
  const dir = tmpWork();
  const S = 'cxroll01';
  const rollout = path.join(dir, `rollout-2026-08-13T12-00-00-${S}.jsonl`);
  const lines = [
    { timestamp: 't', type: 'session_meta', payload: { id: S, session_id: S, cwd: '/w/repo', originator: 'codex_exec', model_provider: 'ollama' } },
    { type: 'event_msg', payload: { type: 'user_message', message: 'Add a clamp helper' } },
    { type: 'event_msg', payload: { type: 'task_started', turn_id: 't-1' } },
    { type: 'response_item', payload: { type: 'function_call', name: 'exec_command', arguments: '{"cmd":"ls"}' } },
    { type: 'event_msg', payload: { type: 'token_count', info: { total_token_usage: { input_tokens: 1000, cached_input_tokens: 200, cache_write_input_tokens: 50, output_tokens: 300, reasoning_output_tokens: 0, total_tokens: 1350 } } } },
    { type: 'event_msg', payload: { type: 'agent_message', message: 'Done.' } },
    { type: 'turn_context', payload: { type: 'thread_settings_applied', thread_settings: { model: 'gpt-oss:20b', model_provider_id: 'ollama', model_reasoning_effort: 'low' } } },
  ];
  fs.writeFileSync(rollout, lines.map((l) => JSON.stringify(l)).join('\n') + '\n{"torn'); // torn tail tolerated
  const r = core.readCodexRollout(rollout);
  assert.equal(r.sessionId, S);
  assert.equal(r.originator, 'codex_exec');
  assert.equal(r.model, 'gpt-oss:20b');
  assert.equal(r.effort, 'low');
  assert.equal(r.prompts[0], 'Add a clamp helper');
  assert.equal(r.turns, 1);
  assert.equal(r.toolCalls.length, 1);
  // Observatory token semantics: new work = (input - cacheRead) + cacheWrite + output; the split rides along.
  assert.deepEqual(r.tokens, { total: 800 + 50 + 300, input: 1000, output: 300, cacheRead: 200, cacheWrite: 50 });

  // Discovery: agent.json's transcript path wins; the sessions-tree scan is the fallback.
  const prevCodexHome = process.env.CODEX_HOME;
  const ch = tmpWork();
  process.env.CODEX_HOME = ch;
  try {
    const shard = path.join(ch, 'sessions', '2026', '08', '13');
    fs.mkdirSync(shard, { recursive: true });
    fs.copyFileSync(rollout, path.join(shard, `rollout-2026-08-13T12-00-00-${S}.jsonl`));
    assert.equal(core.findCodexRollout(S), path.join(shard, `rollout-2026-08-13T12-00-00-${S}.jsonl`), 'found by filename suffix in the sharded tree');
  } finally {
    if (prevCodexHome === undefined) delete process.env.CODEX_HOME;
    else process.env.CODEX_HOME = prevCodexHome;
  }
});

test('models: ollama listing parses newest-first, and the codex rewire is surgical', () => {
  // The listing half: ollama's /api/tags shape, newest pull first, junk tolerated.
  const tags = JSON.stringify({ models: [
    { name: 'qwen3:latest', size: 5e9, modified_at: '2026-08-01T00:00:00Z' },
    { name: 'laguna-xs.2:latest', size: 23e9, modified_at: '2026-08-14T00:00:00Z' },
    { bogus: true },
  ] });
  const list = core.parseOllamaTags(tags);
  assert.deepEqual(list.map((m) => m.name), ['laguna-xs.2:latest', 'qwen3:latest'], 'newest first, junk dropped');
  assert.deepEqual(core.parseOllamaTags('not json'), [], 'garbage parses to an empty list, never a throw');

  // The rewire half: model/model_provider replaced IN PLACE at top level, everything else
  // byte-for-byte, appended keys spliced BEFORE the first table (a key after [hooks.state.x]
  // would silently belong to that table).
  const cfg = '# mine\nmodel = "gpt-oss:20b"  # local\napproval_policy = "on-request"\n\n[hooks.state."k"]\ntrusted_hash = "sha256:aa"\n';
  const next = core.rewireCodexConfigText(cfg, 'laguna-xs.2');
  assert.ok(next.includes('model = "laguna-xs.2"'), 'model replaced');
  assert.ok(next.includes('model_provider = "ollama"'), 'provider appended');
  assert.ok(next.includes('# mine') && next.includes('approval_policy = "on-request"'), 'user lines survive');
  assert.ok(next.includes('trusted_hash = "sha256:aa"'), 'foreign tables survive');
  assert.ok(next.indexOf('model_provider') < next.indexOf('[hooks.state'), 'appended keys stay TOP-LEVEL');
  // A model key inside a table is NOT the default and must not be rewritten.
  const tabled = '[profiles.x]\nmodel = "other"\n';
  const next2 = core.rewireCodexConfigText(tabled, 'qwen3');
  assert.ok(next2.includes('model = "qwen3"') && next2.includes('model = "other"'), 'the table key is untouched; the top-level key is added');
  // Idempotent: wiring the same model twice changes nothing.
  assert.equal(core.rewireCodexConfigText(next, 'laguna-xs.2'), next, 'same model twice is a no-op');

  // End-to-end against a real file, CODEX_HOME-isolated: .bak on first touch, read-back agrees.
  const prevCodexHome = process.env.CODEX_HOME;
  const ch = tmpWork();
  process.env.CODEX_HOME = ch;
  try {
    fs.writeFileSync(path.join(ch, 'config.toml'), cfg);
    const r = core.wireCodexModel('laguna-xs.2');
    assert.ok(r.changed && r.previous === 'gpt-oss:20b' && r.backupPath, 'changed, previous named, backup made');
    assert.deepEqual(core.codexConfiguredModel(), { model: 'laguna-xs.2', provider: 'ollama' });
    assert.equal(fs.readFileSync(r.backupPath, 'utf8'), cfg, 'the .bak is the pre-touch original');
    assert.equal(core.wireCodexModel('laguna-xs.2').changed, false, 'and the rewire is idempotent');
  } finally {
    if (prevCodexHome === undefined) delete process.env.CODEX_HOME;
    else process.env.CODEX_HOME = prevCodexHome;
  }
});

test('models: plain init wires only when nothing chooses the model, and uninstall removes exactly its lines', () => {
  const prevCodexHome = process.env.CODEX_HOME;
  const ch = tmpWork();
  process.env.CODEX_HOME = ch;
  const cfgPath = path.join(ch, 'config.toml');
  try {
    // Every way a user chooses codex's model counts, not just a top-level `model`.
    assert.equal(core.codexModelChoice(), null, 'no config: nothing chosen');
    for (const [text, said] of [
      ['model = "gpt-oss:20b"\n', 'gpt-oss:20b'],
      ["model = 'gpt-5'  # single-quoted\n", "'gpt-5'"],
      ['model_provider = "azure"\n', 'set by model_provider = "azure"'],
      ['profile = "work"\n\n[profiles.work]\nmodel = "gpt-5-codex"\n', 'set by profile = "work"'],
      ['[profiles.work]\nmodel = "gpt-5-codex"\n', 'set by a [profiles] table'],
      ['# mine\napproval_policy = "on-request"\n', null],
      ['[hooks.state."k"]\nmodel = "not top-level"\n', null],
    ]) {
      fs.writeFileSync(cfgPath, text);
      assert.equal(core.codexModelChoice(), said, JSON.stringify(text));
    }
    fs.writeFileSync(path.join(ch, 'work.config.toml'), 'model = "gpt-5-codex"\n');
    assert.equal(core.codexModelChoice(), 'set by the profile file work.config.toml', 'a codex 0.156 profile file is a choice');
    fs.rmSync(path.join(ch, 'work.config.toml'));

    // init's wiring: marked lines, and a backup that is not the hook installer's config.toml.bak.
    const original = '# mine\napproval_policy = "on-request"\n\n[hooks.state."k"]\ntrusted_hash = "sha256:aa"\n';
    fs.writeFileSync(cfgPath, original);
    fs.writeFileSync(cfgPath + '.bak', 'the hook installer backup\n');
    const r = core.wireCodexModel('llama3.2:latest', true);
    assert.equal(r.backupPath, cfgPath + '.oak-model.bak');
    assert.equal(fs.readFileSync(r.backupPath, 'utf8'), original);
    assert.equal(fs.readFileSync(cfgPath + '.bak', 'utf8'), 'the hook installer backup\n', 'config.toml.bak is not overwritten');
    const wired = fs.readFileSync(cfgPath, 'utf8');
    assert.ok(wired.includes(`model = "llama3.2:latest" ${core.CODEX_MODEL_MARKER}\nmodel_provider = "ollama" ${core.CODEX_MODEL_MARKER}\n[hooks.state`), wired);
    assert.deepEqual(core.codexConfiguredModel(), { model: 'llama3.2:latest', provider: 'ollama' }, 'the marker does not hide the model');
    assert.equal(core.unwireCodexModel(), 'llama3.2:latest');
    assert.equal(fs.readFileSync(cfgPath, 'utf8'), original, 'uninstall restores the file byte for byte');
    assert.equal(core.unwireCodexModel(), null, 'and a second uninstall finds nothing');

    // `models use` takes the lines over: they lose the marker, and uninstall leaves them.
    core.wireCodexModel('llama3.2:latest', true);
    core.wireCodexModel('qwen3');
    assert.equal(core.unwireCodexModel(), null);
    assert.deepEqual(core.codexConfiguredModel(), { model: 'qwen3', provider: 'ollama' });
  } finally {
    if (prevCodexHome === undefined) delete process.env.CODEX_HOME;
    else process.env.CODEX_HOME = prevCodexHome;
  }
});

test('models: a byte order mark that opens config.toml stays first through init\'s wiring, `models use` and uninstall', () => {
  // Codex refuses a config.toml that holds the mark anywhere else. Init's keys went in front of it when
  // a table came first, and a rewritten first line dropped it.
  const BOM = '\uFEFF';
  const prevCodexHome = process.env.CODEX_HOME;
  const ch = tmpWork();
  process.env.CODEX_HOME = ch;
  const cfgPath = path.join(ch, 'config.toml');
  try {
    const tableFirst = BOM + '[features]\nhooks = true\n';
    fs.writeFileSync(cfgPath, tableFirst);
    assert.equal(core.codexModelChoice(), null);
    core.wireCodexModel('llama3.2:latest', true);
    assert.equal(fs.readFileSync(cfgPath, 'utf8'),
      `${BOM}model = "llama3.2:latest" ${core.CODEX_MODEL_MARKER}\nmodel_provider = "ollama" ${core.CODEX_MODEL_MARKER}\n[features]\nhooks = true\n`);
    assert.equal(core.unwireCodexModel(), 'llama3.2:latest');
    assert.equal(fs.readFileSync(cfgPath, 'utf8'), tableFirst, 'uninstall restores the file byte for byte, the mark first');

    fs.writeFileSync(cfgPath, BOM + 'model = "gpt-5"\n\n[features]\nhooks = true\n');
    core.wireCodexModel('qwen3');
    const used = fs.readFileSync(cfgPath, 'utf8');
    assert.equal(used, `${BOM}model = "qwen3"\n\nmodel_provider = "ollama"\n[features]\nhooks = true\n`);
    assert.equal(require('smol-toml').parse(used).model, 'qwen3');
  } finally {
    if (prevCodexHome === undefined) delete process.env.CODEX_HOME;
    else process.env.CODEX_HOME = prevCodexHome;
  }
});

test('codex: installer — Orca manners on hooks.json, append-only trust state, verifiable uninstall', () => {
  freshHome();
  const prevCodexHome = process.env.CODEX_HOME;
  const ch = tmpWork();
  process.env.CODEX_HOME = ch;
  try {
    const command = `claude-observatory capture --agent codex #${core.HOOK_MARKER}`;
    // The user's config.toml, with the user's comments — the whole point is that these survive.
    const original = '# my codex config\nmodel = "gpt-oss:20b"  # local\nmodel_provider = "ollama"\n';
    fs.writeFileSync(path.join(ch, 'config.toml'), original);

    const res = core.installCodexHooks(command, core.isOurCommand);
    assert.equal(res.hooksJson, 'created');
    assert.equal(res.stateWritten, true);
    assert.equal(res.backupPath, path.join(ch, 'config.toml.bak'));
    const hooksFile = JSON.parse(fs.readFileSync(core.codexHooksJsonPath(), 'utf8'));
    assert.equal(Object.keys(hooksFile.hooks).length, core.CODEX_HOOK_EVENTS.length, 'every event registered');
    assert.equal(hooksFile.hooks.PostToolUse[0].hooks[0].command, command);
    const config = fs.readFileSync(path.join(ch, 'config.toml'), 'utf8');
    assert.ok(config.startsWith(original.trimEnd()), 'existing lines and comments survive byte-for-byte');
    assert.equal((config.match(/\[hooks\.state\."/g) || []).length, core.CODEX_HOOK_EVENTS.length, 'one trust table per event');
    assert.ok(config.includes('trusted_hash = "sha256:'), 'the replicated hash shape');
    assert.equal(fs.readFileSync(res.backupPath, 'utf8'), original, 'the pre-touch original survives as .bak');

    // Idempotent: a second run changes NOTHING (no churn, no growing config).
    const again = core.installCodexHooks(command, core.isOurCommand);
    assert.equal(again.hooksJson, 'unchanged');
    assert.equal(again.stateWritten, false);

    // Foreign entries: another tool's group is never touched, reordered, or deduped.
    const withForeign = JSON.parse(fs.readFileSync(core.codexHooksJsonPath(), 'utf8'));
    withForeign.hooks.PostToolUse.push({ matcher: 'Bash', hooks: [{ type: 'command', command: 'orca observe' }] });
    fs.writeFileSync(core.codexHooksJsonPath(), JSON.stringify(withForeign));
    const res3 = core.installCodexHooks(command, core.isOurCommand);
    assert.equal(res3.foreignGroups, 1, 'the foreign group is counted, present, untouched');
    const st = core.codexHooksStatus(core.isOurCommand);
    assert.equal(st.installed, true);
    assert.equal(st.trust, 'trusted', 'our replicated hash matches what we wrote');
    assert.equal(st.foreignGroups, 1);

    // Tampered state (a codex upgrade drifting the hash) reads as NOT trusted — the silent-skip alarm.
    const tampered = fs.readFileSync(path.join(ch, 'config.toml'), 'utf8').replace(/trusted_hash = "sha256:[0-9a-f]{8}/, 'trusted_hash = "sha256:00000000');
    fs.writeFileSync(path.join(ch, 'config.toml'), tampered);
    assert.equal(core.codexHooksStatus(core.isOurCommand).trust, 'partial');

    // Uninstall prunes OUR entries, keeps the foreign group and its file, strips only OUR tables.
    const un = core.uninstallCodexHooks(core.isOurCommand);
    assert.equal(un.hooksJson, 'pruned');
    assert.equal(un.stateRemoved, true);
    const pruned = JSON.parse(fs.readFileSync(core.codexHooksJsonPath(), 'utf8'));
    assert.deepEqual(Object.keys(pruned.hooks), ['PostToolUse'], 'only the foreign group remains');
    assert.equal(pruned.hooks.PostToolUse[1].hooks[0].command, 'orca observe');
    const cleaned = fs.readFileSync(path.join(ch, 'config.toml'), 'utf8');
    assert.ok(!cleaned.includes('[hooks.state."'), 'our trust tables are gone');
    assert.ok(cleaned.includes('# my codex config'), 'the user lines still survive');

    // With no foreign entries at all, uninstall removes the file it created.
    fs.rmSync(core.codexHooksJsonPath());
    core.installCodexHooks(command, core.isOurCommand);
    const un2 = core.uninstallCodexHooks(core.isOurCommand);
    assert.equal(un2.hooksJson, 'removed');
    assert.ok(!fs.existsSync(core.codexHooksJsonPath()));
  } finally {
    if (prevCodexHome === undefined) delete process.env.CODEX_HOME;
    else process.env.CODEX_HOME = prevCodexHome;
  }
});

test('codex: a hook turned off in Codex stays off through a reinstall, and is reported apart from trust', () => {
  freshHome();
  const prevCodexHome = process.env.CODEX_HOME;
  // A Windows path needs TOML escaping; a literal backslash exercises it on POSIX too.
  const ch = path.join(tmpWork(), 'codex\\home');
  fs.mkdirSync(ch, { recursive: true });
  process.env.CODEX_HOME = ch;
  try {
    const command = `oak capture --agent codex #${core.HOOK_MARKER}`;
    core.installCodexHooks(command, core.isOurCommand);
    const cfg = path.join(ch, 'config.toml');
    const table = (ev) => `[hooks.state.${JSON.stringify(core.codexHookKey(core.codexHooksJsonPath(), ev, 0))}]`;
    const states = () => require('smol-toml').parse(fs.readFileSync(cfg, 'utf8')).hooks.state;
    const state = (ev) => states()[core.codexHookKey(core.codexHooksJsonPath(), ev, 0)];
    // Turning a hook off in Codex writes `enabled = false` into that hook's state table.
    const text = fs.readFileSync(cfg, 'utf8');
    const at = text.indexOf(table('PostToolUse'));
    assert.ok(at >= 0, 'the TOML-escaped PostToolUse table is found before changing its switch');
    const end = text.indexOf('\n', text.indexOf('trusted_hash', at));
    fs.writeFileSync(cfg, text.slice(0, end) + '\nenabled = false' + text.slice(end));
    let st = core.codexHooksStatus(core.isOurCommand);
    assert.equal(st.trust, 'trusted', 'every hash still matches: a hook the person turned off is not a trust problem');
    assert.deepEqual(st.userDisabled, ['PostToolUse']);
    // An install over it changes nothing, and leaves the switch where it was.
    const before = fs.readFileSync(cfg, 'utf8');
    assert.equal(core.installCodexHooks(command, core.isOurCommand).stateWritten, false);
    assert.equal(fs.readFileSync(cfg, 'utf8'), before);
    // A hash that drifted is reinstalled, which rewrites OAK's tables: the switch comes along.
    const drift = (t) => t.replace(/(:stop:0:0"\]\ntrusted_hash = "sha256:)[0-9a-f]{8}/, (_, head) => head + '00000000');
    fs.writeFileSync(cfg, drift(before));
    assert.equal(core.codexHooksStatus(core.isOurCommand).trust, 'partial', 'the drifted hash is what reads as untrusted');
    assert.equal(core.installCodexHooks(command, core.isOurCommand).stateWritten, true);
    assert.equal(state('PostToolUse').enabled, false, 'the hook the person turned off stays off');
    assert.equal(state('Stop').enabled, undefined);
    st = core.codexHooksStatus(core.isOurCommand);
    assert.equal(st.trust, 'trusted');
    assert.deepEqual(st.userDisabled, ['PostToolUse']);
    // A hook turned back on in Codex (`enabled = true`) keeps that too.
    fs.writeFileSync(cfg, drift(fs.readFileSync(cfg, 'utf8').replace('enabled = false', 'enabled = true')));
    core.installCodexHooks(command, core.isOurCommand);
    assert.equal(state('PostToolUse').enabled, true);
    assert.deepEqual(core.codexHooksStatus(core.isOurCommand).userDisabled, []);
  } finally {
    if (prevCodexHome === undefined) delete process.env.CODEX_HOME;
    else process.env.CODEX_HOME = prevCodexHome;
  }
});

test('codex: a byte order mark that opens config.toml stays first, once, through install, reinstall and uninstall', () => {
  freshHome();
  const prevCodexHome = process.env.CODEX_HOME;
  const ch = tmpWork();
  process.env.CODEX_HOME = ch;
  const BOM = '\uFEFF';
  const cfg = path.join(ch, 'config.toml');
  const marked = () => {
    const text = fs.readFileSync(cfg, 'utf8');
    assert.ok(text.startsWith(BOM) && text.lastIndexOf(BOM) === 0, JSON.stringify(text.slice(0, 80)));
    require('smol-toml').parse(text);
    return text;
  };
  try {
    const command = `oak capture --agent codex #${core.HOOK_MARKER}`;
    for (const original of [BOM + '[features]\nhooks = true\n', BOM + 'model = "gpt-5"\n']) {
      fs.writeFileSync(cfg, original);
      core.installCodexHooks(command, core.isOurCommand);
      assert.ok(marked().startsWith(original), 'every original byte survives, the mark first');
      assert.equal(core.codexHooksStatus(core.isOurCommand).trust, 'trusted');
      core.uninstallCodexHooks(core.isOurCommand);
      assert.ok(!marked().includes('[hooks.state'));
    }
    // OAK's own table first: a file of OAK's tables saved again with the mark. A reinstall rewrites that
    // table and an uninstall removes it; the mark stayed with it.
    fs.writeFileSync(cfg, '');
    core.installCodexHooks(command, core.isOurCommand);
    fs.writeFileSync(cfg, BOM + fs.readFileSync(cfg, 'utf8').replace(/trusted_hash = "sha256:[0-9a-f]{8}/, 'trusted_hash = "sha256:00000000'));
    assert.equal(core.installCodexHooks(command, core.isOurCommand).stateWritten, true);
    marked();
    assert.equal(core.codexHooksStatus(core.isOurCommand).trust, 'trusted');
    core.uninstallCodexHooks(core.isOurCommand);
    assert.equal(marked(), BOM + '\n');
    // A file of the mark alone, which the blank-line trim took with it.
    fs.writeFileSync(cfg, BOM);
    core.installCodexHooks(command, core.isOurCommand);
    marked();
    assert.equal(core.codexHooksStatus(core.isOurCommand).trust, 'trusted');
  } finally {
    if (prevCodexHome === undefined) delete process.env.CODEX_HOME;
    else process.env.CODEX_HOME = prevCodexHome;
  }
});

test('feed: kind agent reads the SPAWN\'s OWN transcript — the read-only view a spawn-row click opens', () => {
  freshHome();
  const S = 'feed-sub';
  const cwd = tmpWork();
  const proj = core.projectDir(cwd);
  fs.mkdirSync(proj, { recursive: true });
  const AG = 'deadbeef0001';
  // The session transcript must exist (findSubagentsDir walks from it) and edits ITS OWN file; the
  // spawn edits a DIFFERENT one. A feed that shows the spawn's file — and not the session's — proves
  // it read the spawn's transcript, which is what `--feed-agent` (and a spawn-row click) must open.
  fs.writeFileSync(
    path.join(proj, S + '.jsonl'),
    JSON.stringify({ cwd, timestamp: '2026-07-13T10:00:00.000Z', message: { role: 'assistant', content: [{ type: 'tool_use', name: 'Edit', input: { file_path: cwd + '/PARENT-only.ts' } }] } }) + '\n',
  );
  const subDir = path.join(proj, S, 'subagents');
  fs.mkdirSync(subDir, { recursive: true });
  fs.writeFileSync(
    path.join(subDir, `agent-${AG}.jsonl`),
    JSON.stringify({ isSidechain: true, agentId: AG, timestamp: '2026-07-13T10:01:00.000Z', message: { role: 'assistant', content: [{ type: 'tool_use', name: 'Edit', input: { file_path: cwd + '/SPAWN-only.ts' } }] } }) + '\n',
  );

  const blob = JSON.stringify(core.liveFeed(cwd, S, { kind: 'agent', id: AG }).entries);
  assert.ok(/SPAWN-only/.test(blob), 'the spawn feed shows the SPAWN\'s edit');
  assert.ok(!/PARENT-only/.test(blob), 'and NOT the session\'s edit — it read the spawn\'s own transcript');

  // A bogus agent id has no transcript — an honest empty, never a silent fall-through to the session's feed.
  assert.equal(core.liveFeed(cwd, S, { kind: 'agent', id: 'nope' }).entries.length, 0, 'an unknown spawn id yields no entries');

  // THE FLAG ITSELF, through the built CLI: `--feed-agent` is the terminal's channel for this view
  // (feed-specific, because the Agent screen's batch also carries `prompts`, which reads `--id`). A
  // typo on either side of the seam silently falls back to kind:'session' — the reader then gets the
  // PARENT's feed labelled as the worker's, and only this spawn catches it.
  const viaCli = JSON.parse(cp.execFileSync(
    'node', [CLI, 'feed', '--session', S, '--root', cwd, '--feed-agent', AG, '--json'],
    { env: { ...process.env, HOME: os.homedir(), USERPROFILE: os.homedir() }, encoding: 'utf8' },
  ));
  assert.equal(viaCli.ref?.kind, 'agent', 'the flag routes the view to the worker');
  const cliBlob = JSON.stringify(viaCli.entries ?? []);
  assert.ok(/SPAWN-only/.test(cliBlob) && !/PARENT-only/.test(cliBlob), 'and the CLI serves the worker\'s own feed, not the parent\'s');
});

test('actions: a Bash command rides its own `cmd` field whole (bounded) — the blob expands it', () => {
  // The head row is one line by design; the REAL command (newlines and all) rides `cmd` so every
  // surface can expand it. detail
  // stays the human description — the two are separable on purpose.
  const multi = core.targetOf('Bash', { command: 'cd /repo\nnpm test', description: 'run tests' });
  assert.equal(multi.target, 'cd /repo npm test', 'the head is the one-line form');
  assert.equal(multi.detail, 'run tests', 'detail stays the description alone');
  assert.equal(multi.cmd, 'cd /repo\nnpm test', 'cmd carries the real command, line breaks intact');
  const huge = core.targetOf('Bash', { command: Array.from({ length: 40 }, (_, i) => `step-${i}`).join('\n') });
  assert.match(huge.cmd, /\+16 more lines \(the transcript has it whole\)/, 'a giant script is bounded, and says how much it withheld');
});

test('cli: `views --serve` answers batches over stdin — warm worker, one JSON line per request', async () => {
  freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const S = 'serve-views';
  const cwd = tmpWork();
  const proj = core.projectDir(cwd);
  fs.mkdirSync(proj, { recursive: true });
  fs.writeFileSync(path.join(proj, S + '.jsonl'), JSON.stringify({ cwd, message: { role: 'user', content: 'go' } }) + '\n');
  core.ensureStore(S);

  const child = cp.spawn('node', [CLI, 'views', '--serve'], {
    env: { ...process.env, HOME: os.homedir(), USERPROFILE: os.homedir() },
    stdio: ['pipe', 'pipe', 'pipe'],
  });
  let buf = '';
  const waiters = [];
  child.stdout.on('data', (d) => {
    buf += d;
    let i;
    while ((i = buf.indexOf('\n')) >= 0 && waiters.length) {
      const line = buf.slice(0, i);
      buf = buf.slice(i + 1);
      waiters.shift()(line);
    }
  });
  const ask = (req) => new Promise((resolve) => { waiters.push(resolve); child.stdin.write(JSON.stringify(req) + '\n'); });

  // Two real batches: the worker stays alive between them (the whole point), and each answers with
  // exactly the views asked for.
  const r1 = JSON.parse(await ask({ views: ['sessions', 'feed'], args: ['--session', S, '--root', cwd] }));
  assert.deepEqual(Object.keys(r1).filter((k) => !k.startsWith('__')).sort(), ['feed', 'sessions'], 'first batch answers its views');
  const r2 = JSON.parse(await ask({ views: ['sessions'], args: ['--session', S, '--root', cwd] }));
  assert.ok(r2.sessions, 'the SAME process answers a second batch — warm, not respawned');

  // A malformed request answers with __fatal — a reason, never a dead worker.
  const r3 = JSON.parse(await ask({ nonsense: true }));
  assert.match(String(r3.__fatal), /no views/, 'a bad request names its problem instead of killing the serve');
  const r4 = JSON.parse(await ask({ views: ['sessions'], args: ['--session', S, '--root', cwd] }));
  assert.ok(r4.sessions, 'and the worker still serves after it');

  // stdin closing ends the serve cleanly.
  const exited = new Promise((resolve) => child.on('exit', resolve));
  child.stdin.end();
  assert.equal(await exited, 0, 'EOF exits 0');
});

test('cli: `views --serve` follows a store another process moves, and leaves the old location as it was', async () => {
  // The terminal app's warm worker kept the location it started with: after `oak store --move` it listed
  // nothing, wrote `session-meta` back into the old location, and the move back there was then refused.
  freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const S = 'serve-moved';
  const cwd = tmpWork();
  editHook(S, cwd, path.join(cwd, 'a.ts'), 'one\n', 'two\n');
  const env = { ...process.env, HOME: os.homedir(), USERPROFILE: os.homedir() };
  const def = core.rootDir();
  const dest = path.join(tmpDir('serve-moved-'), 'observatory');
  const child = cp.spawn('node', [CLI, 'views', '--serve'], { env, stdio: ['pipe', 'pipe', 'pipe'] });
  let buf = '';
  const waiters = [];
  child.stdout.on('data', (d) => {
    buf += d;
    let i;
    while ((i = buf.indexOf('\n')) >= 0 && waiters.length) {
      const line = buf.slice(0, i);
      buf = buf.slice(i + 1);
      waiters.shift()(line);
    }
  });
  const listed = () => new Promise((resolve) => {
    waiters.push((line) => resolve(JSON.parse(line).list?.edits?.length));
    child.stdin.write(JSON.stringify({ views: ['list', 'sessions'], args: ['--session', S, '--root', cwd] }) + '\n');
  });
  const oak = (...args) => cp.spawnSync('node', [CLI, ...args], { env, encoding: 'utf8' });
  try {
    assert.equal(await listed(), 1, 'the worker lists the edit');
    assert.equal(oak('store', '--move', dest).status, 0, 'another process moves the store');
    assert.equal(await listed(), 1, 'the same worker lists it from where it went');
    assert.deepEqual(fs.readdirSync(def), ['prefs.json'], 'and writes nothing where it was');
    const back = oak('store', '--default');
    assert.equal(back.status, 0, `so the move back is not refused: ${back.stderr}`);
    assert.equal(await listed(), 1, 'and the worker follows it back');
  } finally {
    const exited = new Promise((resolve) => child.on('exit', resolve));
    child.stdin.end();
    await exited;
  }
});

test('store: rootDir stats prefs.json once per turn of the event loop, and sees a location written since', async () => {
  // Called 3,000 times in one warm view batch over a 3,000-edit session: a stat per call put 17 ms on a 50 ms batch.
  freshHome();
  const prefs = core.prefsPath();
  const moved = path.join(tmpDir('root-turn-'), 'observatory');
  let stats = 0;
  const realStat = fs.statSync;
  const count = () => {
    stats = 0;
    fs.statSync = function (p, ...rest) {
      if (String(p) === prefs) stats++;
      return realStat.call(this, p, ...rest);
    };
  };
  try {
    count();
    for (let i = 0; i < 1000; i++) core.rootDir();
    assert.equal(stats, 1, 'one stat for a thousand calls in one turn');
    // Written as another process writes it, with no clearRootMemo in this one: the next turn sees it.
    fs.mkdirSync(path.dirname(prefs), { recursive: true });
    fs.writeFileSync(`${prefs}.tmp`, JSON.stringify({ storeDir: moved }));
    fs.renameSync(`${prefs}.tmp`, prefs);
    await new Promise((resolve) => setImmediate(resolve));
    count();
    assert.equal(core.rootDir(), moved, 'the next turn follows the new location');
    assert.equal(core.rootDir(), moved);
    assert.equal(stats, 1, 'and stats it once');
  } finally {
    fs.statSync = realStat;
  }
});

test('store: rootDir follows a location written within one tick of a coarse file system clock, and a new inode alone', async () => {
  // FAT dates a write to 2 s and HFS+ to 1 s: two writes of one size in one tick, in place or onto a reused inode, left
  // the stamp as it was, and a running process stayed on the old location.
  freshHome();
  const prefs = core.prefsPath();
  const base = tmpDir('root-coarse-');
  const [a, b, c] = ['a', 'b', 'c'].map((x) => path.join(base, `store-${x}`)); // one length, so one size
  const turn = () => new Promise((resolve) => setImmediate(resolve));
  fs.mkdirSync(path.dirname(prefs), { recursive: true });
  const tick = new Date(Date.now() - 500); // this second, as such a file system dates it
  fs.writeFileSync(prefs, JSON.stringify({ storeDir: a }));
  fs.utimesSync(prefs, tick, tick);
  await turn();
  assert.equal(core.rootDir(), a, 'control: the first location');
  const before = fs.statSync(prefs);
  fs.writeFileSync(prefs, JSON.stringify({ storeDir: b })); // in place: the inode stays
  fs.utimesSync(prefs, tick, tick);
  const after = fs.statSync(prefs);
  assert.deepEqual([after.ino, after.size, after.mtimeMs], [before.ino, before.size, before.mtimeMs], 'control: the stamp is as it was');
  await turn();
  let reads = 0;
  const realRead = fs.readFileSync;
  fs.readFileSync = function (f, ...rest) { if (String(f) === prefs) reads++; return realRead.call(this, f, ...rest); };
  try {
    assert.equal(core.rootDir(), b, 'a location written in the same tick is followed');
    for (let i = 0; i < 1000; i++) core.rootDir();
    assert.ok(reads <= 2, `and read once for the turn, not per call (${reads})`);
  } finally {
    fs.readFileSync = realRead;
  }
  // Older than any tick, the stamp is trusted: a new inode alone (a rename onto one size and one mtime) moves it.
  const old = new Date(Date.now() - 60_000);
  fs.utimesSync(prefs, old, old);
  await turn();
  assert.equal(core.rootDir(), b);
  fs.writeFileSync(`${prefs}.tmp`, JSON.stringify({ storeDir: c }));
  fs.utimesSync(`${prefs}.tmp`, old, old);
  const was = fs.statSync(prefs);
  fs.renameSync(`${prefs}.tmp`, prefs);
  const now = fs.statSync(prefs);
  assert.ok(now.ino !== was.ino && now.size === was.size && now.mtimeMs === was.mtimeMs, 'control: only the inode differs');
  await turn();
  assert.equal(core.rootDir(), c, 'a new inode alone is a new location');
});

test('store: a prefs.json that does not parse leaves a running process on the store where it is', async () => {
  // Read as no preferences, a hand edit saved half done sent every running process to the default location until it
  // parsed again: Review listed nothing, the views worker wrote its caches there, the focus server stopped and one started
  // there, and `oak store --default` then refused the default as not empty.
  freshHome();
  const prefs = core.prefsPath();
  const moved = path.join(tmpDir('root-unparsed-'), 'observatory');
  // Written as another process writes it, with no clearRootMemo in this one.
  const put = (text) => {
    fs.mkdirSync(path.dirname(prefs), { recursive: true });
    fs.writeFileSync(`${prefs}.tmp`, text);
    fs.renameSync(`${prefs}.tmp`, prefs);
  };
  const turn = () => new Promise((resolve) => setImmediate(resolve));
  put(JSON.stringify({ storeDir: moved }));
  await turn();
  assert.equal(core.rootDir(), moved, 'control: the moved location');
  put(`{"storeDir": ${JSON.stringify(moved)},`);
  await turn();
  assert.equal(core.rootDir(), moved, 'a hand edit saved half done leaves the store where it was');
  put('');
  await turn();
  assert.equal(core.rootDir(), moved, 'so does a file caught empty in the middle of a write');
  put(JSON.stringify({ theme: 'mono' }));
  await turn();
  assert.equal(core.rootDir(), path.join(core.claudeConfigDir(), 'claude-observatory'), 'once it parses and names no location, the default');
  fs.rmSync(prefs);
  put(`{"storeDir": ${JSON.stringify(moved)},`);
  core.clearRootMemo();
  assert.equal(core.rootDir(), path.join(core.claudeConfigDir(), 'claude-observatory'), 'a process that never knew a location has only the default');
});

test('dashframe: every screen fits its budget at every width', () => {
  for (const screen of ['edits', 'map', 'prompts', 'tasks', 'workflows', 'agents', 'feed', 'audit']) {
    for (const [cols, rows] of [[40, 24], [80, 30], [120, 40], [200, 50]]) {
      const frame = tui.renderDashFrame(dashFixture({ screen }), { cols, rows, color: false });
      assert.equal(frame.length, rows, `${screen} @${cols}x${rows}: a frame is exactly its height`);
      for (const line of frame) {
        // Measured by DISPLAY width, which is the only ruler that is right for CJK and colour. A line
        // one column too wide wraps, and every subsequent row of the frame is then off by one.
        assert.ok(tui.displayWidth(line) <= cols, `${screen} @${cols}: "${line.slice(0, 40)}…" overflows`);
      }
    }
  }
});

test('dashframe: the Workflows screen renders the per-phase breakdown, like both editors (0.9.5)', () => {
  // The terminal used to render ONE flat line per run, built from `w.phase` — a field WorkflowRun
  // has never had — so the column was always empty and collapsed to a running/done the glyph already
  // showed. Everything below was on the wire the whole time.
  // The glyph tier is PINNED. It is chosen from the platform and the locale at runtime — native
  // Windows gets `safe`, whose ramp is ASCII (`..::-=+#`) rather than the block eighths — so a test
  // that hardcodes one tier's characters passes on the author's machine and fails on someone else's.
  // (It did: CI's Windows runners rendered `:#=` where this asserted `▁▂▃▄▅▆▇█`.)
  const g = tui.glyphs('block');
  const RAMP = new RegExp(`[${g.ramp.join('')}]`);
  const frame = tui.renderDashFrame(dashFixture({ screen: 'workflows' }), { cols: 200, rows: 40, color: false, glyphs: g });
  const text = frame.join('\n');
  const line = (re) => frame.find((l) => re.test(l));

  // Header: the run's state, the phase summary, and the DESCRIPTION (not the bare name — that is
  // what the editors show, and it is the half a human recognises).
  const head = line(/deep eval of the CLI roadmap/);
  assert.ok(head, 'the run header carries the description');
  assert.match(head, /running/, 'and whether it is running');
  assert.match(head, /Find 2\/2 · Verify 1\/2/, 'and the phase summary, joined the way the editors join it');

  // Metrics, on their own row so the description keeps its full line. The field set is the editors'
  // metrics line: sparkline · ±lines · agents · tok · dur · edits.
  const met = line(/601k tok/);
  assert.ok(met, 'the metrics row is rendered');
  assert.match(met, RAMP, 'the run sparkline — both editors draw one, and the terminal has a ramp for it');
  assert.match(met, /\+12/, 'lines added');
  assert.match(met, /−3/, 'lines removed');
  assert.match(met, /6 agents/, 'the agent count');
  assert.match(met, /46m/, 'the wall time');
  // w.edits (3), NOT the change-map rollup the old row used — all three front ends must say the same
  // number for the same run.
  assert.match(met, /3 edits/, "the run's OWN edit count");

  // The NAME, under the description, when they differ — VS Code's `mt-wsub`. Both are real
  // identifiers and the reader should not have to choose which one they were shown.
  assert.ok(line(/^\s+roadmap-deep-eval\s*$/), "the run's name rides its own row when it differs from the description");

  // Phase headings, then the agents that belong to them, then the ones that belong to none.
  for (const want of [/^\s+Find 2\/2\s*$/, /^\s+Verify 1\/2\s*$/, /^\s+other\s*$/]) {
    assert.ok(frame.some((l) => want.test(l)), `a heading row matching ${want} is rendered`);
  }
  // An agent row carries what the editors' `wagRow` carries: sparkline · ±lines · model · effort ·
  // tok · dur · edits.
  assert.ok(line(/find:consistency/), 'a phase agent is rendered');
  assert.match(line(/find:consistency/), /Opus 4\.8/, 'with its model when one is known');
  assert.match(line(/find:consistency/), RAMP, 'and its OWN sparkline, as both editors draw');
  assert.match(line(/find:consistency/), /\+5 −2/, 'and its own ±lines');
  assert.match(line(/find:consistency/), /1 edit\b/, 'and its own edit count');
  assert.ok(line(/verify:external/), 'agents in the second phase are rendered too');
  assert.match(line(/verify:external/), /high/, 'and effort when it was actually stated');
  assert.doesNotMatch(line(/find:consistency/), /high|low|medium/, 'an unstated effort is left out, never guessed');
  // ±lines only when there ARE any — a column of `+0 −0` reads as a finding rather than as silence.
  assert.doesNotMatch(line(/find:evidence~/), /\+0 −0/, 'an agent that changed nothing shows no ± at all');

  // A DERIVED label is marked and never asserted.
  assert.match(text, /find:evidence~/, 'a prompt-derived label carries the heuristic marker');
  assert.doesNotMatch(text, /find:consistency~/, 'a real label does not');

  // The phase-less agent falls under `other`, identified by type + short id since it has no label.
  assert.ok(line(/workflow-subagent dddddd/), 'an unlabelled agent falls back to its type and a short id');

  // Ordering: headings before their agents, `other` last.
  const at = (re) => frame.findIndex((l) => re.test(l));
  assert.ok(at(/deep eval/) < at(/601k tok/), 'the metrics row follows its header');
  assert.ok(at(/Find 2\/2\s*$/) < at(/find:consistency/), 'a phase heading precedes its agents');
  assert.ok(at(/find:consistency/) < at(/Verify 1\/2\s*$/), 'phases are rendered in order');
  assert.ok(at(/other/) > at(/verify:external/), 'the leftovers come last');
  assert.ok(at(/other/) < at(/workflow-subagent/), 'under their own heading');

  // Only the run itself is a cursor stop — its breakdown is `cont`, exactly like the agents screen's
  // nested subagents. Asserted through the selection surface rather than by reading the rows.
  const st = dashFixture({ screen: 'workflows' });
  assert.deepEqual(tui.selectionIds(st, 'all'), [], 'a workflow row selects no edits');

  // And the field the old renderer depended on is never read: a run WITHOUT the breakdown still
  // renders its header rather than a blank or a crash.
  const bare = dashFixture({ screen: 'workflows' });
  bare.views.multitask.workflows = [{ id: 'w0', name: 'bare', running: false, edits: 0, added: 0, removed: 0, tokens: 0, durationMs: 0, agents: [], phaseGroups: [] }];
  const bareFrame = tui.renderDashFrame(bare, { cols: 120, rows: 24, color: false });
  assert.ok(bareFrame.some((l) => /bare/.test(l)), 'a run with no phases and no agents still renders');
  assert.ok(!bareFrame.some((l) => /\bother\b/.test(l)), 'and shows no stray "other" heading with nothing to put under it');
});

test('dashframe: a WRAPPED row keeps its indent, because the indent is the nesting (0.9.5)', () => {
  // Nesting in every dashboard list is carried by leading spaces — a workflow's per-phase agents,
  // Fleet's subagents. `wrapVisible` splits on ' ', so an indent arrived as a run of empty words and
  // was collapsed: a nested row that wrapped came back flush against the margin, where it reads as a
  // top-level row. Latent for years; reachable the moment a nested row got long enough to wrap.
  const st = paneFixture({
    // The Dashboards pane, on its Workflows tab (index 1) — the real surface, resolved the way the
    // renderer resolves it, not a screen name set by hand.
    panes: { minimized: new Set(), zoom: null, focus: 'dashboards', tab: { dashboards: 1 }, cursor: {}, scroll: {} },
    views: {
      changemap: { rollupByWorkflow: [] },
      multitask: {
        workflows: [
          {
            id: 'w1',
            name: 'w',
            description: 'w',
            phaseGroups: [{ title: 'Find', done: 1, total: 1 }],
            agents: [
              {
                agentId: 'a1',
                // Long enough to wrap at 60 columns once the extras are appended, and made of real
                // words so it WORD-wraps — the realistic case. (A single unbreakable token is
                // hard-broken instead, which puts the glyph alone on the first line.)
                label: 'verify external evidence for every roadmap claim',
                labelDerived: false,
                phase: 'Find',
                done: true,
                tokens: 1000, durationMs: 1000, edits: 1, added: 2, removed: 3,
                model: 'Opus 4.8', effort: 'high', sparkline: [1, 2, 3],
              },
            ],
            running: false,
            agentCount: 1, tokens: 1000, durationMs: 1000, edits: 1, added: 2, removed: 3,
            sparkline: [1, 2, 3],
          },
        ],
      },
    },
  });
  // `selTab` is what paneScreenOf reads — 1 is Workflows in the Dashboards strip. `body` is the inner
  // rect makeBox carves once boxes are on (the default now): inset by the │ borders (x+1, w−2) with a
  // row reserved for the foot — the content functions read box.body, not box.rect.
  const box = { id: 'dashboards', selTab: 1, rect: { x: 0, y: 0, w: 60, h: 20 }, body: { x: 1, w: 58, h: 18 } };
  // Pinned tier, for the same reason as the Workflows test: the continuation marker is `▸` on a
  // block/safe terminal and `>` on an ascii one, so asserting either literal is a platform bet.
  const g = tui.glyphs('block');
  const lines = tui.paneVisible(st, box, g, 'none').map((v) => v.text);
  const agent = lines.find((l) => /verify external/.test(l));
  assert.ok(agent, 'the long agent row is rendered');
  assert.match(agent, /^ {4,}/, 'and it is still INDENTED — a wrapped nested row must not jump to the margin');
  // The tail is not lost either: it continues on a marked row rather than being cut.
  assert.ok(lines.some((l) => l.trimStart().startsWith(g.wrap)), 'the remainder continues on its own marked row');
  assert.ok(lines.some((l) => /1 edit/.test(l)), 'and the tail of the row survives the wrap');
  for (const l of lines) assert.ok(tui.displayWidth(l) <= 60, `"${l}" overflows the pane`);
});

test('dashframe: no width silently truncates the key hints', () => {
  // A hand-written `cols >= 96` picked a hint measuring 100 columns and fit it to `cols - 1`, so
  // widths 96..100 cut the last keys off ("q qui") — invisibly, because a fit never reports. Spot
  // checks miss this; only a sweep finds a five-wide window. The renderer now picks by measurement.
  const st = dashFixture();
  const cut = [];
  for (let cols = 40; cols <= 200; cols++) {
    const frame = tui.renderDashFrame(st, { cols, rows: 24, color: false });
    const hint = frame[frame.length - 1].replace(/\s+$/, '');
    if (tui.displayWidth(hint) > cols - 1) cut.push({ cols, why: 'over budget' });
    // A hint that ends mid-word is a hint that was cut — and a cut hint is one that is no longer a
    // tier, byte for byte. The old rule read the tiers' last WORD ("ends in q/quit", later '?'), so
    // retiring a key broke the instrument while nothing was truncated. The ladder is the expectation.
    else if (hint && !tui.KEY_HINTS.includes(hint)) cut.push({ cols, hint });
  }
  assert.deepEqual(cut, [], `widths whose hints were truncated: ${JSON.stringify(cut.slice(0, 6))}`);

  // Positive control: the sweep must be able to catch a too-long hint, or its silence proves nothing.
  const longHint = '1-8 screens · j/k move · enter open · a keep · u undo · A/U all · / filter · e $EDITOR · ? keys · q quit';
  assert.ok(tui.displayWidth(longHint) > 99, 'the widest hint really does exceed the budget at cols=100');
  // …and of catching a hint fitted by a single column, which is how a truncation actually arrives.
  assert.ok(!tui.KEY_HINTS.includes(tui.KEY_HINTS[0].slice(0, -1)), 'one column off the widest tier is caught');
});

test('dashframe: the session leads the frame, and the picker keeps its columns', () => {
  // Everything below the top row is scoped to ONE session, so a reader who has not noticed which one
  // is selected can misread the whole screen. It leads the frame, and says it can be changed.
  const withSessions = dashFixture({
    views: { ...dashFixture().views, sessions: { active: 'fixture0', sessions: [{ id: 'fixture0' }, { id: 'other1' }] } },
  });
  const top = tui.renderDashFrame(withSessions, { cols: 90, rows: 12, color: false })[0];
  assert.match(top, /fixture/, 'the top row names the session in effect');
  assert.match(top, /2 sessions/, 'and says there are others to switch to');

  // A picker's cursor REPLACES the row's leading space. Prepending shifts every column right by one
  // and collides with the marker a row may already carry — two meanings sharing one glyph.
  const lines = [' * aaaaaaaa   1 pending  first', '   bbbbbbbb   2 pending  second'];
  const picking = dashFixture({ overlay: { title: 'switch session', lines, scroll: 0, cursor: 1 } });
  const frame = tui.renderDashFrame(picking, { cols: 60, rows: 12, color: false });
  const at = frame.findIndex((l) => l.includes('aaaaaaaa'));
  assert.ok(at >= 0, 'the picker rows are on screen');
  const rows = frame.slice(at, at + 2);
  assert.ok(rows[1].startsWith('>  bbbbbbbb'), `cursor replaces the lead space: ${JSON.stringify(rows[1])}`);
  assert.ok(rows[0].startsWith(' * aaaaaaaa'), 'and the current-session marker is a different glyph, unshifted');
  assert.equal(tui.displayWidth(rows[0]), tui.displayWidth(rows[1]), 'so both rows stay the same width');
});

test('dashframe: hostile cell text cannot repaint the screen', () => {
  // A tool argument reaches a frame raw. An unsanitised ESC[2J here would clear the dashboard and
  // redraw over it — from data an agent wrote, not from anything the user typed.
  const frame = tui.renderDashFrame(dashFixture(), { cols: 100, rows: 20, color: false });
  const joined = frame.join('\n');
  assert.ok(!joined.includes('\x1b[2J'), 'the planted erase never reaches the frame');
  assert.ok(joined.includes('evil.ts'), 'while the surrounding filename is still shown');
});

test('dashframe: identical state renders identically, and time is injected', () => {
  const a = tui.renderDashFrame(dashFixture(), { cols: 100, rows: 20, color: false });
  const b = tui.renderDashFrame(dashFixture(), { cols: 100, rows: 20, color: false });
  assert.deepEqual(a, b, 'a pure function of state — otherwise snapshots compare two different renders');
  // Two DAYS later, not an hour: stamps are exact wall-clock now (2026-08-31), so within the same
  // day they hold still and the frames would rightly be identical — the day boundary is where `now`
  // changes what is painted (the clock form gains its date).
  const later = tui.renderDashFrame(dashFixture({ now: 5_000_000 + 2 * 86_400_000 }), { cols: 100, rows: 20, color: false });
  assert.notDeepEqual(a, later, 'and `now` really is the clock the frame reads');
});

test('dashframe: color:false emits no escapes at all', () => {
  // The CLI's own renderers decide colour from process.stdout.isTTY at call time, which is exactly
  // what makes them untestable. This one takes it as an argument.
  const frame = tui.renderDashFrame(dashFixture({ screen: 'audit' }), { cols: 90, rows: 20, color: false });
  assert.ok(!frame.some((l) => l.includes('\x1b')), 'no escape survives when colour is off');
  const colored = tui.renderDashFrame(dashFixture({ screen: 'audit' }), { cols: 90, rows: 20, color: true });
  assert.ok(colored.some((l) => l.includes('\x1b')), 'and colour is actually applied when it is on');
});

test('dashframe: selection means something different on each screen, deliberately', () => {
  // A key that means "one edit" on one screen and "every edit in the session" on another is how a
  // reviewer destroys work they meant to keep. Each screen states its own answer.
  // Cursor on the first row — which, under the default `time` sort, is the most recently edited file
  // (id 3, ts 3000), not the payload's first (id 1). "one" resolves to that row's edit.
  assert.deepEqual(tui.selectionIds(dashFixture({ screen: 'edits', cursor: 0 }), 'one'), [3]);
  // "all" is every edit — its ORDER follows the current sort (time here), so compare the set, not the order.
  assert.deepEqual([...tui.selectionIds(dashFixture({ screen: 'edits' }), 'all')].sort((a, b) => a - b), [1, 2, 3]);
  assert.deepEqual(tui.selectionIds(dashFixture({ screen: 'prompts', cursor: 0 }), 'one'), [1, 3], 'a prompt resolves to the edits it produced');
  // Observation screens carry no edit set, and the runtime prints why rather than doing nothing.
  for (const screen of ['audit', 'feed', 'agents', 'tasks', 'workflows']) {
    assert.deepEqual(tui.selectionIds(dashFixture({ screen }), 'all'), [], `${screen} rows are observations, not edits`);
  }
  // The filter narrows "all" — accepting everything listed must mean what is on screen.
  assert.deepEqual(tui.selectionIds(dashFixture({ screen: 'edits', filter: 'a.ts' }), 'all'), [1]);
});

test('watch: recursion is chosen by PLATFORM, never by try/catch', () => {
  // The only instrument that can catch this. Node does not throw for a recursive watch on Linux — since
  // v19.1 it silently substitutes a per-FILE watcher that opens one handle per file (thousands on a
  // store of thousands of files) and emits a synthetic event for each during its walk. A try/catch
  // waiting to select the poll fallback therefore never fires, and a runtime probe on a macOS CI
  // machine cannot observe any of it. A pure predicate can.
  assert.equal(core.nativeRecursive('linux'), false, 'Linux must NOT take the recursive path');
  assert.equal(core.nativeRecursive('darwin'), true);
  assert.equal(core.nativeRecursive('win32'), true);
  assert.equal(core.nativeRecursive('freebsd'), false, 'anything without a native recursive watch fans out');
});

test('watch: the store filter accepts logs and rejects the read path own writes', () => {
  freshHome();
  const roots = core.observatoryRoots({ cwd: tmpWork(), session: 'wsess' });
  const store = roots.find((r) => r.kind === 'store');
  assert.ok(store, 'a store root exists');
  const dir = store.dir;
  // Both filename SHAPES reach this: a relative path under a native recursive watch, a bare name under
  // a per-directory fanout. The obvious port of the editors' `name === 'log.jsonl'` matches only one.
  assert.equal(store.relevant('s1/log.jsonl', dir), true, 'recursive shape: relative path');
  assert.equal(store.relevant('log.jsonl', dir), true, 'fanout shape: bare name');
  assert.equal(store.relevant('s1/blobs/deadbeef', dir), false, 'blobs are not review state');
  // These four are written BY the views a refresh renders. Accepting them makes a live surface refresh
  // because it refreshed.
  for (const noise of ['changemap-cache/x/y.json', 'session-meta/s1.json', 'usage-cursors/a.json', 'stats-cache.json']) {
    assert.equal(store.relevant(noise, dir), false, `${noise} must not wake a refresh`);
  }
});

test('watch: a folder that is not there yet is waited for, not reported, and watched once it appears', async () => {
  // A fresh machine has no projects folder and no store (capture makes it), and a workspace no agent ran in has no
  // project folder of its own: each was reported as ENOENT on the status row and gave the whole root up to polling,
  // the projects folder too when only the workspace's own folder was missing. Both ways of watching: a fanout of
  // folders (Linux), and one recursive watch of the root (macOS, Windows), chosen here by the platform it reports.
  // Events are asserted for this platform's own way only. Elsewhere Node stands in for the OS's recursive watch, and
  // unlike the OS's it starts on a folder that is not there; it is made to refuse one, as macOS and Windows do.
  const own = core.nativeRecursive() ? 'darwin' : 'linux';
  const realWatch = fs.watch;
  for (const platform of ['linux', 'darwin']) {
    freshHome();
    const root = path.join(tmpWork(), 'not-yet');
    const seen = [], degrades = [];
    const real = Object.getOwnPropertyDescriptor(process, 'platform');
    Object.defineProperty(process, 'platform', { value: platform });
    if (platform !== own) {
      fs.watch = function (p, ...rest) {
        if (!fs.existsSync(p)) throw Object.assign(new Error(`ENOENT: no such file or directory, watch '${p}'`), { code: 'ENOENT' });
        return realWatch.call(this, p, ...rest);
      };
    }
    let w;
    try {
      w = core.createWatcher({
        roots: [{ dir: root, kind: 'store', relevant: (f) => f !== null && path.basename(f) === 'log.jsonl', fanout: (d) => [d, path.join(d, 's1'), path.join(d, 'never')] }],
        onChange: (kind) => seen.push(kind),
        onDegrade: (d, why) => degrades.push(`${d}: ${why}`),
      });
    } finally {
      Object.defineProperty(process, 'platform', real);
    }
    try {
      assert.deepEqual(degrades, [], `${platform}: nothing is reported`);
      assert.notEqual(w.stats()[0].mode, 'poll', `${platform}: and the root is not given up to polling`);
      fs.mkdirSync(path.join(root, 's1'), { recursive: true });
      const want = platform === 'linux' ? 2 : 1; // the root and s1, or the root alone
      for (const end = Date.now() + 10_000; w.stats()[0].watchers < want && Date.now() < end;) await new Promise((r) => setTimeout(r, 25));
      assert.equal(w.stats()[0].watchers, want, `${platform}: watched once it appears`);
      for (let i = 0, end = Date.now() + 10_000; platform === own && !seen.includes('store') && Date.now() < end; i++) {
        fs.appendFileSync(path.join(root, 's1', 'log.jsonl'), `{"id":${i}}\n`);
        await new Promise((r) => setTimeout(r, 200));
      }
      if (platform === own) assert.ok(seen.includes('store'), `${platform}: and a write in it wakes a refresh`);
      assert.deepEqual(degrades, [], `${platform}: a folder that never appears is still not reported`);
    } finally {
      w.close();
      fs.watch = realWatch;
    }
  }
});

test('watch: a folder deleted and made again is watched again', { skip: core.nativeRecursive() && 'one recursive watch of the root, not a folder each (Linux)' }, async () => {
  // A watcher stays on the folder it was given: deleted, it reports a rename of its own name and nothing after, and the
  // folder made again at that path (a session's folder, the store moved away and back) was never watched again, since
  // its path still had a watcher. A live view then stopped following that session.
  freshHome();
  const root = path.join(tmpWork(), 'store');
  const s1 = path.join(root, 's1');
  fs.mkdirSync(s1, { recursive: true });
  const seen = [];
  const w = core.createWatcher({
    roots: [{ dir: root, kind: 'store', relevant: (f) => f !== null && path.basename(f) === 'log.jsonl', fanout: (d) => [d, ...(fs.existsSync(path.join(d, 's1')) ? [path.join(d, 's1')] : [])] }],
    onChange: (kind) => seen.push(kind),
    onDegrade: (d, why) => assert.fail(`${d}: ${why}`),
  });
  try {
    const wake = async (what) => {
      seen.length = 0;
      for (let i = 0, end = Date.now() + 8_000; !seen.length && Date.now() < end; i++) {
        fs.appendFileSync(path.join(s1, 'log.jsonl'), `{"id":${i}}\n`);
        await new Promise((r) => setTimeout(r, 200));
      }
      assert.ok(seen.length, what);
    };
    await wake('control: a write to the folder wakes a refresh');
    fs.rmSync(s1, { recursive: true });
    await new Promise((r) => setTimeout(r, 300));
    fs.mkdirSync(s1);
    // The write inside it, not the folder's own appearance in the root: a log written there must reach the watcher.
    for (const end = Date.now() + 10_000; w.stats()[0].watchers < 2 && Date.now() < end;) await new Promise((r) => setTimeout(r, 25));
    await new Promise((r) => setTimeout(r, core.STORE_DEBOUNCE_MS * 3));
    await wake('a write to the folder made again wakes one too');
  } finally {
    w.close();
  }
});

test('watch: a real write to a session log wakes exactly one refresh', async () => {
  freshHome();
  const S = 'wlive';
  core.ensureStore(S);
  const seen = [];
  const w = core.createWatcher({
    roots: core.observatoryRoots({ cwd: tmpWork(), session: S }),
    onChange: (kind) => seen.push(kind),
    onDegrade: () => {},
  });
  try {
    seedEdit(S, path.join(tmpWork(), 'w.js'), null, 'x\n');
    // WAITED FOR, not slept at. A filesystem event has no deadline: the OS arms the watch and delivers
    // when it delivers, and on a loaded CI runner 900ms was not always enough — this went red on macOS
    // intermittently, on a different Node version each time, which is what a race looks like from the
    // outside. Polling is also strictly faster in the normal case, where the event lands in a few ms.
    const deadline = Date.now() + 10_000;
    while (!seen.includes('store') && Date.now() < deadline) await new Promise((r) => setTimeout(r, 25));
    assert.ok(seen.includes('store'), `a log append woke the store root (saw ${JSON.stringify(seen)})`);

    // …and the debounce still collapses the burst. This has to be measured AFTER the settle above, and
    // over a window longer than the 150ms debounce, or it is asserting about a burst still in flight.
    await new Promise((r) => setTimeout(r, 400));
    assert.ok(seen.filter((k) => k === 'store').length <= 2, `and did not fire once per byte written (saw ${JSON.stringify(seen)})`);
  } finally {
    w.close();
  }
});

test('textwidth: measures display columns, not string length', () => {
  // Each case is one whose string length is a WRONG answer — that gap is the whole reason this
  // module exists, so the comparison against .length is stated rather than implied.
  assert.equal(tui.displayWidth('\x1b[32m✓ ok\x1b[0m'), 4, 'SGR does not occupy columns (length is 13)');
  assert.equal(tui.displayWidth('漢字テスト'), 10, 'East Asian wide chars are 2 columns (length is 5)');
  assert.equal(tui.displayWidth('🔬'), 2, 'astral emoji is 2 columns (length is 2 UTF-16 units)');
  assert.equal(tui.displayWidth('é'), 1, 'a combining mark adds no column (length is 2)');
  assert.equal(tui.displayWidth('plain'), 5, 'plain ASCII still measures as itself');
});

test('textwidth: sanitizeCell disarms frame-hostile escapes and keeps colour', () => {
  // Transcript-derived cells reach a frame raw, so a planted erase in a tool argument would repaint
  // over the dashboard. Colour has to survive the same pass, or every rendered cell goes monochrome.
  assert.equal(tui.sanitizeCell('src/\x1b[2J\x1b[1;1Hfake.ts'), 'src/fake.ts', 'erase + cursor-home removed');
  assert.equal(tui.sanitizeCell('\x1b[32mkeep\x1b[0m'), '\x1b[32mkeep\x1b[0m', 'SGR passes through verbatim');
  assert.equal(tui.sanitizeCell('a\x1b[2Mb'), 'ab', 'uppercase M is delete-lines, not colour');
  assert.equal(tui.sanitizeCell('a\rb'), 'a b', 'CR becomes a space so the width does not shrink');
  assert.ok(!tui.sanitizeCell('a\x1bb').includes('\x1b'), 'a bare ESC cannot survive to swallow the next char');
});

test('textwidth: fitVisible holds the column budget and never leaks an attribute', () => {
  const padded = tui.fitVisible('\x1b[32mab\x1b[0m', 6);
  assert.equal(tui.displayWidth(padded), 6, 'padded to exactly the budget');
  assert.equal((padded.match(/\x1b\[0m/g) || []).length, 1, 'already-closed input is not double-reset');
  const clipped = tui.fitVisible('\x1b[32mabcdef', 3);
  assert.equal(tui.displayWidth(clipped), 3, 'clipped to exactly the budget');
  // A colour opened and then clipped away would bleed into the rest of the row, and on the last row
  // into the user's shell after dash exits.
  assert.ok(clipped.endsWith('\x1b[0m'), 'an open attribute is closed when the text is cut');
  assert.equal(tui.fitVisible('漢字', 3), '漢 ', 'a wide char that would straddle the edge is dropped whole');
  // Wrap, never ellipsize — the standing rule for content text.
  assert.deepEqual(tui.wrapVisible('one two three', 7), ['one two', 'three']);
  assert.ok(tui.wrapVisible('aaaaaaaaaa', 4).every((l) => tui.displayWidth(l) <= 4), 'a long word is hard-broken');
});

test('graphemes: a character ends after its accents, its skin tone, the emoji joined to it, its flag pair or its keycap mark', () => {
  // A session title cut at 64 UTF-16 units showed `👨‍👩‍�…`: half a family, then half of the next emoji's surrogate pair.
  // Intl.Segmenter knows where a character ends, and ends the process (SIGSEGV) on a Node with no full ICU data, so the
  // rule is core's own. Here Intl.Segmenter throws if anything touches it.
  const file = require.resolve('../dist/graphemes.js');
  const { Segmenter } = Intl;
  Intl.Segmenter = function () { throw new Error('Intl.Segmenter was used'); };
  delete require.cache[file];
  try {
    const g = require('../dist/graphemes.js');
    const hex = (cs) => cs.map((c) => [...c].map((ch) => ch.codePointAt(0).toString(16)).join(' '));
    const cases = [
      ['ab👨\u200d👩\u200d👧\u200d👦cd', ['a', 'b', '👨\u200d👩\u200d👧\u200d👦', 'c', 'd'], 'a family, joined by zero-width joiners'],
      ['ab🇯🇵cd', ['a', 'b', '🇯🇵', 'c', 'd'], 'a flag, two regional indicators'],
      ['🇯🇵🇺🇸🇺', ['🇯🇵', '🇺🇸', '🇺'], 'regional indicators pair from the first'],
      ['ab👍🏽cd', ['a', 'b', '👍🏽', 'c', 'd'], 'an emoji and its skin tone'],
      ['👩🏽\u200d💻!', ['👩🏽\u200d💻', '!'], 'a skin tone inside a joined sequence'],
      ['ab1\ufe0f\u20e3cd', ['a', 'b', '1\ufe0f\u20e3', 'c', 'd'], 'a keycap: the digit, a variation selector, the enclosing mark'],
      ['abe\u0301\u0302cd', ['a', 'b', 'e\u0301\u0302', 'c', 'd'], 'a letter and its combining marks'],
      ['\u0301x', ['\u0301', 'x'], 'a mark with no letter before it is a character of its own'],
      ['🏴\u{E0067}\u{E0062}\u{E0073}\u{E0063}\u{E0074}\u{E007F}!', ['🏴\u{E0067}\u{E0062}\u{E0073}\u{E0063}\u{E0074}\u{E007F}', '!'], 'a subdivision flag and its tags'],
      ['a\r\nb', ['a', '\r\n', 'b'], 'a CRLF line break is one'],
      ['a\u0301\nb', ['a\u0301', '\n', 'b'], 'a line break joins nothing'],
      ['x\u200d\ny', ['x\u200d', '\n', 'y'], 'a joiner never joins a line break'],
      ['é\u200d👩', ['é\u200d👩'], 'a joiner keeps the emoji after it, so no cut ends on one that joins'],
      ['a\u200db\u200d c', ['a\u200d', 'b\u200d', ' ', 'c'], 'a joiner joins no letter or space after it, as in UAX #29'],
      ['⛹\ufe0f\u200d♀\ufe0f!', ['⛹\ufe0f\u200d♀\ufe0f', '!'], 'nor does it leave out a symbol a joined sequence holds'],
      ['\u06a9\u062a\u0627\u0628\u200c\u0647\u0627', ['\u06a9', '\u062a', '\u0627', '\u0628\u200c', '\u0647', '\u0627'], 'a non-joiner stays with the letter before it, as in UAX #29'],
    ];
    for (const [s, want, what] of cases) assert.deepEqual(hex(g.graphemes(s)), hex(want), what);
    // Every cut, at every length: a head ends where a character does, and a tail starts where one does.
    for (const [s] of cases) {
      const ends = g.graphemes(s).reduce((at, c) => [...at, at[at.length - 1] + c.length], [0]);
      for (let max = 0; max <= s.length + 1; max++) {
        assert.equal(g.graphemeHead(s, max), s.slice(0, Math.max(...ends.filter((e) => e <= max))), `the head of ${JSON.stringify(s)} at ${max}`);
        assert.equal(g.graphemeTail(s, max), s.slice(Math.min(...ends.filter((e) => e >= s.length - max))), `the tail of ${JSON.stringify(s)} at ${max}`);
      }
    }
    // Two readings of one rule: the walk through a text (graphemes, graphemeEnd) and the test at one index from the code
    // points around it (graphemeHead and graphemeTail, which step over one character instead of walking from the start).
    // They agree at every index of texts drawn from the pieces above, controls, lone surrogates and astral marks.
    const pool = ['a', ' ', '\n', '\r', '\x7f', '\x85', 'e\u0301', '\u0301', '\u200d', '\u200c', '\ufe0f', '\u20e3', '1', '👨', '👩', '👍', '🏽', '🇯', '🇵', '🇺',
      '🏴', '\u{e0067}', '\u{e007f}', '❤', '漢', '\u{1d165}', '\u{e0100}', '\ud83d', '\udc68'];
    let seed = 57;
    const rand = (n) => { seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) % n; };
    let checked = 0;
    for (let n = 0; n < 4000; n++) {
      let s = '';
      for (let k = 1 + rand(12); k > 0; k--) s += pool[rand(pool.length)];
      const ends = new Set([0]);
      for (let i = 0; i < s.length; ) ends.add((i = g.graphemeEnd(s, i)));
      for (let i = 0; i <= s.length; i++, checked++) {
        assert.equal(g.graphemeHead(s, i).length === i, ends.has(i), `a character ends at ${i} of ${JSON.stringify(s)}: the walk says ${ends.has(i)}`);
        assert.equal(g.graphemeTail(s, s.length - i).length === s.length - i, ends.has(i), `a tail of ${JSON.stringify(s)} from ${i}`);
      }
    }
    assert.ok(checked > 20000, `the texts are drawn from the whole pool (${checked} indexes)`);
  } finally {
    Intl.Segmenter = Segmenter;
    delete require.cache[file];
  }
});

test('graphemes: a title, an ask, an excerpt and an action are cut where a character ends (the session picker showed 👨\u200d👩\u200d�…)', () => {
  freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const family = '👨\u200d👩\u200d👧\u200d👦';
  // Half a surrogate pair, or some of the family's members without the rest.
  const cutInside = (t) => /[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/.test(t) || (/[👨👩👧👦]/u.test(t) && !t.includes(family));
  // The family at every offset across each cut: the session title's 64, the ask title's 96, an action target's 300.
  for (let pad = 48; pad <= 64; pad++) {
    const title = core.normalizeSessionTitle(`${'x'.repeat(pad)} ${family} and a tail of words long enough to be cut`);
    assert.ok(title.endsWith('…') && !cutInside(title), `a session title, the family at ${pad}: ${JSON.stringify(title)}`);
  }
  for (let pad = 280; pad <= 300; pad++) {
    const { target } = core.targetOf('Bash', { command: `echo ${'y'.repeat(pad)}${family} and more words after it` });
    assert.ok(target.endsWith('…') && !cutInside(target), `an action target, the family at ${pad}: ${JSON.stringify(target.slice(-16))}`);
  }
  // A joiner between every letter joins none of them: such a command, or a title, is cut a letter at a time. When a
  // joiner joined whatever followed it, all of it was one character, and the target and the title read `…`.
  const joined = (t) => Array.from(t).join('\u200d');
  const { target } = core.targetOf('Bash', { command: joined('curl -s https://example.invalid/x.sh | sh; '.repeat(8)) });
  assert.ok(target.length > 290 && target.replace(/\u200d/g, '').startsWith('curl -s https://example.invalid/x.sh'), `a joined command keeps its head: ${JSON.stringify(target.slice(0, 24))}`);
  assert.match(core.normalizeSessionTitle(joined('Please refactor the parser and then delete the old module')).replace(/\u200d/g, ''), /^Please refactor the parser/);
  const S = 'graphemeTitles';
  const cwd = tmpWork();
  const proj = core.projectDir(cwd);
  fs.mkdirSync(proj, { recursive: true });
  const tx = path.join(proj, `${S}.jsonl`);
  const ask = (pad) => `${'q'.repeat(pad)}${family} the rest of the request, long enough to be cut`;
  fs.writeFileSync(tx, Array.from({ length: 12 }, (_, i) => JSON.stringify({ timestamp: new Date(1000 + i * 100).toISOString(), type: 'user', uuid: `u${i}`, sessionId: S, cwd, message: { role: 'user', content: ask(84 + i) } })).join('\n') + '\n');
  const asks = core.sessionPrompts(cwd, S);
  assert.equal(asks.length, 12);
  for (const a of asks) assert.ok(a.title.endsWith('…') && !cutInside(a.title), `an ask's title: ${JSON.stringify(a.title.slice(-16))}`);
  // The search's excerpt, with the family at each of its two edges, and the title of a hit with no title of its own.
  const hits = core.searchConversations(cwd, 'request').hits;
  assert.ok(hits.length > 0 && hits.every((h) => !cutInside(h.snippet)), `excerpts: ${JSON.stringify(hits.map((h) => h.snippet.slice(0, 12)))}`);
  // An excerpt runs 70 characters either side of the term: a family at each offset across both of its edges, one session each.
  for (let o = 0; o <= 11; o++) {
    const id = `graphemeHit${o}`;
    fs.writeFileSync(path.join(proj, `${id}.jsonl`), JSON.stringify({ timestamp: new Date(1000).toISOString(), type: 'user', uuid: 'u0', sessionId: id, cwd,
      message: { role: 'user', content: `${'w'.repeat(10)}${family}${'v'.repeat(59 + o)}needle${o}${'z'.repeat(69 - o)}${family} the end` } }) + '\n');
    const hit = core.searchConversations(cwd, `needle${o}`).hits[0];
    assert.ok(hit && !cutInside(hit.snippet), `the excerpt, the family at offset ${o}: ${JSON.stringify(hit?.snippet)}`);
  }
  // A title part a previous version cached, cut inside the family, is read again rather than shown.
  fs.writeFileSync(tx, JSON.stringify({ timestamp: new Date(1000).toISOString(), type: 'user', uuid: 'u0', sessionId: S, cwd, message: { role: 'user', content: `${'x'.repeat(55)} ${family} and then a long tail of words` } }) + '\n');
  const fresh = core.fastSessionTitle(tx, S);
  assert.ok(!cutInside(fresh), `read now: ${JSON.stringify(fresh)}`);
  const sidecar = path.join(core.rootDir(), 'session-meta', `${S}.json`);
  const kept = JSON.parse(fs.readFileSync(sidecar, 'utf8'));
  // Version 5 is the one before this cut: its parts could end inside an emoji.
  fs.writeFileSync(sidecar, JSON.stringify({ ...kept, stamp: kept.stamp.replace(/^\d+\|/, '5|'), parts: { ...kept.parts, prompt: `${'x'.repeat(55)} 👨\u200d👩\u200d\ud83d…` } }));
  assert.equal(core.fastSessionTitle(tx, S), fresh, 'a part cached by the previous version is read again');
});

test('memory: fileMemories agrees with fileMemory, and builds the index once', () => {
  freshHome();
  // Several sessions touching a shared file set, so the index has something to cross-reference and
  // the per-file form has many logs to revalidate against.
  const files = [];
  for (let f = 0; f < 5; f++) files.push(path.join(tmpWork(), `m${f}.js`));
  for (let s = 0; s < 3; s++) {
    const S = `mem${s}`;
    for (const f of files) {
      const id = seedEdit(S, f, 'a\n', 'a\nb\n');
      if (s === 0) core.setStatus(S, id, 'kept');
      if (s === 1) core.setStatus(S, id, 'undone');
    }
  }
  core.clearFsCache();

  // Equivalence first: a faster wrong answer is not a fix. Deep-equal covers lastVerdict and notes,
  // not just the counters.
  const batch = core.fileMemories(files);
  for (const f of files) assert.deepEqual(batch.get(f), core.fileMemory(f), `batch matches per-file for ${path.basename(f)}`);

  // Then the budget. Counting SYSCALLS, not milliseconds: the defect is a syscall count, and a
  // wall-clock assertion on this path is flaky on CI while this one is exact.
  const fs2 = require('fs');
  const counts = { stat: 0, exists: 0, readdir: 0 };
  const orig = { statSync: fs2.statSync, existsSync: fs2.existsSync, readdirSync: fs2.readdirSync };
  fs2.statSync = (...a) => (counts.stat++, orig.statSync(...a));
  fs2.existsSync = (...a) => (counts.exists++, orig.existsSync(...a));
  fs2.readdirSync = (...a) => (counts.readdir++, orig.readdirSync(...a));
  let batched, perFile;
  try {
    core.clearFsCache();
    core.fileMemories(files); // warm, so both forms are measured in steady state
    counts.stat = counts.exists = counts.readdir = 0;
    core.fileMemories(files);
    batched = { ...counts };
    counts.stat = counts.exists = counts.readdir = 0;
    for (const f of files) core.fileMemory(f);
    perFile = { ...counts };
  } finally {
    Object.assign(fs2, orig);
  }
  // The batch revalidates the index ONCE however many files it is asked about.
  assert.ok(batched.readdir <= 1, `batched readdir ${batched.readdir} <= 1`);
  assert.ok(batched.stat <= 2 * 3 + 2, `batched stat ${batched.stat} stays proportional to sessions, not files`);
  // Positive control: the per-file form pays that cost per file, so if the counters were broken (or
  // the batch silently fell back to per-file) this assertion fails and the budget above cannot pass
  // vacuously.
  assert.ok(perFile.stat >= batched.stat * files.length, `per-file stat ${perFile.stat} scales with files (batched ${batched.stat})`);
});

test('observe: every flag verdict fires, and only for its own trigger', () => {
  // All five verdicts now live in one memoized record, so a mistyped field name or a swapped pattern
  // silently disables a whole flag class rather than failing to compile. Two of these are the reason
  // to care: "possible hard-coded secret" and "adds a debug statement" are what a reviewer scans for.
  // Each alternation branch gets a case, because a regex that loses one branch still matches the rest.
  freshHome();
  const S = 'flagall';
  const seed = (name, added) => seedEdit(S, path.join(tmpWork(), name), 'const z = 0\n', `const z = 0\n${added}\n`);
  const msgs = (id) => core.flagsFor(S, core.findRecord(S, id)).map((f) => f.message).join(' | ');

  for (const marker of ['TODO', 'FIXME', 'XXX', 'HACK']) {
    assert.match(msgs(seed(`m_${marker}.txt`, `// ${marker} later`)), /TODO\/FIXME/, `${marker} raises the marker flag`);
  }
  for (const dbg of ['console.log(x)', 'debugger', 'print(x)', 'dbg!(x)']) {
    assert.match(msgs(seed(`d_${dbg.replace(/\W/g, '')}.txt`, dbg)), /debug statement/, `${dbg} raises the debug flag`);
  }
  for (const secret of ['api_key = "abc"', "api-key: 'abc'", 'secret = "abc"', 'password = "abc"', 'token = "abc"']) {
    assert.match(msgs(seed(`s_${secret.replace(/\W/g, '')}.txt`, secret)), /hard-coded secret/, `${secret} raises the secret flag`);
  }
  // The negative direction, which is what stops every assertion above passing on a flag that always
  // fires: ordinary code raises none of the three.
  const plain = msgs(seed('plain.txt', 'const total = a + b'));
  assert.doesNotMatch(plain, /TODO\/FIXME|debug statement|hard-coded secret/, `ordinary code is unflagged (got: ${plain})`);
  // And the count verdict, which shares the same record.
  const big = seedEdit(S, path.join(tmpWork(), 'big.txt'), Array.from({ length: 40 }, (_, i) => `l${i}`).join('\n') + '\n', 'l0\n');
  assert.match(msgs(big), /large deletion/, 'a large deletion is still counted from the same memo');
});

test('observe: an XXX-only edit earns the flag but not the follow-up step', () => {
  // The flag matches TODO|FIXME|XXX|HACK; the next step matches TODO|FIXME only. Both verdicts are
  // memoized off the same immutable blob pair, and collapsing them onto one boolean — the obvious
  // simplification — silently puts "follow up on the TODO" on edits that never mention one. On a real
  // store, that invented dozens of follow-ups.
  freshHome();
  const S = 'flagsplit';
  const marker = path.join(tmpWork(), 'marker.js');
  const todo = path.join(tmpWork(), 'todo.js');
  const xxxId = seedEdit(S, marker, null, 'const a = 1 // XXX revisit this\n');
  const todoId = seedEdit(S, todo, null, 'const b = 2 // TODO revisit this\n');

  const msgs = (id) => core.flagsFor(S, core.findRecord(S, id)).map((f) => f.message);
  assert.ok(msgs(xxxId).some((m) => /TODO\/FIXME/.test(m)), 'XXX earns the flag');
  assert.ok(msgs(todoId).some((m) => /TODO\/FIXME/.test(m)), 'TODO earns it as well');

  // Filtered to the FOLLOW-UP step specifically: both files are test-less sources, so both also earn
  // an "Add or update tests" step, and asserting on bare file mentions would fail for the wrong reason.
  const followUps = core.heuristicSuggestions(S).filter((s) => s.startsWith('Follow up on the TODO/FIXME'));
  // The positive half is what stops the negative half passing vacuously: if follow-ups ever stopped
  // being generated at all, this fails rather than the marker check quietly succeeding.
  assert.ok(followUps.some((s) => s.includes('todo.js')), 'the TODO edit earns a follow-up step');
  assert.ok(!followUps.some((s) => s.includes('marker.js')), 'the XXX-only edit does not');
});

test('classes: CRLF files and python classes with trailing comments are detected', () => {
  // CRLF brace language
  const br = core.detectClasses('import x;\r\nexport class Foo {\r\n  m() { return 1 }\r\n}\r\nclass Bar {}\r\n');
  assert.equal(br.length, 2, 'both CRLF brace classes found');
  assert.deepEqual([br[0].name, br[0].start, br[0].end], ['Foo', 1, 3]);
  // CRLF python
  const py = core.detectClasses('class P:\r\n    def m(self):\r\n        pass\r\nx = 1\r\n');
  assert.equal(py.length, 1);
  assert.deepEqual([py[0].name, py[0].end], ['P', 2], 'CR does not break the python end-of-line match');
  // python class with a trailing comment must be treated as python (indent span), not brace-matched
  const pyc = core.detectClasses('class C:  # frozen\n    def m(self):\n        d = {}\n    x = 1\nz = 2\n');
  assert.equal(pyc.length, 1);
  assert.deepEqual([pyc[0].name, pyc[0].start, pyc[0].end], ['C', 0, 3], 'span covers the indented body, not the dict brace');
});

test('memory: fileMemory aggregates a file\'s review history across sessions', () => {
  freshHome();
  const F = '/w/critical/api.ts';
  // session A: one accepted, one reverted; session B: one still pending
  const a1 = seedEdit('memA', F, null, 'v1\n');
  const a2 = seedEdit('memA', F, 'v1\n', 'v2\n');
  core.setStatus('memA', a1, 'kept');
  core.setStatus('memA', a2, 'undone');
  seedEdit('memB', F, 'v2\n', 'v3\n');
  seedEdit('memB', '/w/other.ts', null, 'x\n'); // different file — must not leak in
  // a cached Claude analysis for edit a1 becomes a memory note
  const fs2 = require('fs');
  const path2 = require('path');
  const ap = core.analysisPath('memA', 'edit-' + a1);
  fs2.mkdirSync(path2.dirname(ap), { recursive: true });
  fs2.writeFileSync(ap, JSON.stringify({ kind: 'edit', key: 'edit-' + a1, text: '**Summary** adds the v1 handler\nmore', ts: 5 }));

  const m = core.fileMemory(F);
  assert.equal(m.edits, 3, 'counts edits across both sessions');
  assert.equal(m.kept, 1);
  assert.equal(m.undone, 1);
  assert.equal(m.pending, 1);
  assert.equal(m.lastVerdict.status, 'undone', 'newest decided edit wins');
  assert.equal(m.notes.length, 1, 'cached analysis surfaces as a note');
  assert.equal(m.notes[0].text, 'adds the v1 handler', 'Summary prefix stripped');

  assert.equal(core.isRiskyFile(m), false, 'one revert is not yet risky');
  assert.equal(core.isRiskyFile({ ...m, undone: 2, kept: 1 }), true, 'repeat reverts flag as risky');
  assert.equal(core.isRiskyFile({ ...m, undone: 2, kept: 5 }), false, 'mostly-accepted files are not risky');

  const s = core.memorySummary(m, 10 * 60000 + 2000);
  assert.match(s, /3 edits across sessions/, 'summary counts');
  assert.match(s, /50% accepted/, 'summary acceptance rate');
  assert.match(s, /last reverted/, 'summary last verdict');
  assert.equal(core.memorySummary(core.fileMemory('/w/never-touched.ts')), '', 'no history -> empty summary');
});

test('diagnose: flags missing hooks and CLI-off-PATH, clears once installed', () => {
  freshHome();
  const work = tmpWork();
  const byId = (checks, id) => checks.find((c) => c.id === id);

  // Nothing installed yet: hooks are a hard failure with a fix hint.
  let checks = core.diagnose({ cwd: work, binOnPath: true, jqPresent: true });
  assert.equal(byId(checks, 'hooks').level, 'fail', 'missing hooks reported as a failure');
  assert.ok(byId(checks, 'hooks').fix, 'missing hooks carries a fix hint');
  assert.equal(byId(checks, 'settings-json').level, 'ok', 'absent settings.json is not "invalid"');

  // Install the portable, marker-based hook: the hooks check clears.
  core.installHooks('claude-observatory capture #' + core.HOOK_MARKER, core.settingsPath());
  checks = core.diagnose({ cwd: work, binOnPath: true, jqPresent: true });
  assert.equal(byId(checks, 'hooks').level, 'ok', 'hooks now ok');
  assert.equal(byId(checks, 'hook-shape'), undefined, 'marker hook does not trip the legacy warning');

  // An install from before an event existed still captures, so it is a warning that names the gap.
  const d = JSON.parse(fs.readFileSync(core.settingsPath(), 'utf8'));
  delete d.hooks.PostToolUseFailure;
  fs.writeFileSync(core.settingsPath(), JSON.stringify(d));
  const partial = byId(core.diagnose({ cwd: work, binOnPath: true, jqPresent: true }), 'hooks');
  assert.equal(partial.level, 'warn', 'a partial install is reported, not passed');
  assert.match(partial.detail, /not hooked: PostToolUseFailure$/);
  assert.match(partial.fix, /oak init/);
  core.installHooks('claude-observatory capture #' + core.HOOK_MARKER, core.settingsPath());
  assert.equal(byId(core.diagnose({ cwd: work, binOnPath: true, jqPresent: true }), 'hooks').level, 'ok', 'init completes it');

  // The CLI not resolving on PATH is a hard failure (capture would silently no-op).
  const off = core.diagnose({ cwd: work, binOnPath: false, jqPresent: true });
  assert.equal(byId(off, 'bin-path').level, 'fail', 'bin off PATH is a failure');

  // A hand-mangled settings.json is caught before anything else.
  const fs2 = require('fs');
  fs2.writeFileSync(core.settingsPath(), '{ not json');
  const broken = core.diagnose({ cwd: work, binOnPath: true, jqPresent: true });
  assert.equal(byId(broken, 'settings-json').level, 'fail', 'invalid settings.json flagged');
});

test('diagnose: a status line installed a moment ago is not told to install itself', () => {
  freshHome();
  const prev = process.env.CLAUDE_CONFIG_DIR;
  const cfg = tmpWork();
  process.env.CLAUDE_CONFIG_DIR = cfg;
  try {
    const row = (jqPresent = true) => core.diagnose({ cwd: tmpWork(), binOnPath: true, jqPresent }).find((c) => c.id === 'statusline');
    assert.match(row().fix, /oak statusline/, 'not installed: the fix installs it');
    // What `oak statusline` leaves: the script, and settings pointing at it. Claude Code has not drawn it yet.
    fs.writeFileSync(path.join(cfg, 'statusline.sh'), '#!/bin/bash\n');
    fs.writeFileSync(path.join(cfg, 'settings.json'), JSON.stringify({ statusLine: { type: 'command', command: `bash ${path.join(cfg, 'statusline.sh')}` } }));
    assert.equal(core.statuslineInstalled(), true, 'the fixture is the bundled status line');
    const installed = row();
    assert.equal(installed.level, 'ok');
    assert.match(installed.detail, /installed; its usage cache appears the next time Claude Code draws the status line/);
    assert.equal(installed.fix, undefined, 'no advice to install what is installed');
    assert.equal(row(false).level, 'warn', 'without jq it cannot draw');
    fs.writeFileSync(path.join(cfg, 'statusline-last.json'), '{}');
    assert.match(row().detail, /usage cache present/);
  } finally {
    if (prev === undefined) delete process.env.CLAUDE_CONFIG_DIR;
    else process.env.CLAUDE_CONFIG_DIR = prev;
  }
});

test('semver: compareVersions / isNewer order releases correctly', () => {
  assert.equal(core.compareVersions('0.3.0', '0.3.0'), 0);
  assert.equal(core.compareVersions('0.3.1', '0.3.0'), 1);
  assert.equal(core.compareVersions('0.4.0', '0.3.9'), 1);
  assert.equal(core.compareVersions('1.0.0', '0.9.9'), 1);
  assert.equal(core.compareVersions('v0.3.0', '0.3.0'), 0, 'a leading v is ignored');
  assert.equal(core.isNewer('0.4.0', '0.3.0'), true);
  assert.equal(core.isNewer('0.3.0', '0.3.0'), false);
  assert.equal(core.isNewer('0.2.0', '0.3.0'), false, 'an older release is not "newer"');
  assert.deepEqual(core.parseVersion('v1.2.3-beta.1'), [1, 2, 3], 'prerelease suffix ignored');
});

test('semver: channelReason places an install against its channel in the version menus\' words', () => {
  assert.equal(core.channelReason('0.11.0', '0.11.0'), 'current');
  assert.equal(core.channelReason('0.11.0', '0.10.0'), 'update available');
  assert.equal(core.channelReason('0.11.0', '0.12.0-dev.1'), 'not on this channel', 'an install above the channel is not current');
  assert.equal(core.channelReason('0.11.0', '0.11.0-dev.3'), 'update available', 'the release is newer than its pre-releases');
  assert.equal(core.channelReason(null, '0.11.0'), 'current', 'no known release: nothing to differ from');
  // A local build (dev.0, a version no release carries) is offered nothing, whichever way the channel lies.
  assert.equal(core.channelReason('0.11.0-dev.15', '0.11.0-dev.0'), 'local build');
  assert.equal(core.channelReason('0.10.0', '0.11.0-dev.0'), 'local build');
  assert.equal(core.channelReason(null, '0.11.0-dev.0'), 'local build');
  assert.equal(core.channelReason('0.11.0-dev.0', '0.11.0-dev.0'), 'current', 'unless the channel serves exactly that');
});

test('semver: isLocalBuild is a dev.0 version, which CI never publishes', () => {
  for (const v of ['0.11.0-dev.0', 'v0.11.0-dev.0', '0.11.0-dev.0+abc1234']) assert.equal(core.isLocalBuild(v), true, v);
  for (const v of ['0.11.0-dev.1', '0.11.0-dev.15', '0.11.0', '0.11.0-dev', '0.11.0-dev.0.1', '0.11.0-rc.0', '', null, undefined]) assert.equal(core.isLocalBuild(v), false, String(v));
});

test('review: reviewSummary aggregates per file + acceptance rate; markdown exports', () => {
  freshHome();
  const S = 'reviewsum';
  const A = path.join(tmpWork(), 'a.txt');
  const B = path.join(tmpWork(), 'b.txt');
  seedEdit(S, A, 'x\n', 'x\ny\n');            // #1 pending
  const i2 = seedEdit(S, A, 'x\ny\n', 'x\n');  // #2 -> keep
  const i3 = seedEdit(S, B, 'p\n', 'q\n');     // #3 -> undo
  core.setStatus(S, i2, 'kept');
  core.setStatus(S, i3, 'undone');
  const s = core.reviewSummary(S);
  assert.equal(s.total, 3);
  assert.equal(s.kept, 1);
  assert.equal(s.undone, 1);
  assert.equal(s.pending, 1);
  assert.equal(Math.round(s.acceptanceRate * 100), 50, '1 kept of 2 reviewed = 50%');
  assert.equal(s.files.length, 2, 'two files aggregated');
  assert.equal(s.reverted.length, 1);
  assert.equal(s.reverted[0].id, i3);
  const md = core.reviewSummaryMarkdown(s);
  assert.match(md, /review summary/i);
  assert.match(md, /50%/, 'markdown shows the acceptance rate');
  assert.match(md, /Reverted edits/, 'markdown lists reverted edits');
});

// Run the capture hook for a Bash tool call (no file_path — capture walks cwd).
function runHookBash(home, session, dir, event) {
  const payload = JSON.stringify({
    session_id: session, cwd: dir, hook_event_name: event, tool_name: 'Bash', tool_input: { command: 'true' },
  });
  return cp.execFileSync('node', [CAPTURE], { input: payload, env: { ...process.env, HOME: home }, encoding: 'utf8' });
}

test('capture: Bash tool full-snapshots cwd and records modify/create/delete (undoable)', () => {
  const home = freshHome();
  const dir = tmpWork();
  const A = path.join(dir, 'a.txt'); // modified
  const B = path.join(dir, 'b.txt'); // deleted
  const D = path.join(dir, 'd.txt'); // untouched
  fs.writeFileSync(A, 'one\n');
  fs.writeFileSync(B, 'gone\n');
  fs.writeFileSync(D, 'same\n');
  const S = 'bashSess';
  assert.equal(runHookBash(home, S, dir, 'PreToolUse'), '', 'Pre: no stdout');
  // simulate the Bash command's effects
  fs.writeFileSync(A, 'ONE\n');
  const C = path.join(dir, 'c.txt');
  fs.writeFileSync(C, 'brand new\n'); // created
  fs.unlinkSync(B); // deleted
  assert.equal(runHookBash(home, S, dir, 'PostToolUse'), '', 'Post: no stdout');

  const log = fs
    .readFileSync(path.join(home, '.claude', 'claude-observatory', S, 'log.jsonl'), 'utf8')
    .trim().split('\n').map(JSON.parse);
  const at = (f) => log.find((r) => r.file === f);
  assert.ok(at(A) && at(A).tool === 'Bash', 'modified file recorded as a Bash edit');
  assert.ok(at(A).beforeBlob && at(A).afterBlob && at(A).beforeBlob !== at(A).afterBlob, 'modify: before+after present (undoable)');
  assert.ok(at(C) && at(C).beforeBlob === null && at(C).afterBlob, 'created file: before null');
  assert.ok(at(B) && at(B).beforeBlob && at(B).afterBlob === null, 'deleted file: after null');
  assert.equal(at(D), undefined, 'untouched file produces no edit');
});

test('capture: CLAUDE_OBSERVATORY_NO_BASH opts out of Bash capture', () => {
  const home = freshHome();
  const dir = tmpWork();
  const F = path.join(dir, 'a.txt');
  fs.writeFileSync(F, 'one\n');
  const S = 'bashOff';
  const env = { ...process.env, HOME: home, CLAUDE_OBSERVATORY_NO_BASH: '1' };
  const bash = (event) => cp.execFileSync('node', [CAPTURE], {
    input: JSON.stringify({ session_id: S, cwd: dir, hook_event_name: event, tool_name: 'Bash', tool_input: {} }),
    env, encoding: 'utf8',
  });
  bash('PreToolUse');
  fs.writeFileSync(F, 'TWO\n');
  bash('PostToolUse');
  assert.equal(fs.existsSync(path.join(home, '.claude', 'claude-observatory', S, 'log.jsonl')), false, 'no log written when opted out');
});

test('capture: the Bash full-tree walk never snapshots secret files (.env), only ordinary edits', () => {
  const home = freshHome();
  const dir = tmpWork();
  const ENV = path.join(dir, '.env'); // secret — must NOT be captured
  const SRC = path.join(dir, 'app.js'); // ordinary — must be captured
  fs.writeFileSync(ENV, 'API_KEY=sk-secret-000\n');
  fs.writeFileSync(SRC, 'let x = 1;\n');
  const S = 'bashSecret';
  runHookBash(home, S, dir, 'PreToolUse');
  fs.writeFileSync(ENV, 'API_KEY=sk-secret-999\n'); // the Bash command "changed" both
  fs.writeFileSync(SRC, 'let x = 2;\n');
  runHookBash(home, S, dir, 'PostToolUse');

  const log = fs
    .readFileSync(path.join(home, '.claude', 'claude-observatory', S, 'log.jsonl'), 'utf8')
    .trim().split('\n').map(JSON.parse);
  assert.ok(log.some((r) => r.file === SRC), 'ordinary source edit is captured');
  assert.ok(!log.some((r) => r.file === ENV), '.env is never recorded');
  // and its secret content never lands in a blob
  const blobs = fs.readdirSync(path.join(home, '.claude', 'claude-observatory', S, 'blobs'));
  const anySecret = blobs.some((b) =>
    fs.readFileSync(path.join(home, '.claude', 'claude-observatory', S, 'blobs', b), 'utf8').includes('sk-secret')
  );
  assert.ok(!anySecret, 'no blob contains the .env secret');
});

test('store: session dirs are 0700 and blobs 0600 (not world/group-readable)', { skip: process.platform === 'win32' }, () => {
  freshHome();
  const S = 'perms';
  core.ensureStore(S);
  const sha = core.writeBlob(S, Buffer.from('secret-ish\n'));
  const dirMode = fs.statSync(core.storeDir(S)).mode & 0o777;
  const blobMode = fs.statSync(path.join(core.storeDir(S), 'blobs', sha)).mode & 0o777;
  assert.equal(dirMode & 0o077, 0, `store dir must have no group/other bits (got ${dirMode.toString(8)})`);
  assert.equal(blobMode & 0o077, 0, `blob must have no group/other bits (got ${blobMode.toString(8)})`);
});

test('install: re-init migrates a legacy matcher in place (adds Bash) without duplicating', () => {
  const home = freshHome();
  fs.mkdirSync(path.join(home, '.claude'), { recursive: true });
  const sp = path.join(home, '.claude', 'settings.json');
  const cmd = 'claude-observatory capture #claude-observatory-hook';
  // an old install: our command under the pre-Bash matcher
  fs.writeFileSync(sp, JSON.stringify({
    hooks: {
      PreToolUse: [{ matcher: 'Edit|Write|MultiEdit|NotebookEdit', hooks: [{ type: 'command', command: cmd }] }],
      PostToolUse: [{ matcher: 'Edit|Write|MultiEdit|NotebookEdit', hooks: [{ type: 'command', command: cmd }] }],
    },
  }));
  assert.ok(core.installHooks(cmd).changed, 're-init migrates the matcher');
  const d = JSON.parse(fs.readFileSync(sp, 'utf8'));
  assert.equal(d.hooks.PreToolUse.length, 1, 'no duplicate group');
  assert.equal(d.hooks.PreToolUse[0].hooks.length, 1, 'no duplicate command');
  assert.equal(d.hooks.PreToolUse[0].matcher, core.MATCHER, 'matcher upgraded to current');
  assert.ok(core.MATCHER.includes('Bash'), 'MATCHER now includes Bash');
  assert.equal(core.installHooks(cmd).changed, false, 'idempotent after migration');
});

test('tree: buildEditTree groups by folder/file with chain compaction + exact deltas', () => {
  freshHome();
  const S = 'treeview';
  const root = tmpWork();
  const A = path.join(root, 'src', 'a.ts');
  const B = path.join(root, 'src', 'util', 'deep', 'b.ts');
  fs.mkdirSync(path.dirname(A), { recursive: true });
  fs.mkdirSync(path.dirname(B), { recursive: true });
  fs.writeFileSync(A, 'x\ny\n');
  fs.writeFileSync(B, 'p\nq\n');
  seedEdit(S, A, 'x\n', 'x\ny\n');   // +1
  seedEdit(S, B, 'p\n', 'p\nq\n');   // +1

  const tree = core.buildEditTree(S, { root });
  assert.equal(tree.files.length, 0, 'nothing directly at root');
  assert.equal(tree.folders.length, 1, 'one top-level folder');
  const src = tree.folders[0];
  assert.equal(src.label, 'src', 'src not compacted (it holds a file and a subfolder)');
  assert.ok(src.files.some((f) => f.rel === 'src/a.ts'), 'a.ts sits directly under src');
  const util = src.folders.find((d) => d.label === 'util/deep');
  assert.ok(util, 'single-child chain util/deep is compacted into one node');
  assert.equal(util.files[0].rel, 'src/util/deep/b.ts');
  const aFile = src.files.find((f) => f.rel === 'src/a.ts');
  assert.equal(aFile.loose.length, 1, 'edit is loose (no class detected)');
  assert.equal(aFile.loose[0].added, 1, 'exact delta carried on the edit');

  // filter narrows by relative path
  const filtered = core.buildEditTree(S, { root, filter: 'a.ts' });
  const flatFiles = [];
  const walk = (n) => { flatFiles.push(...n.files.map((f) => f.rel)); n.folders.forEach(walk); };
  walk(filtered);
  assert.deepEqual(flatFiles, ['src/a.ts'], 'filter keeps only matching files');
});

test('actions: parseActions builds a typed timeline of every tool call, with results + edit links', () => {
  freshHome();
  const S = 'acts';
  const cwd = tmpWork();
  const F = path.join(cwd, 'app.ts');
  // store: two edits to F so the edit-category actions link to records #1 / #2 positionally.
  seedEdit(S, F, null, 'export const a = 1\n'); // #1
  seedEdit(S, F, 'export const a = 1\n', 'export const a = 2\n'); // #2
  const proj = core.projectDir(cwd);
  fs.mkdirSync(proj, { recursive: true });
  const tx = [
    { timestamp: '2026-07-13T10:00:00.000Z', message: { role: 'assistant', content: [
      { type: 'text', text: 'Exploring the code.' },
      { type: 'tool_use', id: 'tu1', name: 'Read', input: { file_path: F } },
      { type: 'tool_use', id: 'tu2', name: 'Grep', input: { pattern: 'const a', path: cwd } },
    ] } },
    { message: { role: 'user', content: [
      { type: 'tool_result', tool_use_id: 'tu1', is_error: false, content: 'ok' },
      { type: 'tool_result', tool_use_id: 'tu2', is_error: true, content: 'grep failed' },
    ] } },
    { timestamp: '2026-07-13T10:01:00.000Z', message: { role: 'assistant', content: [
      { type: 'text', text: 'Creating app.ts.' },
      { type: 'tool_use', id: 'tu3', name: 'Write', input: { file_path: F, content: '...' } },
    ] } },
    { message: { role: 'assistant', content: [{ type: 'thinking', thinking: 'Now run checks.' }] } }, // reasoning, no tool
    { timestamp: '2026-07-13T10:02:00.000Z', message: { role: 'assistant', content: [
      { type: 'tool_use', id: 'tu4', name: 'Bash', input: { command: 'npm test\n--silent', description: 'run tests' } },
      { type: 'tool_use', id: 'tu5', name: 'WebFetch', input: { url: 'https://example.com/docs' } },
      { type: 'tool_use', id: 'tu6', name: 'Agent', input: { description: 'audit deps', subagent_type: 'Explore' } },
      { type: 'tool_use', id: 'tu7', name: 'TodoWrite', input: { todos: [{ content: 'ship it', status: 'in_progress' }, { content: 'done', status: 'completed' }] } },
    ] } },
    { timestamp: '2026-07-13T10:03:00.000Z', message: { role: 'assistant', content: [
      { type: 'text', text: 'Bump to 2.' },
      { type: 'tool_use', id: 'tu8', name: 'Edit', input: { file_path: F } },
    ] } },
    // a subagent (sidechain) line — must be IGNORED (its calls live in subagents/*.jsonl).
    { isSidechain: true, message: { role: 'assistant', content: [{ type: 'tool_use', id: 'sx1', name: 'Read', input: { file_path: '/secret' } }] } },
  ].map((o) => JSON.stringify(o)).join('\n');
  fs.writeFileSync(path.join(proj, S + '.jsonl'), tx);

  const acts = core.parseActions(cwd, S);
  const byTool = (t) => acts.find((a) => a.tool === t);
  assert.equal(acts.length, 8, 'every main-chain tool call captured; the sidechain call excluded');

  // categories
  assert.equal(byTool('Read').category, 'read');
  assert.equal(byTool('Grep').category, 'search');
  assert.equal(byTool('Write').category, 'edit');
  assert.equal(byTool('Bash').category, 'exec');
  assert.equal(byTool('WebFetch').category, 'web');
  assert.equal(byTool('Agent').category, 'agent');
  assert.equal(byTool('TodoWrite').category, 'todo');

  // targets (one-line, tool-specific)
  assert.equal(byTool('Read').target, F);
  assert.equal(byTool('Grep').target, 'const a');
  assert.equal(byTool('Bash').target, 'npm test --silent', 'multiline command collapsed to one line');
  assert.equal(byTool('Bash').detail, 'run tests', 'detail stays the description');
  assert.equal(byTool('Bash').cmd, 'npm test\n--silent', 'the WHOLE command rides its own cmd field (2026-08-19)');
  assert.equal(byTool('WebFetch').target, 'https://example.com/docs');
  assert.equal(byTool('Agent').target, 'audit deps');
  assert.equal(byTool('Agent').detail, 'Explore');
  assert.match(byTool('TodoWrite').target, /ship it/, 'todo target surfaces the in-progress item');

  // result folding (ok / isError from the correlated tool_result)
  assert.equal(byTool('Read').ok, true);
  assert.equal(byTool('Grep').ok, false);
  assert.equal(byTool('Grep').isError, true, 'an errored tool_result folds onto its action');

  // reasoning carry-forward (same-message text, and a thinking-only preceding message)
  assert.equal(byTool('Read').reasoning, 'Exploring the code.');
  assert.equal(byTool('Bash').reasoning, 'Now run checks.', 'thinking-only message carries forward to the next call');

  // edit linking: Write -> store #1, Edit -> store #2 (positional per file); Bash is not edit-linked
  assert.equal(byTool('Write').editId, 1, 'Write links to store edit #1');
  assert.equal(byTool('Edit').editId, 2, 'Edit links to store edit #2');
  assert.equal(byTool('Bash').editId, undefined, 'a Bash action carries no single editId');

  // chronological + summary
  assert.ok(acts[0].ts > 0 && acts[0].ts <= acts[acts.length - 1].ts, 'actions are in chronological order with parsed timestamps');
  const sum = core.summarizeActions(acts);
  assert.equal(sum.total, 8);
  assert.equal(sum.errors, 1);
  assert.equal(sum.byCategory.edit, 2);
});

