  const AG2 = 'noinprog99';
  fs.writeFileSync(
    path.join(subDir, `agent-${AG2}.jsonl`),
    JSON.stringify({ isSidechain: true, message: { role: 'assistant', content: [{ type: 'tool_use', name: 'TodoWrite', input: { todos: [{ content: 'all done', status: 'completed' }] } }] } })
  );
