test('statusline: message ids recur across FILES — forks/resumes copy history, deduped once (0.10.0)', () => {
  // Per-file dedup overcounted a machine's week by nearly half or more —
  // a forked or resumed session copies its history into a NEW transcript while the original stays
  // on disk, so the same message.id lives in several files. The dedup must span files, INCLUDING
  // cold ones served from the per-file cache (which therefore stores id maps, not pre-summed
  // numbers). Second run re-reads through that cache and must report the same totals — a cache
  // that re-inflates on the cached path would pass any single-run test.
  const sh = fs.readFileSync(path.resolve(__dirname, '../../cli/statusline/install-statusline.sh'), 'utf8');
  const lines = sh.split('\n');
  const from = lines.findIndex((l) => l.includes("<<'PYEOF'"));
  const to = lines.indexOf('PYEOF', from + 1);
  const py = lines.slice(from + 1, to).join('\n');

  const home = freshHome();
  const proj = path.join(home, 'projects', 'p1');
  fs.mkdirSync(proj, { recursive: true });
  const own = path.join(home, 'proj');
  const now = Date.UTC(2026, 8, 20, 12); // pinned mid-month: fixture ages must stay inside the bill cycle
  const iso = (ms) => new Date(ms).toISOString();
  const L = (ts, id, tok, reads = 0) =>
    JSON.stringify({ timestamp: ts, cwd: own, message: { id, usage: { input_tokens: tok, output_tokens: 0, cache_creation_input_tokens: 0, cache_read_input_tokens: reads } } }) + '\n';
  // The live session: msgX (minted 3 days ago — a resumed conversation) plus fresh work msgZ,
  // which also read 7000 cached tokens.
  fs.writeFileSync(path.join(proj, 'live.jsonl'), L(iso(now - 3 * 86400_000), 'msgX', 300, 2000) + L(iso(now - 60_000), 'msgZ', 40, 7000));
  // A fork made earlier carries the SAME msgX with its ORIGINAL timestamp — file cold (6h old).
  const fork = path.join(proj, 'fork.jsonl');
  fs.writeFileSync(fork, L(iso(now - 3 * 86400_000), 'msgX', 300, 2000) + L(iso(now - 3 * 86400_000), 'msgY', 50));
  // And a second cold fork also carrying msgY.
  const fork2 = path.join(proj, 'fork2.jsonl');
  fs.writeFileSync(fork2, L(iso(now - 3 * 86400_000), 'msgY', 50));
  const cold = new Date(now - 6 * 3600_000);
  fs.utimesSync(fork, cold, cold);
  fs.utimesSync(fork2, cold, cold);

  const state = path.join(home, 'usage-state.json');
  const env = { ...process.env, HOME: home, USERPROFILE: home, STATUSLINE_SCAN_ALARM: '30', STATUSLINE_NOW: String(now / 1000) };
  const run = () => {
    const r = require('child_process').spawnSync('python3', ['-', state, proj, '10', '0', '20', '0'], { input: py, encoding: 'utf8', env });
    return r;
  };
  const r1 = run();
  if (r1.error && r1.error.code === 'ENOENT') return; // no python3 on this runner
  assert.equal(r1.status, 0, `scan must run — python said: ${(r1.stderr || '').trim()}`);
  let st = JSON.parse(fs.readFileSync(state, 'utf8'));
  assert.equal(st.U7, 390, 'msgX once (300, not 600 across live+fork) + msgY once (50, not 100) + fresh msgZ (40)');
  assert.equal(st.R30, 9000, 'cache READS sum beside the unit, deduped the same way (msgX 2000 once across two files + msgZ 7000) — charged volume, never mixed into the quota unit');
  assert.equal(st.U5, 40, 'the 5h window holds only the freshly-minted work — a copy never re-bills its window');
  const cached = Object.values(st.fc).some((c) => c && c.ids && Object.keys(c.ids).length);
  assert.ok(cached, 'cold files cache their ID MAPS — a pre-summed number cannot be deduplicated later');

  // Second pass THROUGH the cache: force the scan gate open, keep fc.
  st.last_scan = 0;
  fs.writeFileSync(state, JSON.stringify(st));
  const r2 = run();
  assert.equal(r2.status, 0, `cached-path scan must run — ${(r2.stderr || '').trim()}`);
  const st2 = JSON.parse(fs.readFileSync(state, 'utf8'));
  assert.equal(st2.U7, 390, 'the cached path reports the SAME deduped totals (the positive control)');
});

test('install-extensions: detects an editor that does NOT yet have our extension (0.10.0)', async () => {
  // `update` refreshes only what is already installed — deliberately. This command is the other half,
  // and the detection it needs is different: it must see a bare editor. Fake HOME, real dirs.
  const home = freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;

  // The releases API is POINTED AT A LOCAL MOCK. The first version of this test let it reach
  // api.github.com, which answers 403 to an unauthenticated CI runner — so it passed on Linux, failed on
  // macOS and Windows, and would have been flaky forever.
  const http = require('http');
  const srv = http.createServer((_req, res) => {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(
      JSON.stringify([
        {
          tag_name: 'v9.9.9',
          prerelease: false,
          draft: false,
          assets: [
            { name: 'claude-observatory-vscode-v9.9.9.vsix', browser_download_url: 'http://127.0.0.1:1/x.vsix' },
          ],
        },
      ])
    );
  });
  // await 'listening' (srv.address() is null before it), and unref so a failed assertion can never
  // leave a listening handle holding the whole suite open.
  await new Promise((r) => srv.listen(0, '127.0.0.1', r));
  srv.unref();

  // APPDATA too: jetbrainsPluginDirs() scans %APPDATA%\JetBrains unconditionally, so without this a
  // Windows contributor with PyCharm installed would see their REAL IDEs in these assertions.
  const env = {
    ...process.env,
    HOME: home,
    USERPROFILE: home,
    APPDATA: path.join(home, 'AppData', 'Roaming'),
    CLAUDE_OBSERVATORY_RELEASES_API: `http://127.0.0.1:${srv.address().port}`,
    CLAUDE_OBSERVATORY_NO_UPDATE_CHECK: '1',
  };

  // ASYNC exec, not execFileSync: the mock server runs in THIS process, so a sync child would block the
  // event loop that has to answer it — a 106-second timeout instead of a test.
  const run = (args, envOverride) =>
    new Promise((resolve, reject) => {
      cp.execFile('node', [CLI, 'install-extensions', ...args], { env: envOverride || env, encoding: 'utf8' }, (err, stdout, stderr) => {
        if (err) reject(new Error(`${args.join(' ')} failed: ${stderr || stdout || err.message}`));
        else resolve(stdout);
      });
    });
  const check = async (...extra) => JSON.parse(await run(['--check', '--json', ...extra]));

  try {
    // A fake HOME isolates the extension DIRS but not PATH, so an editor whose CLI is genuinely on this
    // machine still reports present — which is correct, and is the whole point of the `or` in
    // editorPresent: installed-but-never-launched has a CLI and no extensions dir.
    let d = await check();
    assert.deepEqual(d.jetbrains, [], 'no plugin dirs -> no JetBrains');
    assert.equal(d.version, '9.9.9', 'the reported version comes from the resolved release');
    assert.ok(
      d.vscode.every((r) => r.installed === null),
      'under a fresh HOME nothing of ours is installed in any detected editor'
    );

    // An editor that has RUN but does not have our extension: the case `update` ignores and this acts on.
    fs.mkdirSync(path.join(home, '.vscode', 'extensions'), { recursive: true });
    d = await check();
    const vsc = () => d.vscode.find((r) => r.label === 'VS Code');
    assert.ok(vsc(), 'an empty extensions dir is still a PRESENT editor');
    assert.equal(vsc().present, true);
    assert.equal(vsc().installed, null, 'and it reports our extension as not installed');

    // Now give it our extension: same row, now with a version.
    fs.mkdirSync(path.join(home, '.vscode', 'extensions', 'cell-observatory.oak-observatory-vscode-0.9.0'), {
      recursive: true,
    });
    d = await check();
    assert.equal(vsc().installed, '0.9.0', 'the installed version is read from the folder name');

    // 0.9.5 — THE EDITOR'S OWN REGISTRY WINS OVER LEFTOVER FOLDERS.
    //
    // An editor does not delete the previous version's folder when it installs a new one, and the
    // scan took the highest folder it could find. So after a switch DOWN to stable, the abandoned
    // higher folder made us keep reporting the version we had just replaced — the machine looked
    // permanently current and could never be moved again. extensions.json lists what is LOADED, one
    // row per extension, which is the only thing an update should reason about.
    const extDir = path.join(home, '.vscode', 'extensions');
    fs.mkdirSync(path.join(extDir, 'cell-observatory.oak-observatory-vscode-0.10.0-dev.12'), { recursive: true });
    fs.writeFileSync(
      path.join(extDir, 'extensions.json'),
      JSON.stringify([
        { identifier: { id: 'cell-observatory.oak-observatory-vscode' }, version: '0.9.0', relativeLocation: 'cell-observatory.oak-observatory-vscode-0.9.0' },
      ])
    );
    d = await check();
    assert.equal(vsc().installed, '0.9.0', 'the registry decides, so an orphaned higher folder cannot re-strand the install');

    // Corrupt or absent registry is NOT "nothing installed" — fall back to the folders rather than
    // reporting a clean absence we never verified.
    fs.writeFileSync(path.join(extDir, 'extensions.json'), '{ this is not json');
    d = await check();
    assert.equal(vsc().installed, '0.10.0-dev.12', 'an unreadable registry falls back to the folder scan');
    fs.rmSync(path.join(extDir, 'extensions.json'));
    fs.rmSync(path.join(extDir, 'cell-observatory.oak-observatory-vscode-0.10.0-dev.12'), { recursive: true });

    // A JetBrains IDE with no plugin of ours — again, present and actionable.
    const jb = path.join(home, 'Library', 'Application Support', 'JetBrains', 'PyCharm2026.1', 'plugins');
    fs.mkdirSync(jb, { recursive: true });
    d = await check();
    assert.equal(d.jetbrains.length, 1, 'a plugins dir is a present IDE even with no plugin of ours');
    assert.equal(d.jetbrains[0].installed, null);

    // The scope flags must agree with what a real run would do, or an installer acts on a wrong report.
    assert.equal((await check('--vscode-only')).jetbrains.length, 0, '--vscode-only hides the JetBrains surface');
    assert.equal((await check('--jetbrains-only')).vscode.length, 0, '--jetbrains-only hides the VS Code surface');

    // A DETECTION report must survive an unreachable feed — CI runners get 403 from api.github.com, and
    // an installer asking "what is on this machine?" should not die of it.
    const offline = JSON.parse(
      await run(['--check', '--json'], { ...env, CLAUDE_OBSERVATORY_RELEASES_API: 'http://127.0.0.1:1/nope' })
    );
    assert.equal(offline.version, null, 'the version is honestly null rather than a guess');
    assert.ok(offline.vscode.length >= 1, 'and detection still reports what is on the machine');

    // Bad input fails loudly rather than installing something unintended.
    for (const args of [['--vsix', path.join(home, 'nope.vsix')], ['--channel'], ['--channel', 'bogus']]) {
      await assert.rejects(() => run(args), /no such file|requires a value|unknown channel/, `install-extensions ${args.join(' ')} must fail loudly`);
    }
  } finally {
    srv.close();
  }
});

test('install-extensions: Cursor\'s agent shim is not the editor (2026-11-09)', { skip: process.platform === 'win32' && 'the shim is a POSIX script' }, () => {
  // Cursor's agent CLI puts a `cursor` script in ~/.local/bin that runs the next `cursor` on PATH and, with none,
  // exits 1. Taken for the editor, `--install-extension` failed through it on a machine with no Cursor app on PATH.
  const home = freshHome();
  const shimDir = path.join(home, '.local', 'bin');
  const ideDir = path.join(home, 'cursor-app', 'bin');
  fs.mkdirSync(shimDir, { recursive: true });
  fs.mkdirSync(ideDir, { recursive: true });
  fs.mkdirSync(path.join(home, '.cursor', 'extensions'), { recursive: true }); // Cursor has run here, so its row is listed
  const shim = path.join(shimDir, 'cursor');
  fs.writeFileSync(shim, '#!/bin/sh\n# A stand-in for the agent CLI\'s shim, with its message.\n' +
    'echo "Error: No Cursor IDE installation found. Use \'cursor agent\' or \'agent\' to run the agent." >&2\nexit 1\n', { mode: 0o755 });
  const ide = path.join(ideDir, 'cursor');
  const cursorRow = (PATH) => {
    const env = { ...process.env, HOME: home, USERPROFILE: home, PATH, CLAUDE_OBSERVATORY_RELEASES_API: 'http://127.0.0.1:1/offline', CLAUDE_OBSERVATORY_NO_UPDATE_CHECK: '1' };
    delete env.CLAUDE_CONFIG_DIR;
    const out = cp.execFileSync(process.execPath, [CLI, 'install-extensions', '--check', '--json', '--vscode-only'], { env, encoding: 'utf8' });
    return JSON.parse(out).vscode.find((r) => r.label === 'Cursor');
  };
  const sys = '/usr/bin:/bin';
  // The shim alone. A Cursor this machine has in /usr/bin or /Applications is its own command, never the shim.
  const alone = cursorRow(`${shimDir}:${sys}`);
  assert.ok(alone, 'an editor that has run is listed');
  assert.notEqual(alone.cli, 'cursor', 'the bare name runs the shim');
  assert.notEqual(alone.cli, shim, 'and so does its path, where a Linux install is also looked for');
  // The editor's own command later on PATH is the one OAK drives, not the shim ahead of it.
  fs.writeFileSync(ide, '#!/bin/sh\nexit 0\n', { mode: 0o755 });
  assert.equal(cursorRow(`${shimDir}:${ideDir}:${sys}`).cli, ide);
  // With the editor's command first, as before: the bare name.
  assert.equal(cursorRow(`${ideDir}:${shimDir}:${sys}`).cli, 'cursor');
});

test('install-extensions: inside WSL, Windows\' own VS Code on PATH is skipped with a note, not failed (section 8)', { skip: process.platform !== 'linux' && 'WSL is Linux' }, () => {
  // Through interop, the `code` on PATH is the sh script Windows' VS Code keeps in bin\ beside code.cmd. It drives
  // Windows' editor, which cannot read this distro's paths: bootstrap.sh's install failed through it.
  const home = freshHome();
  const winBin = path.join(home, 'mnt', 'c', 'Microsoft VS Code', 'bin');
  fs.mkdirSync(winBin, { recursive: true });
  const ran = path.join(home, 'code-ran');
  fs.writeFileSync(path.join(winBin, 'code'), `#!/bin/sh\necho "$*" >> '${ran}'\nexit 1\n`, { mode: 0o755 });
  fs.writeFileSync(path.join(winBin, 'code.cmd'), '@echo off\r\n');
  const vsix = path.join(home, 'oak.vsix');
  fs.writeFileSync(vsix, 'not a real vsix');
  const run = (wsl) => {
    const env = { ...process.env, HOME: home, USERPROFILE: home, PATH: `${winBin}:/usr/bin:/bin`, CLAUDE_OBSERVATORY_RELEASES_API: 'http://127.0.0.1:1/offline', CLAUDE_OBSERVATORY_NO_UPDATE_CHECK: '1' };
    delete env.CLAUDE_CONFIG_DIR; delete env.WSL_DISTRO_NAME; delete env.WSLENV;
    if (wsl) env.WSL_DISTRO_NAME = 'Ubuntu';
    // Unscoped, as bootstrap.sh runs it; --vsix keeps the run offline.
    return cp.spawnSync(process.execPath, [CLI, 'install-extensions', '--vsix', vsix], { env, encoding: 'utf8' });
  };
  let r = run(true);
  assert.equal(r.status, 0, r.stdout + r.stderr);
  assert.match(r.stdout, /VS Code: the `code` on PATH is Windows' own, reached through WSL interop — skipped\./);
  assert.match(r.stdout, /install OAK on Windows \(install\.ps1\)[^\n]*connected to WSL runs it from this distro's VS Code server/);
  assert.doesNotMatch(r.stdout, /VS Code family: no editor detected/, 'not contradicted by the line after it');
  assert.ok(!fs.existsSync(ran), 'Windows\' code is not run');
  // Control: outside WSL the same `code` is an editor's CLI, run and failed.
  r = run(false);
  assert.equal(r.status, 1, r.stdout + r.stderr);
  assert.match(r.stdout, /VS Code --install-extension failed/);
  assert.equal(fs.readFileSync(ran, 'utf8'), `--install-extension ${vsix} --force\n`);
});

test('install-extensions: installs a LOCAL artifact into a bare JetBrains IDE (0.10.0)', () => {
  // The from-source path install.sh uses: --jetbrains-zip, no network, and it must install even though
  // nothing of ours is there yet. Exercises zipToolReady + applyJetbrainsZip + the version sentinel.
  const home = freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const env = {
    ...process.env,
    HOME: home,
    USERPROFILE: home,
    APPDATA: path.join(home, 'AppData', 'Roaming'),
    CLAUDE_OBSERVATORY_NO_UPDATE_CHECK: '1',
  };
  const jb = path.join(home, 'Library', 'Application Support', 'JetBrains', 'PyCharm2026.1', 'plugins');
  fs.mkdirSync(jb, { recursive: true });

  // A plugin zip shaped like the real asset: oak-observatory-jetbrains/lib/<name>-<version>.jar.
  // Written by writeStoredZip rather than shelling out to `zip`: the product deliberately avoids
  // zip/unzip on Windows (extractZip uses PowerShell's Expand-Archive), so demanding a `zip` binary
  // would make this test need MORE of the environment than the code it tests — and windows-latest does
  // not list one.
  const stage = tmpDir('cc-jbzip-');
  const zip = path.join(stage, 'oak-observatory-jetbrains-v9.9.9.zip');
  writeStoredZip(zip, [
    ['oak-observatory-jetbrains/lib/oak-observatory-jetbrains-9.9.9.jar', Buffer.from('x')],
  ]);

  const out = cp.execFileSync('node', [CLI, 'install-extensions', '--jetbrains-only', '--jetbrains-zip', zip], {
    env,
    encoding: 'utf8',
  });
  assert.match(out, /JetBrains plugin →/, 'it reports the install');
  const dir = path.join(jb, 'oak-observatory-jetbrains');
  assert.ok(fs.existsSync(path.join(dir, 'lib', 'oak-observatory-jetbrains-9.9.9.jar')), 'the jar landed');
  // A local artifact installs at the CLI's OWN version — no release is fetched in this mode at all,
  // which is what makes install.sh's from-source path work offline.
  // `--version` prints "claude-observatory <semver>", so take the semver out of it.
  const cliVersion = /(\d+\.\d+\.\d+[^\s]*)/.exec(
    cp.execFileSync('node', [CLI, '--version'], { env, encoding: 'utf8' })
  )[1];
  assert.equal(
    fs.readFileSync(path.join(dir, '.observatory-version'), 'utf8').trim(),
    cliVersion,
    'the version sentinel is stamped, so a later `update` can tell what is installed'
  );
});

test('installers: every install path goes through the CLI, and offers both channels (0.10.0)', () => {
  // These scripts are not exercised by any test run (e2e is skipped on Windows and none of them run
  // here), so their CONTENT is the only thing that can be pinned. Each assertion below corresponds to a
  // defect that shipped: bash reimplementing editor detection, JetBrains only ever being downloaded and
  // never installed, and no way at all to install the pre-release channel.
  const read = (p) => fs.readFileSync(path.resolve(__dirname, '../../..', p), 'utf8');
  // Assert about CODE, not prose: these files explain in comments what they used to do wrong, and a
  // blunt doesNotMatch cannot tell the explanation from the mistake.
  const code = (s) =>
    s
      .split('\n')
      .filter((l) => !/^\s*(?:#|<#|\.[A-Z]|\s*$)/.test(l))
      .join('\n');

  const boot = read('scripts/bootstrap.sh');
  assert.match(boot, /install-extensions --channel/, 'bootstrap delegates editor install to the CLI');
  assert.match(boot, /--channel stable\|dev/, 'and documents the channel flag');
  assert.match(boot, /dev-latest/, 'the dev channel resolves the rolling pre-release tag');
  assert.doesNotMatch(code(boot), /Install Plugin from Disk/, 'it must INSTALL the JetBrains plugin, not print instructions');
  assert.doesNotMatch(code(boot), /code --install-extension/, 'and must not hand-roll the VS Code install');

  const inst = read('install.sh');
  assert.match(inst, /install-extensions/, 'the from-source installer delegates too');
  assert.match(inst, /--vsix/, 'passing the locally built .vsix rather than downloading one');
  assert.match(inst, /--jetbrains/, 'and can build + install the JetBrains plugin');
  assert.doesNotMatch(code(inst), /^\s*code --install-extension/m, 'no hand-rolled VS Code install');

  const jb = read('scripts/install-jetbrains.sh');
  assert.match(jb, /install-extensions --jetbrains-only --jetbrains-zip/, 'JetBrains install delegates to the CLI');
  assert.match(jb, /--build-only/, 'and exposes the build-only mode install.sh uses');
  assert.doesNotMatch(code(jb), /unzip -qo/, 'the bash unzip + dir-walk is gone (it never worked outside Git Bash)');

  const ps1 = read('install.ps1');
  assert.match(ps1, /install-extensions/, 'the Windows installer delegates too');
  assert.match(ps1, /Get-FileHash/, 'and verifies the CLI tarball sha256 like downloadAsset does');
  assert.match(ps1, /\$Channel/, 'and offers the channel choice');
  assert.match(ps1, /jq/, 'and is honest about the bash+jq status line');
});

test('installers: install.ps1 parses as PowerShell', { skip: !hasPwsh() }, () => {
  // A syntax error in this file is invisible until a Windows user pipes it into iex and it half-runs.
  // pwsh ships on the windows-latest runner, so CI checks it even though a mac dev machine usually
  // cannot.
  const ps1 = path.resolve(__dirname, '../../../install.ps1');
  const script =
    "$e = $null; [void][System.Management.Automation.Language.Parser]::ParseFile('" +
    ps1.replace(/'/g, "''") +
    "', [ref]$null, [ref]$e); if ($e -and $e.Count -gt 0) { $e | ForEach-Object { Write-Output $_.Message }; exit 1 }";
  const r = cp.spawnSync('pwsh', ['-NoProfile', '-NonInteractive', '-Command', script], { encoding: 'utf8' });
  assert.equal(r.status, 0, `install.ps1 has PowerShell syntax errors:\n${r.stdout}${r.stderr}`);
});

test('installers: install.ps1\'s dev channel installs the newer of the pre-release and the latest release', { skip: !hasPwsh() }, () => {
  // Its own block, run with the release API stubbed: bootstrap.sh's run against fake releases is in gates.test.js.
  const ps1 = fs.readFileSync(path.resolve(__dirname, '../../../install.ps1'), 'utf8');
  const start = ps1.indexOf("    if ($Channel -eq 'dev') {", ps1.indexOf('The dev channel serves the newest build'));
  const block = ps1.slice(start, ps1.indexOf('\n    }\n', start) + 6);
  assert.match(block, /Invoke-RestMethod[\s\S]*\$rel = \$stable/, 'the block that compares the two releases');
  const pick = (pre, latest) => {
    const script = [
      "function Say($m) { Write-Output \"say: $m\" }",
      latest ? `function Invoke-RestMethod { param($Uri, $Headers, [switch]$UseBasicParsing) if ($Uri -notlike '*/releases/latest') { throw 'unexpected' }; [pscustomobject]@{ tag_name = '${latest}' } }`
        : "function Invoke-RestMethod { throw 'offline' }",
      "$Channel = 'dev'; $Repo = 'owner/repo'",
      `$rel = [pscustomobject]@{ tag_name = 'dev-latest'; name = 'Pre-release ${pre} (rolling, from dev)' }`,
      block,
      'Write-Output "picked: $($rel.tag_name)"',
    ].join('\n');
    const r = cp.spawnSync('pwsh', ['-NoProfile', '-NonInteractive', '-Command', script], { encoding: 'utf8' });
    assert.equal(r.status, 0, r.stdout + r.stderr);
    return r.stdout;
  };
  // Right after a release, before the next push to dev: 9.9.9 outranks 9.9.9-dev.4.
  assert.match(pick('9.9.9-dev.4', 'v9.9.9'), /say: The latest release is newer than the pre-release[\s\S]*picked: v9\.9\.9/);
  assert.match(pick('9.10.0-dev.1', 'v9.9.9'), /picked: dev-latest/, 'a pre-release ahead of the release');
  assert.match(pick('9.9.9-dev.4', null), /picked: dev-latest/, 'no release to compare with');
});

test('installers: install.ps1 installs the status line with Git Bash, and says "Git Bash not found" rather than take the WSL launcher (section 1)', { skip: !hasPwsh() }, () => {
  // Find-GitBash and the status-line block, run with stand-in files for System32\bash.exe (the WSL
  // launcher), Git in Program Files and git on PATH, with `oak` stubbed. The environment is set inside the
  // script so pwsh itself starts with the real one.
  const ps1 = fs.readFileSync(path.resolve(__dirname, '../../../install.ps1'), 'utf8');
  const fnAt = ps1.indexOf('function Find-GitBash {');
  const fn = ps1.slice(fnAt, ps1.indexOf('\n}\n', fnAt) + 3);
  const blockAt = ps1.indexOf('    # --- status line');
  const block = ps1.slice(blockAt, ps1.indexOf('    # --- capture hooks', blockAt));
  assert.ok(fnAt > 0 && blockAt > 0, 'the function and the status-line block');
  const t = tmpWork();
  const file = (rel, exec) => {
    const f = path.join(t, ...rel.split('/'));
    fs.mkdirSync(path.dirname(f), { recursive: true });
    fs.writeFileSync(f, exec ? '#!/bin/sh\nexit 0\n' : '');
    if (exec) fs.chmodSync(f, 0o755);
    return f;
  };
  // The launcher answers to `bash` on PATH, as System32\bash.exe does on Windows.
  const wsl = file('Windows/System32/bash.exe'); file('Windows/System32/bash', true);
  const pfBash = path.join(t, 'PF', 'Git', 'bin', 'bash.exe');
  const appsBash = path.join(t, 'Apps', 'Git', 'bin', 'bash.exe');
  const q = (s) => `'${s.replace(/'/g, "''")}'`;
  const run = ({ setBash, pathDirs }) => {
    const script = [
      "function Say($m) { Write-Output \"say: $m\" }", "function Warn($m) { Write-Output \"warn: $m\" }",
      "function Ok($m) { Write-Output \"ok: $m\" }", "function Dim($m) { Write-Output \"dim: $m\" }",
      "function oak { $global:oakRan = \"$args\"; $global:LASTEXITCODE = 0 }", 'function jq { }',
      `$env:SystemRoot = ${q(path.join(t, 'Windows'))}; $env:ProgramFiles = ${q(path.join(t, 'PF'))}`,
      "Remove-Item -LiteralPath 'Env:ProgramFiles(x86)' -ErrorAction SilentlyContinue",
      `$env:CLAUDE_CODE_GIT_BASH_PATH = ${setBash ? q(setBash) : '$null'}`,
      `$env:PATH = ${q(pathDirs.map((d) => path.join(t, ...d.split('/'))).join(path.delimiter))}`,
      fn, block,
      'Write-Output "found: $(Find-GitBash)"; Write-Output "oak ran: $global:oakRan"',
    ].join('\n');
    const r = cp.spawnSync('pwsh', ['-NoProfile', '-NonInteractive', '-Command', script], { encoding: 'utf8' });
    assert.equal(r.status, 0, r.stdout + r.stderr);
    return r.stdout.replace(/\r\n/g, '\n');
  };
  const sys32 = ['Windows/System32'];
  let out = run({ pathDirs: sys32 });
  assert.match(out, /warn: Skipped the bundled status line: Git Bash not found\./, 'only the WSL launcher: no Git Bash');
  assert.match(out, /dim: winget install Git\.Git/);
  assert.match(out, /^found: $/m);
  assert.match(out, /^oak ran: $/m, 'and `oak statusline` is not run');
  out = run({ setBash: wsl, pathDirs: sys32 });
  assert.match(out, /^found: $/m, 'CLAUDE_CODE_GIT_BASH_PATH naming the WSL launcher is passed over too');

  file('PF/Git/bin/bash.exe');
  out = run({ pathDirs: sys32 });
  assert.ok(out.includes(`found: ${pfBash}\n`), out);
  assert.match(out, /ok: Status line installed/);
  assert.match(out, /^oak ran: statusline$/m);
  const custom = file('Tools/bash.exe');
  assert.ok(run({ setBash: custom, pathDirs: sys32 }).includes(`found: ${custom}\n`), 'CLAUDE_CODE_GIT_BASH_PATH comes first');
  assert.ok(run({ setBash: path.join(t, 'Tools', 'git.exe'), pathDirs: sys32 }).includes(`found: ${pfBash}\n`), 'unless it names no bash');

  fs.rmSync(path.join(t, 'PF'), { recursive: true });
  file('Apps/Git/cmd/git', true); file('Apps/Git/cmd/git.exe'); file('Apps/Git/bin/bash.exe');
  assert.ok(run({ pathDirs: [...sys32, 'Apps/Git/cmd'] }).includes(`found: ${appsBash}\n`), 'the bin\\bash.exe beside the git on PATH');
});

function hasPwsh() {
  const r = cp.spawnSync('pwsh', ['-NoProfile', '-Command', '$PSVersionTable.PSVersion.Major'], { encoding: 'utf8' });
  return r.status === 0;
}

/** Minimal STORED (uncompressed) zip writer — enough for a fixture, and it needs no external binary.
 *  Deliberate: the product never shells out to `zip`, so neither should its tests. */
function writeStoredZip(dest, entries) {
  const zlib = require('zlib');
  const chunks = [];
  const central = [];
  let offset = 0;
  for (const [name, body] of entries) {
    const nameBuf = Buffer.from(name, 'utf8');
    const crc = zlib.crc32 ? zlib.crc32(body) : crc32(body);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); // local file header
    local.writeUInt16LE(20, 4); // version needed
    local.writeUInt16LE(0, 6); // flags
    local.writeUInt16LE(0, 8); // method 0 = stored
    local.writeUInt16LE(0, 10); // time
    local.writeUInt16LE(0x21, 12); // date (1980-01-01 is invalid; use a real one)
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(body.length, 18);
    local.writeUInt32LE(body.length, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28);
    chunks.push(local, nameBuf, body);
    const cd = Buffer.alloc(46);
    cd.writeUInt32LE(0x02014b50, 0);
    cd.writeUInt16LE(20, 4);
    cd.writeUInt16LE(20, 6);
    cd.writeUInt16LE(0, 8);
    cd.writeUInt16LE(0, 10);
    cd.writeUInt16LE(0, 12);
    cd.writeUInt16LE(0x21, 14);
    cd.writeUInt32LE(crc, 16);
    cd.writeUInt32LE(body.length, 20);
    cd.writeUInt32LE(body.length, 24);
    cd.writeUInt16LE(nameBuf.length, 28);
    cd.writeUInt32LE(offset, 42);
    central.push(cd, nameBuf);
    offset += local.length + nameBuf.length + body.length;
  }
  const cdBuf = Buffer.concat(central);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(entries.length, 8);
  end.writeUInt16LE(entries.length, 10);
  end.writeUInt32LE(cdBuf.length, 12);
  end.writeUInt32LE(offset, 16);
  fs.writeFileSync(dest, Buffer.concat([...chunks, cdBuf, end]));
}

function crc32(buf) {
  let c = ~0;
  for (const b of buf) {
    c ^= b;
    for (let k = 0; k < 8; k++) c = (c >>> 1) ^ (0xedb88320 & -(c & 1));
  }
  return (~c) >>> 0;
}

test('installers: every shell script parses (they are run via curl | bash)', () => {
  // Four of the five installers are bash and nothing in the pipeline parses them — a typo ships and
  // lands on whoever runs the documented one-liner. install.ps1 has its own parser test above.
  const root = path.resolve(__dirname, '../../..');
  const scripts = ['install.sh', 'scripts/bootstrap.sh', 'scripts/install-jetbrains.sh', 'scripts/sync-statusline.sh', 'packages/cli/statusline/install-statusline.sh'];
  for (const rel of scripts) {
    const r = cp.spawnSync('bash', ['-n', path.join(root, rel)], { encoding: 'utf8' });
    assert.equal(r.status, 0, `${rel} has a bash syntax error:\n${r.stderr}`);
  }
});

// ---------------------------------------------------------------------------
// Pane layout — pure, so every degradation is asserted rather than discovered.
// ---------------------------------------------------------------------------

const L = (cols, rows, over = {}) =>
  tui.resolveLayout({ cols, rows, minimized: new Set(), focus: 'traces', ...over });

test('layout: the computed thresholds are where the spec says they are', () => {
  // These numbers are the whole degradation story, so they are pinned rather than described. Two
  // columns now, not three: Traces (36, up from 30 — it stacks Map over it since the swap) + Detail
  // (36) + one seam = 73.
  assert.equal(L(73, 24).mode, 'wide', '73 columns is the exact minimum for both columns');
  assert.equal(L(72, 24).mode, 'stack', 'and 72 is one short');
  // The bottom dock opens once the column band still clears COL_FLOOR after the top band is carved.
  // Derived, not hard-coded: a structural change should move this number, not break the test.
  let opensAt = null;
  for (let r = 10; r <= 60 && opensAt === null; r++) if (L(120, r).boxes.some((b) => b.id === 'dashboards')) opensAt = r;
  assert.ok(opensAt !== null, 'the bottom dock opens at SOME height');
  assert.ok(!L(120, opensAt - 1).boxes.some((b) => b.id === 'dashboards'), `and not one row below (${opensAt - 1})`);
});

test('layout: panes tile the width exactly, with one seam between neighbours', () => {
  // An off-by-one here is invisible in a mockup and corrupts every frame, so it is checked by
  // arithmetic over a sweep rather than by eye at one width.
  // The band membership is derived from each pane's DOCK, exactly as the product derives it — a
  // test-side id list is how the first top-dock pane got silently swept into the band while this
  // test kept passing.
  const dockOf = (id) => tui.PANE_SPECS.find((p) => p.id === id).dock;
  for (let cols = 40; cols <= 200; cols += 1) {
    for (const rows of [24, 30, 36]) {
      const lay = L(cols, rows);
      // Map is excluded from the WIDTH walk exactly as the product's seam builder excludes it: it
      // stacks INSIDE Diff's column, and its own tiling is vertical — asserted right after.
      const band = lay.boxes.filter((b) => b.id !== 'map' && b.id !== 'prompts' && dockOf(b.id) !== 'top' && dockOf(b.id) !== 'bottom').sort((a, b) => a.rect.x - b.rect.x);
      if (!band.length) continue;
      assert.equal(band[0].rect.x, 0, `${cols}x${rows}: band starts at 0`);
      for (let i = 1; i < band.length; i++) {
        const prev = band[i - 1].rect;
        assert.equal(band[i].rect.x, prev.x + prev.w + 1, `${cols}x${rows}: exactly one seam column`);
      }
      const last = band[band.length - 1].rect;
      assert.equal(last.x + last.w, cols, `${cols}x${rows}: the band ends flush at the right edge`);
      for (const b of lay.boxes) assert.ok(b.rect.w > 0 && b.rect.h > 0, 'no zero-extent box');
      // The vertical tiling of the LEFT stack: Map over Traces share the column exactly, one seam row
      // between them (Map moved left over Traces). Same arithmetic, rotated.
      const mapBox = lay.boxes.find((b) => b.id === 'map');
      const tracesBox = lay.boxes.find((b) => b.id === 'traces');
      if (mapBox && tracesBox) {
        assert.equal(mapBox.rect.x, tracesBox.rect.x, `${cols}x${rows}: the left stack shares a left edge`);
        assert.equal(mapBox.rect.w, tracesBox.rect.w, `${cols}x${rows}: the left stack shares a width`);
        assert.equal(tracesBox.rect.y, mapBox.rect.y + mapBox.rect.h + 1, `${cols}x${rows}: exactly one seam row between Map and Traces`);
      }
      // The RIGHT stack mirrors it: Prompts over Diff, sharing the right column's edge and width, one
      // seam row between — the swap put the ask (Prompts) over the change it made (Diff).
      const promptsBox = lay.boxes.find((b) => b.id === 'prompts');
      const diffBox = lay.boxes.find((b) => b.id === 'detail');
      if (promptsBox && diffBox) {
        assert.equal(promptsBox.rect.x, diffBox.rect.x, `${cols}x${rows}: the right stack shares a left edge`);
        assert.equal(promptsBox.rect.w, diffBox.rect.w, `${cols}x${rows}: the right stack shares a width`);
        assert.equal(diffBox.rect.y, promptsBox.rect.y + promptsBox.rect.h + 1, `${cols}x${rows}: exactly one seam row between Prompts and Diff`);
      }
    }
  }
});

test('layout: the latch — growing the terminal never shrinks a pane', () => {
  // Without this, 27->28 rows takes Traces from 22 rows to 16: the panel lurches while the reader is
  // still dragging the edge. The runtime folds `forced` into `minimized`; only the reader clears it.
  // The sweep steps ONE row at a time because a real drag is continuous — a coarse sweep steps over
  // the exact boundary where the dock opens and reports a clean bill of health it did not earn.
  const sweep = (latch) => {
    const minimized = new Set();
    const seen = [];
    for (let rows = 8; rows <= 50; rows++) {
      const lay = tui.resolveLayout({ cols: 80, rows, minimized: latch ? minimized : new Set(), focus: 'traces' });
      // The PRODUCT's latch, not a re-implementation: folding `forced` in with two lines here would
      // keep passing against a runtime that had stopped latching altogether.
      if (latch) for (const id of tui.latchMinimized(minimized, lay)) minimized.add(id);
      // The BAND height, not the Traces box: Traces stacks under Prompts now (2026-08-17), so it is a
      // split sibling that rebalances as its neighbour grows — like Diff under Map. The latch's job is
      // the band never shrinking on grow (a folded strip staying folded); that is `colH`.
      seen.push({ rows, h: lay.colH });
    }
    const shrank = [];
    for (let i = 1; i < seen.length; i++) {
      if (seen[i].h < seen[i - 1].h) shrank.push({ at: seen[i].rows, from: seen[i - 1].h, to: seen[i].h });
    }
    return shrank;
  };

  // Positive control FIRST: prove the sweep can see a lurch before trusting it to report none.
  const unlatched = sweep(false);
  assert.ok(
    unlatched.length > 0,
    `the un-latched control must lurch somewhere, or this test proves nothing: ${JSON.stringify(unlatched)}`
  );

  assert.deepEqual(sweep(true), [], 'with the latch, growing never shrinks the band');
});

test('layout: zoom gives one full-extent pane, for every pane', () => {
  for (const id of tui.PANE_SPECS.map((p) => p.id)) {
    for (const [cols, rows] of [[80, 24], [120, 36], [100, 30], [60, 20], [200, 50]]) {
      const lay = tui.resolveLayout({ cols, rows, minimized: new Set(), zoom: id, focus: id });
      assert.equal(lay.boxes.length, 1, `zoom ${id} at ${cols}x${rows}: exactly one box`);
      assert.equal(lay.boxes[0].id, id);
      assert.equal(lay.boxes[0].rect.w, cols, 'full width');
      assert.equal(lay.boxes[0].rect.h, lay.bodyH, 'full body height');
    }
  }
});

test('layout: a pane that will not fit says what it would take', () => {
  const lay = L(60, 24);
  assert.ok(!lay.boxes.some((b) => b.id === 'detail'), 'Detail does not fit beside Traces at 60 columns');
  const b = lay.blocked.find((x) => x.pane === 'detail');
  assert.ok(b && b.need === 73, `it names the 73 columns it needs, got ${JSON.stringify(b)}`);
  const d = lay.blocked.find((x) => x.pane === 'dashboards');
  assert.ok(d && d.needRows === 23, `and Dashboards names its 23 body rows, got ${JSON.stringify(d)}`);
  // Every pane keeps its chip even when it has no box, so a minimized pane never loses its counter.
  assert.equal(lay.bar.length, tui.BAR_ENTRIES.length, 'every chip stays on the window bar, open or not');
});

test('layout: the window bar leads the frame, in the order the reader was promised', () => {
  const lay = L(140, 36);
  // Order, keys and titles together: the bar is the frame's table of contents, and every one of the
  // three is something a reader navigates by.
  // SIX chips over six panes: Agent leads (who is working, and the door back to the conversation —
  // renamed from 'Claude' in 0.10.0, since a driven session may be any ACP agent), and Map and Diff
  // are separate panes with a key each, stacked in the centre column. F1 to F3 are OAK's tabs, so the
  // four windows Review shows are F4 to F7, and the Agent strip and Dashboards, which it hides, F8 and F9.
  assert.deepEqual(
    lay.bar.map((c) => `F${c.key} ${c.title}`),
    ['F8 Agent', 'F4 Prompts', 'F5 Traces', 'F6 Map', 'F7 Diff', 'F9 Dashboards'],
    'left to right: the agent, what was asked, what it changed, the map of it, the diff, then everything else'
  );
  assert.deepEqual(lay.bar.map((c) => c.pane), ['claude', 'prompts', 'traces', 'map', 'detail', 'dashboards'],
    'and the middle chips are TWO REAL panes — Map above Diff (0.10.0), never faces of one');
  const f = tui.renderDashFrame(paneFixture(), { cols: 140, rows: 36, color: false });
  assert.match(f[0], /F8 .?Agent.*F4 .?Prompts.*F5 .?Traces.*F6 .?Map.*F7 .?Diff.*F9 .?Dashboards/, 'and row 0 draws it');
  assert.match(f[2], /fixture/, 'the session bar follows it — inside its navbar box (bar 0 · edge 1 · row 2 · edge 3)');
  // The digits belong to EDITS now, so no chip may advertise a bare one.
  assert.doesNotMatch(f[0], /(^|\s)[0-9]\s+.?(Prompts|Traces|Dashboards|Diff|Map)/, 'no chip claims a digit');

  // Exactly one chip is ever current — Map and Diff are separate panes now, so focusing either
  // lights ITS chip and only its chip, with no face plumbing left to disagree with the focus.
  for (const pane of ['map', 'detail']) {
    const l = tui.resolveLayout({ cols: 140, rows: 36, minimized: new Set(), focus: pane, tab: {} });
    const lit = l.bar.filter((c) => c.focused);
    assert.equal(lit.length, 1, `${pane}: one chip is marked`);
    assert.equal(lit[0].title, pane === 'map' ? 'Map' : 'Diff');
  }
});

test('layout: hit-testing reads the geometry the renderer drew from', () => {
  const lay = L(120, 36);
  for (const b of lay.boxes) {
    assert.deepEqual(tui.hitTest(lay, b.rect.x + 1, b.titleRow), { t: 'title', pane: b.id });
    for (const s of b.tabSpans) {
      const hit = tui.hitTest(lay, s.x, b.tabsRow);
      assert.deepEqual(hit, { t: 'tab', pane: b.id, index: s.index }, `tab ${s.label} is clickable where it is drawn`);
    }
    const inBody = tui.hitTest(lay, b.body.x + 3, b.body.y + 1);
    assert.equal(inBody && inBody.t, 'body');
    assert.equal(inBody.pane, b.id);
  }
  // The window bar: the chip focuses, the twig cell toggles minimize. Two targets, one chip.
  for (const chip of lay.bar) {
    assert.deepEqual(tui.hitTest(lay, chip.twigX, 0), { t: 'windowbar', pane: chip.pane, part: 'twig' });
    assert.deepEqual(tui.hitTest(lay, chip.x, 0), { t: 'windowbar', pane: chip.pane, part: 'chip' });
  }
  assert.equal(tui.hitTest(lay, 0, 1).part, 'session', 'row 1 is the session, sharing its line with the counts');
  assert.equal(tui.hitTest(lay, 0, 35).part, 'keys');
  assert.equal(lay.chrome.top, 2, 'two chrome rows above the body, not three');
});

test('layout: a pane with an action bar owns that row, and the mouse can reach every button', () => {
  // THE defect this redesign exists for. `makeBox` gave a tab-less pane `body.y = y + 1` while the
  // renderer drew Detail's navbar there, so `hitTest` called the button row body: every button was
  // painted where nothing was clickable, each body click landed one row off, and the pane composed
  // one line taller than its box — which the compositor dropped off the bottom.
  const st = paneFixture({
    diffPatch: '@@ -1,2 +1,3 @@\n keep\n-was\n+now\n',
    diffMeta: { id: 5, path: '/w/a.ts', added: 1, removed: 1, verb: 'Write' },
  });
  for (const cols of [80, 100, 120, 150, 200]) {
    const lay = tui.resolveLayout({ cols, rows: 36, minimized: new Set(), focus: 'detail', tab: {} });
    const box = lay.boxes.find((b) => b.id === 'detail');
    if (!box) continue;
    assert.equal(box.navRow, box.titleRow + 1, `${cols}: the bar sits under the title`);
    assert.equal(box.body.y, box.navRow + 1, `${cols}: and the body starts BELOW it`);
    assert.equal(box.body.h, box.rect.h - 2, `${cols}: two chrome rows are accounted for`);
    const btns = tui.detailNavButtons(box, st);
    assert.ok(btns.length > 0, `${cols}: some buttons are drawn`);
    for (const b of btns) {
      // Every cell the button occupies, not just its first column.
      for (const x of [b.x, b.x + b.w - 1]) {
        assert.deepEqual(tui.hitTest(lay, x, box.navRow), { t: 'nav', pane: 'detail' }, `${cols}: ${b.action} at col ${x}`);
      }
    }
  }
  // Positive control: the OLD geometry must fail this. A hand-built box with the pre-fix body offset
  // classifies the same row as body, which is exactly how the bug shipped through a green suite.
  const lay = tui.resolveLayout({ cols: 150, rows: 36, minimized: new Set(), focus: 'detail', tab: {} });
  const box = lay.boxes.find((b) => b.id === 'detail');
  const old = {
    ...lay,
    boxes: lay.boxes.map((b) => (b.id === 'detail' ? { ...b, navRow: -1, body: { ...b.body, y: b.titleRow + 1, h: b.rect.h - 1 } } : b)),
  };
  assert.equal(tui.hitTest(old, box.rect.x + 3, box.titleRow + 1).t, 'body', 'the un-fixed geometry calls the bar row body');
});

test('layout: the tab strip drops whole tabs and names the count, never clipping a label', () => {
  // Dashboards carries every "what else is going on" surface, so its strip is the long one; at narrow
  // widths some tabs cannot be drawn. A clipped tab name is the same defect as a clipped path, so the
  // strip drops whole tabs and SAYS how many it dropped.
  const all = tui.PANE_SPECS.find((p) => p.id === 'dashboards').tabs;
  let sawDrop = false;
  for (let cols = 20; cols <= 140; cols++) {
    for (const sel of [0, Math.floor(all.length / 2), all.length - 1]) {
      const lay = tui.resolveLayout({ cols, rows: 36, minimized: new Set(), focus: 'dashboards', tab: { dashboards: sel } });
      const d = lay.boxes.find((b) => b.id === 'dashboards');
      if (!d) continue;
      for (const s of d.tabSpans) {
        assert.equal(s.label, all[s.index], `cols=${cols}: label intact`);
      }
      assert.ok(d.tabSpans.some((s) => s.selected), `cols=${cols} sel=${sel}: the selected tab is always drawn`);
      // The "names the count" half, which no test ever asserted: what is hidden is REPORTED, and the
      // number is the truth rather than a decoration.
      const { pre, post } = d.tabMore;
      const drawn = d.tabSpans.length;
      const hidden = (pre ? pre.hidden : 0) + (post ? post.hidden : 0);
      assert.equal(drawn + hidden, all.length, `cols=${cols} sel=${sel}: drawn + hidden accounts for every tab`);
      if (pre) assert.equal(pre.hidden, d.tabSpans[0].index, 'the pre-count is how many precede the first drawn tab');
      if (hidden) sawDrop = true;
    }
  }
  assert.ok(sawDrop, 'the sweep must actually reach a width that drops tabs, or it proves nothing');
});

const paneFixture = (over = {}) => ({
  ...dashFixture(),
  panes: { minimized: new Set(), zoom: null, focus: 'traces', tab: {}, cursor: {}, scroll: {} },
  ...over,
});

test('tui: the Traces list is ordered by time or name — and defaults to time', () => {
  // A 546-file session is not read chronologically. `time` (the default) puts the most recently
  // edited file on top; `name` sorts the paths A→Z. (Superseded the earlier recent/path/churn set.)
  const edits = [
    { id: 1, file: '/w/zebra.ts',  rel: 'zebra.ts',  status: 'pending', ts: 3000, added: 1,   removed: 0 },
    { id: 2, file: '/w/alpha.ts',  rel: 'alpha.ts',  status: 'pending', ts: 2000, added: 900, removed: 5 },
    { id: 3, file: '/w/middle.ts', rel: 'middle.ts', status: 'pending', ts: 1000, added: 10,  removed: 0 },
  ];
  const order = (sort) => {
    const st = paneFixture({ views: { list: { edits } }, sort, panes: { minimized: new Set(), zoom: null, focus: 'traces', tab: {}, cursor: {}, scroll: {} } });
    const frame = tui.renderDashFrame(st, { cols: 150, rows: 34, color: false });
    // The FILE HEADERS, in the order they are drawn.
    return frame.flatMap((l) => (l.match(/\b(zebra|alpha|middle)\.ts\b/) || []).slice(1));
  };

  assert.deepEqual(order(undefined), ['zebra', 'alpha', 'middle'], 'the default is time — newest first');
  assert.deepEqual(order('time'), ['zebra', 'alpha', 'middle'], 'and `time` says so explicitly (ts 3000, 2000, 1000)');
  assert.deepEqual(order('name'), ['alpha', 'middle', 'zebra'], 'by name — path A→Z');
  // …and the two are NOT the same ordering by accident: give the alphabetically-first file the OLDEST
  // time, so time and name must disagree.
  const edits2 = [
    { id: 1, file: '/w/aaa.ts', rel: 'aaa.ts', status: 'pending', ts: 1000, added: 1,   removed: 0 },
    { id: 2, file: '/w/zzz.ts', rel: 'zzz.ts', status: 'pending', ts: 3000, added: 500, removed: 0 },
  ];
  const order2 = (sort) => {
    const st = paneFixture({ views: { list: { edits: edits2 } }, sort, panes: { minimized: new Set(), zoom: null, focus: 'traces', tab: {}, cursor: {}, scroll: {} } });
    return tui.renderDashFrame(st, { cols: 150, rows: 34, color: false })
      .flatMap((l) => (l.match(/\b(aaa|zzz)\.ts\b/) || []).slice(1));
  };
  assert.deepEqual(order2('name'), ['aaa', 'zzz'], 'name is alphabetical');
  assert.deepEqual(order2('time'), ['zzz', 'aaa'], 'time is not — the most recently edited leads');
});

test('panes: every frame fills the terminal exactly, at every size', () => {
  for (const cols of [60, 67, 80, 98, 100, 120, 160, 200]) {
    for (const rows of [10, 20, 24, 27, 28, 36, 50]) {
      for (const color of [false, true]) {
        const f = tui.renderDashFrame(paneFixture(), { cols, rows, color });
        assert.equal(f.length, rows, `${cols}x${rows} color=${color}: exactly ${rows} lines`);
        const over = f.map((l, i) => ({ i, w: tui.displayWidth(l) })).filter((x) => x.w > cols);
        assert.deepEqual(over, [], `${cols}x${rows} color=${color}: lines over budget ${JSON.stringify(over)}`);
      }
    }
  }
});

test('panes: a wrapped row reassembles to its row text, character for character', () => {
  // A row too wide for its pane wraps. If wrapping is lossy the reader sees a path that does not
  // exist and cannot tell — strictly worse than truncation, which at least announces itself. Two
  // real defects came out of this: a `join(' ')` that welded `handler.md` into `handle r.md`, and a
  // check that hard-coded the pane width one column short and blamed the renderer for its own cut.
  //
  // The assertion deliberately does NOT normalise whitespace. Squashing spaces out before comparing
  // makes `handle r.md` and `handler.md` identical — it would have passed the very bug that prompted
  // this test. A path has no spaces, so it must come back with none injected.
  const long = 'plans/there-s-a-very-long-directory-name/and-another-one/deeply-nested-file.ts';
  const shown = 'deeply-nested-file.ts'; // rowsFor leads with the basename now; no collision, so no path
  const st = paneFixture({
    views: { list: { edits: [{ id: 7, file: long, added: 12, removed: 3, state: 'pending', ts: 0 }] } },
  });
  const reassemble = (f, box) =>
    f
      .slice(box.body.y, box.body.y + box.body.h)
      .map((l) => l.slice(0, box.rect.w).replace(/\s+$/, ''))
      .map((l) => l.slice(1)) // drop the cursor gutter column, which is chrome, not content
      .map((l) => {
        const m = l.match(/^\s*▸(.*)$/); // a continuation contributes only its own text
        return m ? m[1] : l;
      })
      .join('');

  for (const cols of [60, 70, 80, 100, 120]) {
    const lay = tui.resolveLayout({ cols, rows: 30, minimized: new Set(), focus: 'traces' });
    const box = lay.boxes.find((b) => b.id === 'traces');
    if (!box) continue; // width from the LAYOUT, never a hand-written constant
    const got = reassemble(tui.renderDashFrame(st, { cols, rows: 30, color: false }), box);
    assert.ok(got.includes(shown), `cols=${cols}: the path must survive wrapping intact\n  want: ${shown}\n  got:  ${got}`);
  }

  // Positive control: the exact defect this guards against — rejoining hard-broken pieces with a
  // space — must fail the same `includes` check, or the assertions above prove nothing.
  const parts = tui.wrapVisible(shown, 20);
  assert.ok(parts.length > 1, 'the fixture really does wrap');
  assert.equal(parts.join(''), shown, 'wrapVisible itself is lossless for a space-free token');
  assert.ok(!parts.join(' ').includes(shown), 'and a space-rejoin corrupts it, so the check can fail');
});

test('panes: the selection is said ONCE, and stays legible with no colour at all', () => {
  // The row used to carry a `>` marker AND a colour band — one fact stated twice, on every list on
  // screen. Colour now carries it alone, and the marker is what is left when there is no colour.
  // The state glyph must survive either way: overwriting the row's first cell with the marker ate the
  // pending/kept/undone mark, which is the one thing the reader is there to act on.
  const st = paneFixture({ panes: { minimized: new Set(), zoom: null, focus: 'traces', tab: {}, cursor: { traces: 0 }, scroll: {} } });
  const lay = tui.resolveLayout({ cols: 120, rows: 30, minimized: new Set(), focus: 'traces', navBox: true }); // matches renderDashFrame's own resolve (boxed tier)
  const box = lay.boxes.find((b) => b.id === 'traces');

  // Row 0 is a FILE HEADER now (folded by default), so its cells lead with the fold arrow and THEN
  // the state glyph — the glyph still survives the cursor marker, which is this test's subject.
  // The pane is BOXED now (default): every content row opens with the │ left border, so the cursor
  // marker/gutter sits one column in from where the un-boxed pane put it.
  const plain = tui.renderDashFrame(st, { cols: 120, rows: 30, color: false })[box.body.y];
  assert.match(plain, /^│>[▸▾] [?+x✓✗]/, `no colour: border, marker, fold arrow, then state glyph, got ${JSON.stringify(plain.slice(0, 9))}`);

  const lit = tui.renderDashFrame(st, { cols: 120, rows: 30, color: 'truecolor' })[box.body.y];
  // The focused pane's box border is CORAL, so the row opens with a coloured `│` (not the dim one an
  // unfocused pane wears) before the band.
  assert.match(lit, /^\x1b\[[0-9;]*m│/, `the row opens with the coloured box border, got ${JSON.stringify(lit.slice(0, 14))}`);
  assert.ok(/\x1b\[7m/.test(lit), 'and with colour the focused row is a band');
  const visible = lit.replace(/\x1b\[[0-9;]*m/g, '');
  assert.match(visible, /^│ [▸▾] [?+x✓✗]/, `and the gutter is blank, not an arrow: ${JSON.stringify(visible.slice(0, 9))}`);

  // An UNFOCUSED pane paints NO band at all — the faint "context" band was tried and read as a
  // second selected item both times a user looked at it (N7, then N16). One selection on screen.
  const un = paneFixture({ panes: { minimized: new Set(), zoom: null, focus: 'detail', tab: {}, cursor: { traces: 0 }, scroll: {} } });
  const other = tui.renderDashFrame(un, { cols: 120, rows: 30, color: 'truecolor' })[box.body.y];
  assert.ok(!/^\x1b\[7m/.test(other) && !/^\x1b\[48;2;/.test(other) && !/^\x1b\[100m/.test(other),
    `an unfocused pane's cursor row carries no band, got ${JSON.stringify(other.slice(0, 14))}`);
});

test('panes: a size that cannot hold a window says what it would take', () => {
  const f = tui.renderDashFrame(paneFixture(), { cols: 60, rows: 24, color: false });
  const status = f[f.length - 3];
  assert.match(status, /Diff needs 73 cols/, 'the status row names the cost, rather than the window just being gone');
  // And the window keeps its chip on the bar, so its jump key and counter never disappear.
  assert.match(f[0], /F7 .?Diff/, 'the Diff pane keeps its chip when minimized');
});

test('panes: zoom announces itself, and names the edit it is showing', () => {
  const st = paneFixture({
    panes: { minimized: new Set(), zoom: 'detail', focus: 'detail', tab: {}, cursor: {}, scroll: {} },
    diffPatch: '@@ -1,2 +1,3 @@\n keep\n-was\n+now\n',
    diffMeta: { id: 5, path: '/w/pkg/src/a.ts', added: 1, removed: 1, verb: 'Write' },
  });
  const f = tui.renderDashFrame(st, { cols: 120, rows: 30, color: false });
  assert.match(f[0], /ZOOM Diff/, 'a zoom that is not announced leaves "why can I only see one thing" unanswered');
  // Full screen is where the surrounding list is GONE, so the status row becomes the edit's address.
  assert.match(f[f.length - 3], /edit #5 · \/w\/pkg\/src\/a\.ts/, 'the status row names the edit and its whole path');
  // And the path is never cut to fit: a narrow frame drops to a shorter form rather than a false one.
  // Sweeping every width also proves the ladder never emits a path that was trimmed to fit.
  for (let cols = 12; cols <= 60; cols++) {
    const bar = tui.renderDashFrame(st, { cols, rows: 30, color: false })[27].trimEnd();
    assert.ok(
      /^edit #5( · (\/w\/pkg\/src\/a\.ts|pkg\/src\/a\.ts))?$/.test(bar) || bar === '',
      `no truncated path at ${cols} cols, got ${JSON.stringify(bar)}`
    );
  }
  // A zoom is the reader closing the other panes on purpose, so nothing may report what they "need".
  assert.doesNotMatch(f[f.length - 3], /needs \d+ (cols|body rows)/, 'a zoom does not price the panes it hid');
});

test('dashframe: an overlay with a cursor is a picker, one without is a reader', () => {
  // The runtime distinguishes the two by `cursor`, and dispatches Enter differently for each. If a
  // reader-overlay ever grew a cursor it would silently become selectable, so the contract is pinned
  // here: the rendered picker marks exactly one row, and the reader marks none.
  const lines = [' one', ' two', ' three'];
  const reader = tui.renderDashFrame(dashFixture({ overlay: { title: 'settings', lines, scroll: 0 } }), { cols: 60, rows: 10, color: false });
  assert.equal(reader.filter((l) => l.startsWith('>')).length, 0, 'a reader overlay marks no row');
  const picker = tui.renderDashFrame(dashFixture({ overlay: { title: 'menu', lines, scroll: 0, cursor: 1 } }), { cols: 60, rows: 10, color: false });
  assert.equal(picker.filter((l) => l.startsWith('>')).length, 1, 'a picker marks exactly one');
});

test('dashframe: a WRAPPED row does not move the selection to a different row', () => {
  // The overlay expands each logical line into as many visual lines as it needs, then marked the
  // cursor by comparing it against a position in that EXPANDED list — while `cursor` indexes the
  // logical ones. Every wrap above the cursor shifted the highlight down by one, so the reader
  // arrowed onto "three" and the frame highlighted "two". It stayed hidden while every row fit on one
  // line, which is exactly what stopped being true when the session picker grew its cost columns.
  const long = ` ${'wide '.repeat(20)}`; // comfortably past `cols`, so it wraps
  const lines = [long, ' two', ' three'];
  const at = (cursor) => {
    const f = tui.renderDashFrame(dashFixture({ overlay: { title: 'menu', lines, scroll: 0, cursor } }),
      { cols: 40, rows: 14, color: false });
    return f.filter((l) => l.startsWith('>')).map((l) => l.slice(1).trim());
  };
  // Positive control: without a wrap the mapping was already right, so the fixture has to wrap at all.
  const flat = tui.renderDashFrame(dashFixture({ overlay: { title: 'menu', lines, scroll: 0, cursor: 0 } }),
    { cols: 40, rows: 14, color: false });
  assert.ok(flat.filter((l) => l.trim()).length > lines.length + 1, 'the fixture must actually wrap');

  assert.deepEqual(at(1), ['two'], 'the cursor lands on the row it indexes, not one displaced by the wrap');
  assert.deepEqual(at(2), ['three'], 'and stays correct further down the list');
  // The wrapped row itself is marked across ALL of its visual lines, so a selection reads as one block
  // rather than as a highlighted fragment with an unhighlighted tail.
  assert.ok(at(0).length > 1, `a wrapped selection marks every line it occupies, got ${at(0).length}`);
});

test('dashframe: an open filter is visible before a single character is typed', () => {
  // The keys row used to print the prompt only when the buffer was non-empty, so pressing `/` looked
  // identical to normal mode. An invisible mode that swallows keystrokes is indistinguishable from a
  // frozen dashboard — and in the runtime those keystrokes were reaching `a`(keep) and `u`(undo).
  const keys = (over) => {
    const f = tui.renderDashFrame(dashFixture(over), { cols: 100, rows: 20, color: false });
    return f[f.length - 1].trim();
  };
  assert.equal(keys({ filterOpen: true }), '/_', 'the prompt appears the moment the mode opens');
  assert.equal(keys({ filterOpen: true, filter: 'readme' }), '/readme_', 'and carries a caret while typing');
  assert.equal(keys({ filterOpen: false, filter: 'readme' }), '/readme', 'a applied filter shows without the caret');
  assert.notEqual(keys({}), keys({ filterOpen: true }), 'normal mode and filter mode never render the same');
});

test('dashframe: a pending confirmation states the verb, the real count, and the answer keys', () => {
  const f = tui.renderDashFrame(
    dashFixture({ confirm: { verb: 'undo', ids: [1, 2, 3], label: 'every row listed' } }),
    { cols: 100, rows: 20, color: false }
  );
  const status = f[f.length - 3].trim();
  assert.match(status, /undo 3 edit\(s\)/, 'the REAL count, so a bulk revert is never a surprise');
  assert.match(status, /\[y\/n\]/, 'and the keys that answer it — which the runtime must actually bind');
});

test('fscache: the shared text layer sees an append, and never serves a stale transcript', () => {
  // The whole point of this layer is that ten derivations read one transcript once instead of dozens
  // of times. That is only safe if a GROWING file — the live-session case, which is the case the
  // dashboard exists for — is never served from cache after it changes. The stamp is
  // (mtimeMs:size:ino), and size moves on append, so this must hold.
  const fs = require('fs');
  const os = require('os');
  const path = require('path');
  const f = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'obs-fscache-')), 't.jsonl');

  fs.writeFileSync(f, 'one\ntwo\n');
  const first = core.readLines(f);
  assert.deepEqual(first, ['one', 'two', ''], 'reads the file');

  // Positive control: a SECOND read with no change must come from the cache, or this test cannot
  // distinguish "invalidated correctly" from "never cached at all". Counted at the disk, because two
  // fresh reads of an unchanged file return equal strings too.
  const read = fs.readFileSync; let loads = 0;
  fs.readFileSync = function (p, ...args) { if (String(p) === f) loads++; return read.call(this, p, ...args); };
  try { core.readText(f); core.readText(f); } finally { fs.readFileSync = read; }
  assert.equal(loads, 0, 'unchanged file is served from cache');

  fs.appendFileSync(f, 'three\n');
  const after = core.readLines(f);
  assert.ok(after.includes('three'), `an append must be visible, got ${JSON.stringify(after)}`);
  assert.equal(after.length, first.length + 1, 'exactly one line more');

  // And a truncation/replacement (a GC'd or rewritten transcript) must not serve the longer text.
  fs.writeFileSync(f, 'only\n');
  assert.deepEqual(core.readLines(f), ['only', ''], 'a shrunken file is re-read, not served long');

  fs.rmSync(path.dirname(f), { recursive: true, force: true });
});

test('comments: line comments on a pending edit batch into ONE prompt, delivered ONCE (the sent ledger)', () => {
  // The review-comment loop: mark up pending edits, hand them all back as one prompt, and never
  // send the same note twice. Anchored on the review-unit id + a line; DRAFTED, never auto-sent.
  freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const cwd = tmpWork();
  const S = 'cmtSess';
  const A = path.join(cwd, 'a.ts');
  const B = path.join(cwd, 'b.ts');
  seedEdit(S, A, 'line1\nline2\nline3\n', 'LINE1\nline2\nLINE3\n');
  seedEdit(S, B, null, 'new file\ncontent\n');
  const units = core.reviewEdits(S);
  const ua = units.find((r) => r.file === A).id;
  const ub = units.find((r) => r.file === B).id;

  const c1 = core.addComment(S, { unit: ua, line: 1, text: 'rename LINE1' });
  const c2 = core.addComment(S, { unit: ua, line: 3, text: 'handle the empty case' });
  const c3 = core.addComment(S, { unit: ub, text: 'this whole file needs a header' }); // line 0 = file-level
  assert.ok(c1 && c2 && c3, 'three comments added');
  assert.equal(core.addComment(S, { unit: ua, line: 1, text: '   ' }), null, 'empty text is rejected');
  assert.equal(core.addComment(S, { unit: 99999, line: 1, text: 'x' }), null, 'an unknown unit is rejected');
  assert.equal(core.pendingCommentCount(S), 3);
  assert.deepEqual(
    core.listComments(S).map((c) => [core.relPath(cwd, c.file), c.line]),
    [['a.ts', 1], ['a.ts', 3], ['b.ts', 0]],
    'listed by file, then line',
  );

  const p1 = core.composeCommentPrompt(S, { cwd });
  assert.ok(p1, 'a prompt is composed');
  assert.equal(p1.ids.length, 3);
  assert.match(p1.text, /3 review comment\(s\) on 2 files/, 'the {count} and {file} tokens');
  assert.match(p1.text, /a\.ts:/, 'file-grouped');
  assert.match(p1.text, /rename LINE1/, 'the human comment rides');
  assert.match(p1.text, /`LINE1`/, "the commented line's current content is quoted for context");

  // POSITIVE CONTROL: compose does NOT consume — a second compose still returns them (delivery is the
  // caller's, so a failed hand-off never spends a comment).
  assert.equal(core.composeCommentPrompt(S, { cwd }).ids.length, 3, 'compose alone never marks sent');
  core.markCommentsSent(S, p1.ids);
  assert.equal(core.pendingCommentCount(S), 0, 'the ledger recorded them');
  assert.equal(core.composeCommentPrompt(S, { cwd }), null, 'nothing unsent → no prompt (never re-sends)');

  const c4 = core.addComment(S, { unit: ua, line: 2, text: 'and this line too' });
  const p2 = core.composeCommentPrompt(S, { cwd });
  assert.deepEqual(p2.ids, [c4.id], 'only the new unsent comment batches');
  assert.doesNotMatch(p2.text, /rename LINE1/, 'the already-sent ones never ride again');
  core.markCommentsSent(S, p2.ids);

  // Scope to one file.
  core.addComment(S, { unit: ua, line: 1, text: 'A note' });
  core.addComment(S, { unit: ub, text: 'B note' });
  assert.match(core.composeCommentPrompt(S, { cwd, file: A }).text, /A note/);
  assert.doesNotMatch(core.composeCommentPrompt(S, { cwd, file: A }).text, /B note/, 'a file scope excludes the other file');

  assert.ok(core.removeComment(S, core.listComments(S, { unsentOnly: true })[0].id), 'a comment can be removed');
  assert.ok(core.clearComments(S) >= 1, 'clear empties the rest');
  assert.equal(core.readComments(S).length, 0);

  // GC POSITIVE CONTROL: authored comments are NOT a hashed cache payload, so the map sweep spares them.
  core.addComment(S, { unit: ua, line: 1, text: 'survive the GC' });
  core.pruneStaleMaps(S);
  assert.equal(core.pendingCommentCount(S), 1, 'the comment store survives a cache sweep (authored, never reaped)');
});

test('comments: a comment the store cannot save fails loudly — core throws, `oak comment add` exits 1 — and is never reported as added (0.11.0)', () => {
  // The write was "best effort": a failed one was swallowed while addComment returned the comment, so `oak comment add`
  // printed its id and the comment was gone at the next read.
  const home = freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const S = 'cmt-unsaved';
  seedEdit(S, path.join(tmpWork(), 'a.ts'), 'a\n', 'b\n');
  const unit = core.reviewEdits(S)[0].id;
  // A folder takes the file's name, so the write fails as a full disk would fail it: where comments live now, and among
  // the caches, where an earlier build wrote them.
  const places = [core.storeDir(S), path.join(core.rootDir(), 'changemap-cache', S)];
  for (const dir of places) fs.mkdirSync(path.join(dir, 'comments.json', 'taken'), { recursive: true });
  assert.throws(() => core.addComment(S, { unit, text: 'lost' }), /could not be saved/, 'core says the comment was not saved');
  const r = cp.spawnSync(process.execPath, [CLI, 'comment', 'add', '--session', S, '--edit', String(unit), '--text', 'lost too', '--json'],
    { env: { ...process.env, HOME: home, USERPROFILE: home }, encoding: 'utf8' });
  assert.equal(r.status, 1, `oak comment add fails: ${r.stdout}${r.stderr}`);
  assert.match(r.stderr, /oak: .*could not be saved/, 'and says why');
  assert.equal(r.stdout, '', 'with no comment printed as added');
  for (const dir of places) fs.rmSync(path.join(dir, 'comments.json'), { recursive: true });
  // Control: with the name free again, the comment is saved, and only it.
  assert.ok(core.addComment(S, { unit, text: 'saved' }));
  assert.deepEqual(core.listComments(S).map((c) => c.text), ['saved'], 'the failed writes saved nothing');
});

test('comments: a delivered prompt whose comments cannot be marked sent says it was sent — `oak prompt --comment-ids`, `oak comment send` (0.11.0)', { skip: process.platform === 'win32' && 'a POSIX socket stands in for herdr' }, async (t) => {
  // The mark can fail now (the session's lock, a write that fails), after the prompt went out. Said as "could not be
  // saved", JetBrains read the exit as an undelivered prompt and offered the draft to send again.
  const home = freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const S = 'cmt-sent-unmarked';
  seedEdit(S, path.join(tmpWork(), 'a.ts'), 'a\n', 'b\n');
  const c = core.addComment(S, { unit: core.reviewEdits(S)[0].id, text: 'rename it' });
  // Read where an earlier build kept them, a folder where they live now: the comments read, and the mark's write fails.
  const own = path.join(core.storeDir(S), 'comments.json'), legacy = path.join(core.rootDir(), 'changemap-cache', S, 'comments.json');
  fs.mkdirSync(path.dirname(legacy), { recursive: true });
  fs.renameSync(own, legacy);
  fs.mkdirSync(path.join(own, 'taken'), { recursive: true });
  // A herdr that runs the session in a pane and takes its prompts.
  const { version, protocol } = require('../dist/herdr-lock').HERDR_LOCK;
  const sock = path.join(tmpDir('fake-herdr-'), 'h.sock');
  const delivered = [];
  const server = require('net').createServer((s) => {
    let buf = '';
    s.on('data', (d) => {
      buf += d;
      if (!buf.includes('\n')) return;
      const req = JSON.parse(buf.slice(0, buf.indexOf('\n')));
      if (req.method === 'agent.prompt') delivered.push(req.params.text);
      const result = req.method === 'session.snapshot'
        ? { type: 'session_snapshot', snapshot: { version, protocol, panes: [{ pane_id: 'p1', agent_session: { value: S }, agent_status: 'idle' }], agents: [{ name: 'a1', pane_id: 'p1' }] } }
        : { type: 'ok' };
      s.end(JSON.stringify({ id: req.id, result }) + '\n');
    });
  });
  await new Promise((r) => server.listen(sock, r));
  t.after(() => server.close());
  const run = (args) => new Promise((resolve) => {
    const p = cp.spawn(process.execPath, [CLI, ...args], { env: { ...process.env, HOME: home, USERPROFILE: home, HERDR_SOCKET_PATH: sock } });
    let out = '', err = '';
    p.stdout.on('data', (d) => (out += d));
    p.stderr.on('data', (d) => (err += d));
    p.on('close', (code) => resolve({ code, out, err }));
  });
  const prompt = await run(['prompt', '--session', S, '--text', 'fix it', '--comment-ids', c.id, '--json']);
  assert.deepEqual(delivered, ['fix it'], `control: the prompt was delivered: ${prompt.err}`);
  assert.equal(prompt.code, 1, 'the mark failed');
  assert.equal(JSON.parse(prompt.out).sent, true);
  assert.match(prompt.err, /^oak: sent to the agent, but its review comments were not marked sent, so the next send drafts them again: .*could not be saved/, 'and the reason says the prompt was sent');
  const send = await run(['comment', 'send', '--session', S]);
  assert.equal(delivered.length, 2, `control: sent again: ${send.err}`);
  assert.equal(send.code, 1);
  assert.match(send.out, /^Sent to the agent\./);
  assert.match(send.err, /^oak: sent to the agent, but its review comments were not marked sent/, '`oak comment send` says the same');
  // Control: with the folder gone, the mark lands, and nothing is drafted again.
  fs.rmSync(own, { recursive: true });
  const marked = await run(['comment', 'send', '--session', S, '--json']);
  assert.equal(marked.code, 0, marked.err);
  assert.ok(core.listComments(S).every((x) => x.sentAt), 'marked sent');
});

// Nothing sent is a draft kept, said by the exit status in every output mode (75), so an agent driving another agent can
// tell; 0 only when it went out. A quote without --send is a draft by design, and exits 0 (0.11.0).
test('prompts: nothing sent keeps a draft and exits 75, in every output mode; sent exits 0 — `oak prompt`, `oak comment send`, `oak quote --send`', { skip: process.platform === 'win32' && 'a POSIX socket stands in for herdr' }, async (t) => {
  const home = freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const S = 'draft-exit';
  seedEdit(S, path.join(tmpWork(), 'a.ts'), 'a\n', 'b\n');
  core.addComment(S, { unit: core.reviewEdits(S)[0].id, text: 'rename it' });
  const transcript = path.join(home, '.claude', 'projects', '-work', `${S}.jsonl`);
  fs.mkdirSync(path.dirname(transcript), { recursive: true });
  fs.writeFileSync(transcript, [
    { type: 'user', cwd: '/work', sessionId: S, message: { role: 'user', content: 'rename it' } },
    { type: 'assistant', cwd: '/work', sessionId: S, message: { id: 'm1', role: 'assistant', model: 'claude-opus-4-8', content: [{ type: 'text', text: 'Renamed it.' }], usage: { input_tokens: 1, output_tokens: 1 } } },
  ].map((r) => JSON.stringify(r)).join('\n') + '\n');
  // A herdr whose pane runs the session, blocked on a dialog until the test says otherwise.
  const { version, protocol } = require('../dist/herdr-lock').HERDR_LOCK;
  const sock = path.join(tmpDir('fake-herdr-'), 'h.sock');
  const delivered = [];
  let pane = 'blocked';
  const server = require('net').createServer((s) => {
    let buf = '';
    s.on('data', (d) => {
      buf += d;
      if (!buf.includes('\n')) return;
      const req = JSON.parse(buf.slice(0, buf.indexOf('\n')));
      if (req.method === 'agent.prompt') delivered.push(req.params.text);
      const result = req.method === 'session.snapshot'
        ? { type: 'session_snapshot', snapshot: { version, protocol, panes: [{ pane_id: 'p1', agent_session: { value: S }, agent_status: pane }], agents: [{ name: 'a1', pane_id: 'p1' }] } }
        : { type: 'ok' };
      s.end(JSON.stringify({ id: req.id, result }) + '\n');
    });
  });
  await new Promise((r) => server.listen(sock, r));
  t.after(() => server.close());
  // The clipboard a kept draft goes to: stubs that record what they were given, first on PATH, so a run never reaches
  // the person's own clipboard.
  const clipBin = tmpDir('clip-');
  const clipLog = path.join(clipBin, 'clip.log');
  for (const name of ['wl-copy', 'xclip', 'xsel', 'pbcopy']) fs.writeFileSync(path.join(clipBin, name), `#!/bin/sh\ncat >> '${clipLog}'\nprintf '\\n--\\n' >> '${clipLog}'\n`, { mode: 0o755 });
  const run = (args) => new Promise((resolve) => {
    const p = cp.spawn(process.execPath, [CLI, ...args], { env: { ...process.env, HOME: home, USERPROFILE: home, HERDR_SOCKET_PATH: sock, PATH: `${clipBin}${path.delimiter}${process.env.PATH}` } });
    let out = '', err = '';
    p.stdout.on('data', (d) => (out += d));
    p.stderr.on('data', (d) => (err += d));
    p.on('close', (code) => resolve({ code, out, err }));
  });
  for (const args of [['prompt', '--session', S, '--text', 'fix it'], ['comment', 'send', '--session', S], ['quote', '--session', S, '--send']]) {
    for (const json of [false, true]) {
      const r = await run(json ? [...args, '--json'] : args);
      assert.equal(r.code, 75, `${args.join(' ')}${json ? ' --json' : ''}: ${r.out}${r.err}`);
      if (json) assert.equal(JSON.parse(r.out).sent, false);
      else assert.match(r.err, /^Draft retained: The agent is blocked/);
    }
  }
  assert.deepEqual(delivered, [], 'control: nothing was sent');
  assert.equal(fs.readFileSync(clipLog, 'utf8').split('\n--\n').filter((x) => x === 'fix it').length, 2, 'each kept draft of the prompt went to the clipboard');
  assert.equal((await run(['quote', '--session', S, '--json'])).code, 0, 'a quote not asked to send is a draft, and no failure');
  pane = 'idle';
  const sent = await run(['prompt', '--session', S, '--text', 'fix it', '--json']);
  assert.equal(sent.code, 0, sent.err);
  assert.deepEqual(delivered, ['fix it']);
});

/**
 * Two writers of one file at once, the first held after it read the file and before its write lands (its rename onto
 * a file named `name`), the second started meanwhile: resolves with both runs. Without a lock, the second reads, writes
 * and exits while the first is held, and the first's write then drops what the second added. With one, the second
 * waits for the first, which is let go once the second has exited or 2.5 s have passed.
 */
async function raceHeldWriter(name, first, second) {
  const box = tmpDir('held-writer-');
  const hold = path.join(box, 'hold.cjs');
  fs.writeFileSync(hold, `const fs = require('fs'), path = require('path'), rename = fs.renameSync;
fs.renameSync = function (a, b, ...r) {
  if (path.basename(String(b)) === ${JSON.stringify(name)}) {
    fs.writeFileSync(process.env.HELD, '');
    for (const end = Date.now() + 15000; !fs.existsSync(process.env.GO) && Date.now() < end;) Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 10);
  }
  return rename.call(this, a, b, ...r);
};\n`);
  const env = { ...process.env, HELD: path.join(box, 'held'), GO: path.join(box, 'go') };
  const run = (args, held) => new Promise((resolve) => {
    const c = cp.spawn(process.execPath, [...(held ? ['--require', hold] : []), ...args], { env, stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    c.stdout.on('data', (d) => (out += d));
    c.stderr.on('data', (d) => (out += d));
    c.on('close', (code) => resolve({ code, out }));
  });
  const a = run(first, true);
  for (const end = Date.now() + 15000; !fs.existsSync(env.HELD) && Date.now() < end;) await new Promise((r) => setTimeout(r, 10));
  assert.ok(fs.existsSync(env.HELD), `control: the first writer has read ${name} and holds its write`);
  const b = run(second, false);
  await Promise.race([b, new Promise((r) => setTimeout(r, 2500))]);
  fs.writeFileSync(env.GO, '');
  return Promise.all([a, b]);
}

test('comments: two writers at once keep both comments — each change is made under the session\'s lock (0.11.0)', async () => {
  freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const S = 'cmt-race';
  seedEdit(S, path.join(tmpWork(), 'a.ts'), 'a\n', 'b\n');
  const unit = String(core.reviewEdits(S)[0].id);
  const add = (text) => [CLI, 'comment', 'add', '--session', S, '--edit', unit, '--text', text];
  const runs = await raceHeldWriter('comments.json', add('first'), add('second'));
  for (const r of runs) assert.equal(r.code, 0, r.out);
  assert.deepEqual(core.listComments(S).map((c) => c.text).sort(), ['first', 'second'], 'neither write drops the other\'s comment');
  // A removal and a mark-sent take the same lock: one held while the other runs keeps both changes.
  const [kept, gone] = core.listComments(S).map((c) => c.id);
  const [x, y] = await raceHeldWriter('comments.json', [CLI, 'comment', 'rm', '--session', S, '--id', gone], [CLI, 'comment', 'mark-sent', '--session', S, '--ids', kept]);
  assert.equal(x.code, 0, x.out);
  assert.equal(y.code, 0, y.out);
  assert.deepEqual(core.listComments(S).map((c) => [c.id, !!c.sentAt]), [[kept, true]], 'the removal and the mark both stand');
});

test('comments: they live in the session\'s own folder, are read where an earlier build leaves them until a change carries them over, and go with the session (0.11.0)', () => {
  // Authored, they were filed among the derived caches (changemap-cache), which nothing replicates or treats as the
  // session's own data.
  freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  const S = 'cmt-where';
  const F = path.join(tmpWork(), 'a.ts');
  seedEdit(S, F, 'a\n', 'b\n');
  const unit = core.reviewEdits(S)[0].id;
  const own = path.join(core.storeDir(S), 'comments.json');
  const legacy = path.join(core.rootDir(), 'changemap-cache', S, 'comments.json');
  fs.mkdirSync(path.dirname(legacy), { recursive: true });
  fs.writeFileSync(legacy, JSON.stringify({ version: 1, comments: [{ id: 'c-earlier', unit, pair: 'x', file: F, line: 0, text: 'from before', createdAt: 1 }] }));
  assert.deepEqual(core.listComments(S).map((c) => c.text), ['from before'], 'the earlier location is read while the session has no file of its own');
  assert.ok(!fs.existsSync(own), 'and reading writes nothing');
  core.addComment(S, { unit, text: 'new' });
  assert.deepEqual(JSON.parse(fs.readFileSync(own, 'utf8')).comments.map((c) => c.text), ['from before', 'new'], 'the next write lands in the session\'s folder, carrying the earlier one');
  assert.ok(!fs.existsSync(legacy), 'and the earlier copy goes, so a comment removed or sent since never comes back');
  // An older build still running beside this one (an editor not yet reloaded) writes there again, holding what it added
  // since. Left unread once the session had its own file, those comments were never shown again: they are read beside
  // the session's own (which wins for an id both hold), and the next change carries them over and removes that file.
  let olderAt = Date.now() + 1000; // after 'new': listComments orders by file, line, then creation
  const older = (id, text) => ({ id, unit, pair: 'x', file: F, line: 0, text, createdAt: olderAt++ });
  const olderWrites = (...comments) => { // as the older build writes it: a temporary file renamed over the old one
    fs.writeFileSync(`${legacy}.older.tmp`, JSON.stringify({ version: 1, comments }));
    rename(`${legacy}.older.tmp`, legacy);
  };
  const rename = fs.renameSync;
  olderWrites(older('c-older', 'from an older build'), older('c-earlier', 'a stale copy'));
  assert.deepEqual(core.listComments(S).map((c) => c.text), ['from before', 'new', 'from an older build'], 'shown beside the session\'s own');
  assert.equal(core.removeComment(S, 'no-such-comment'), false);
  assert.ok(fs.existsSync(legacy), 'a change that writes nothing carries nothing, so removes nothing');
  core.addComment(S, { unit, text: 'later' });
  assert.deepEqual(JSON.parse(fs.readFileSync(own, 'utf8')).comments.map((c) => c.text), ['from before', 'new', 'from an older build', 'later'],
    'carried into the session\'s own file by the next change');
  assert.ok(!fs.existsSync(legacy), 'which removes the file it carried them from');
  // One the older build writes while a change is being made (it takes no lock) is left there, for the next one to carry.
  olderWrites(older('c-mid', 'older, before the change'));
  fs.renameSync = function (a, b, ...rest) {
    const out = rename.call(this, a, b, ...rest);
    if (String(b) === own) { fs.renameSync = rename; olderWrites(older('c-mid', 'older, before the change'), older('c-during', 'older, during the change')); }
    return out;
  };
  try {
    core.removeComment(S, core.listComments(S).find((c) => c.text === 'later').id);
  } finally {
    fs.renameSync = rename;
  }
  assert.deepEqual(core.listComments(S).map((c) => c.text), ['from before', 'new', 'from an older build', 'older, before the change', 'older, during the change'],
    'the removal stands, and what the older build wrote meanwhile is kept');
  for (const id of ['c-older', 'c-mid', 'c-during']) assert.ok(core.removeComment(S, id));
  assert.ok(!fs.existsSync(legacy), 'carried over, then removed, by the next change');
  // A store move carries them, in the session's folder.
  const dest = path.join(tmpDir('cmt-move-'), 'observatory');
  assert.ok(core.moveStore(dest).moved);
  assert.ok(fs.existsSync(path.join(dest, S, 'comments.json')), 'moved with the session');
  assert.deepEqual(core.listComments(S).map((c) => c.text), ['from before', 'new']);
  // Deleting the session deletes them, from both places.
  core.removeSession(S);
  assert.ok(!fs.existsSync(path.join(dest, S)) && !fs.existsSync(path.join(dest, 'changemap-cache', S)), 'a deleted session takes its comments with it');
  assert.deepEqual(core.listComments(S), []);
});

test('store: hiding and restoring sessions at once keeps every change — the hidden list is changed under its lock, and stays a bare JSON array (0.11.0)', async () => {
  // `oak sessions --delete` and an `oak sync` pull both rewrite hidden-sessions.json from what they read: unlocked, the
  // one that wrote last dropped the other's change, so a deleted session came back or a restored one stayed hidden.
  freshHome();
  delete process.env.CLAUDE_CONFIG_DIR;
  core.hideSession('hidden-before');
  const file = path.join(core.rootDir(), 'hidden-sessions.json');
  const coreDist = path.resolve(__dirname, '../dist/index.js');
  const call = (verb, id) => ['-e', `require(${JSON.stringify(coreDist)}).${verb}(${JSON.stringify(id)})`];
  const hidden = await raceHeldWriter('hidden-sessions.json', call('hideSession', 'one'), call('hideSession', 'two'));
  for (const r of hidden) assert.equal(r.code, 0, r.out);
  assert.deepEqual(JSON.parse(fs.readFileSync(file, 'utf8')).sort(), ['hidden-before', 'one', 'two'], 'both hidden, and the file a bare array of ids');
  const restored = await raceHeldWriter('hidden-sessions.json', call('hideSession', 'three'), call('unhideSession', 'hidden-before'));
  for (const r of restored) assert.equal(r.code, 0, r.out);
  assert.deepEqual(JSON.parse(fs.readFileSync(file, 'utf8')).sort(), ['one', 'three', 'two'], 'the restore stands beside the hide made with it');
});

